INSERT INTO `calendar_events` (`calendar_event_id`, `owner_user_id`, `campus_id`, `visit_instance_id`, `logistics_item_id`, `source_type`, `title`, `description`, `location`, `start_at`, `end_at`, `timezone`, `is_all_day`, `recurrence_rule`, `visibility`, `status`, `created_at`, `created_by`, `updated_at`, `updated_by`, `deleted_at`, `deleted_by`) VALUES
	(1, 4, 1, 3005, NULL, 'VISIT', 'Lịch tiếp đoàn: Iberia Mobility Forum campus day', 'Sự kiện lịch gắn với campus HN. Host dùng để kiểm tra xung đột khi gán người phụ trách. Mục tiêu: Tổ chức một ngày giao lưu về mobility, startup và vai trò sinh viên trong dự án xanh.', 'HN meeting room / reception route', '2026-06-23 09:00:00', '2026-06-23 16:00:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'INTERNAL', 'ACTIVE', '2026-06-20 09:00:00', 4, '2026-08-08 17:05:08', NULL, NULL, NULL),
	(2, 18, 1, 3005, 7, 'LOGISTICS', 'Deadline hậu cần: Hậu cần khác cho Iberia Mobility Forum campus day', 'Nhắc deadline cho logistics item: Hậu cần khác cho Iberia Mobility Forum campus day. Trạng thái hiện tại cần kiểm tra trước giờ đoàn tới.', 'Gamma Room', '2026-06-23 08:00:00', '2026-06-23 08:30:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'INTERNAL', 'DONE', '2026-06-20 09:30:00', 17, '2026-08-08 17:05:08', 18, NULL, NULL),
	(3, 3, 1, NULL, NULL, 'DEADLINE', 'Mốc cần xử lý: Duyệt đơn VR-SC-HN-0001', 'Mốc hệ thống dùng cho reminder/notification, không phải sự kiện cá nhân tự do. Liên quan: Mốc cần xử lý: Duyệt đơn VR-SC-HN-0001', 'PEMS Dashboard', '2026-06-24 09:00:00', '2026-06-24 09:15:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'PRIVATE', 'ACTIVE', '2026-06-23 08:05:00', 3, '2026-08-08 17:05:08', NULL, NULL, NULL),
	(4, 2, 1, NULL, NULL, 'DEADLINE', 'Mốc cần xử lý: Theo dõi tiến độ đơn liên cơ sở VR-MC-HN-HCM-0001', 'Mốc hệ thống dùng cho reminder/notification, không phải sự kiện cá nhân tự do. Liên quan: Mốc cần xử lý: Theo dõi tiến độ đơn liên cơ sở VR-MC-HN-HCM-0001', 'PEMS Dashboard', '2026-06-24 10:00:00', '2026-06-24 10:15:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'PRIVATE', 'ACTIVE', '2026-06-23 09:05:00', 2, '2026-08-08 17:05:08', NULL, NULL, NULL),
	(5, 7, 1, NULL, NULL, 'PERSONAL', 'Student preparation notes', 'Sinh viên chuẩn bị checklist cá nhân cho vai trò buddy.', 'Library Study Corner', '2026-06-27 14:00:00', '2026-06-27 15:00:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'PRIVATE', 'ACTIVE', '2026-06-21 09:00:00', 7, NULL, NULL, NULL, NULL),
	(6, 10, 2, 3110, NULL, 'VISIT', 'Lịch tiếp đoàn: Before-visit mobility preparation', 'Sự kiện lịch gắn với campus HCM. Host dùng để kiểm tra xung đột khi gán người phụ trách. Mục tiêu: Chuẩn bị cuộc họp mobility xanh tại Hà Nội và TP.HCM.', 'HCM meeting room / reception route', '2026-07-01 09:00:00', '2026-07-01 12:00:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'INTERNAL', 'ACTIVE', '2026-06-20 09:40:00', 10, '2026-08-08 17:05:08', NULL, NULL, NULL),
	(99001, 10, 2, 9901, NULL, 'VISIT', 'Lịch tiếp đoàn: Visitor cancelled Hanoi-only campus tour due to visa delay', 'Sự kiện lịch gắn với campus HCM. Host dùng để kiểm tra xung đột khi gán người phụ trách. Mục tiêu: Đoàn khách hủy chặng Hà Nội do visa cấp chậm; campus chưa phát sinh người phụ trách tiếp đón.', 'HCM meeting room / reception route', '2026-08-15 09:00:00', '2026-08-15 11:30:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'INTERNAL', 'CANCELLED', '2026-07-31 23:04:48', 9, '2026-08-08 17:05:08', 202, NULL, NULL),
	(99002, 12, 3, 9902, NULL, 'VISIT', 'Lịch tiếp đoàn: Visitor cancelled HCM workshop after partner board reschedule', 'Sự kiện lịch gắn với campus DN. Host dùng để kiểm tra xung đột khi gán người phụ trách. Mục tiêu: Đối tác đổi lịch họp hội đồng quản trị nên người đăng ký hủy yêu cầu sau khi campus đã được duyệt.', 'DN meeting room / reception route', '2026-08-20 13:30:00', '2026-08-20 16:30:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'INTERNAL', 'CANCELLED', '2026-07-30 21:04:48', 11, '2026-08-08 17:05:08', 203, NULL, NULL),
	(99003, 154, 3, 9902, NULL, 'VISIT', 'Lịch tiếp đoàn: Visitor cancelled HCM workshop after partner board reschedule', 'Sự kiện lịch gắn với campus DN. Host dùng để kiểm tra xung đột khi gán người phụ trách. Mục tiêu: Đối tác đổi lịch họp hội đồng quản trị nên người đăng ký hủy yêu cầu sau khi campus đã được duyệt.', 'DN meeting room / reception route', '2026-08-20 13:30:00', '2026-08-20 16:30:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'PRIVATE', 'CANCELLED', '2026-07-30 22:04:48', 11, '2026-08-08 17:05:08', 203, NULL, NULL),
	(99004, 14, 4, 9903, NULL, 'VISIT', 'Lịch tiếp đoàn: Multi-campus request rejected because agenda scope was incomplete', 'Sự kiện lịch gắn với campus CT. Host dùng để kiểm tra xung đột khi gán người phụ trách. Mục tiêu: Staff Leader từ chối vì request multi-campus thiếu campus objective riêng và không đủ ngày chuẩn bị logistics liên cơ sở.', 'CT meeting room / reception route', '2026-08-17 10:00:00', '2026-08-17 13:30:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'INTERNAL', 'CANCELLED', '2026-07-31 20:04:48', 13, '2026-08-08 17:05:08', 210, NULL, NULL),
	(99005, 138, 4, 9903, 99002, 'LOGISTICS', 'Deadline hậu cần: Phòng họp CT cho Multi-campus request rejected because agenda scope was incomplete', 'Nhắc deadline cho logistics item: Phòng họp CT cho Multi-campus request rejected because agenda scope was incomplete. Trạng thái hiện tại cần kiểm tra trước giờ đoàn tới.', 'CT Hybrid Room', '2026-08-17 09:00:00', '2026-08-17 09:45:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'PRIVATE', 'CANCELLED', '2026-08-01 01:04:48', 137, '2026-08-08 17:05:08', 210, NULL, NULL),
	(99006, 12, 3, 9909, NULL, 'VISIT', 'Lịch tiếp đoàn: Closed multi-campus visit with media follow-up and feedback', 'Sự kiện lịch gắn với campus DN. Host dùng để kiểm tra xung đột khi gán người phụ trách. Mục tiêu: Chương trình đã kết thúc; Host hoàn tất hồ sơ, phản hồi và tài liệu công khai sau chuyến thăm.', 'DN meeting room / reception route', '2026-08-14 14:00:00', '2026-08-14 16:30:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'INTERNAL', 'ACTIVE', '2026-07-28 21:04:48', 11, '2026-08-08 17:05:08', NULL, NULL, NULL),
	(99007, 14, 4, 9910, NULL, 'VISIT', 'Lịch tiếp đoàn: Closed multi-campus visit with media follow-up and feedback', 'Sự kiện lịch gắn với campus CT. Host dùng để kiểm tra xung đột khi gán người phụ trách. Mục tiêu: Chương trình đã kết thúc; Host hoàn tất hồ sơ, phản hồi và tài liệu công khai sau chuyến thăm.', 'CT meeting room / reception route', '2026-08-11 10:30:00', '2026-08-11 13:30:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'INTERNAL', 'ACTIVE', '2026-07-28 23:04:48', 13, '2026-08-08 17:05:08', NULL, NULL, NULL),
	(99008, 4, 1, 9913, NULL, 'VISIT', 'Lịch tiếp đoàn: SeoulTech two-campus AI lab cancellation by visitor', 'Sự kiện lịch gắn với campus HN. Host dùng để kiểm tra xung đột khi gán người phụ trách. Mục tiêu: Chuỗi workshop AI lab tại HN và DN, có host và student support ở cả hai campus.', 'HN meeting room / reception route', '2026-08-10 09:30:00', '2026-08-10 13:00:00', 'Asia/Ho_Chi_Minh', 0, NULL, 'INTERNAL', 'CANCELLED', '2026-07-26 22:04:48', 3, '2026-08-08 17:05:08', 8, NULL, NULL),
