INSERT INTO `feedbacks` (`feedback_id`, `visit_request_id`, `visit_instance_id`, `feedback_type`, `submitted_by_user_id`, `submitter_role`, `submitter_context`, `submitter_name_snapshot`, `target_type`, `target_user_id`, `target_participant_id`, `target_guest_member_id`, `target_logistics_item_id`, `target_handover_id`, `target_department_id`, `target_role`, `target_context`, `target_name_snapshot`, `rating`, `comment`, `submitted_at`) VALUES
	(1, 1006, 3006, 'VISITOR_OVERALL', 8, 'VISITOR', 'Khách đại diện SeoulTech', 'Kim Min Jae', 'VISIT_INSTANCE', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Đánh giá tổng thể chuyến thăm', 'Chuyến thăm / đoàn tiếp đón', 5, 'Đoàn đánh giá cao cách host giải thích quy trình học tập và đưa khách đi đúng route. Điểm cần cải thiện là gửi trước bản đồ campus kèm vị trí đỗ xe.', '2026-06-15 18:30:00'),
	(2, 1007, 3007, 'HOST_LOGISTICS', 4, 'HOST', 'Host chính lễ ký kết', 'IC Staff Hà Nội', 'USER', 18, NULL, NULL, NULL, NULL, NULL, 'LOGISTICS', 'Phòng họp Auditorium A', 'Department Staff Cơ sở vật chất HN', 4, 'Department support phản hồi nhanh, nhưng thời lượng Q&A hơi ngắn so với số câu hỏi chuyên môn. Nên chuẩn bị thêm FAQ nội bộ cho các đoàn học thuật.', '2026-06-01 18:00:00'),
	(3, 1007, 3007, 'HOST_LOGISTICS', 4, 'HOST', 'Host chính lễ ký kết', 'IC Staff Hà Nội', 'USER', 18, NULL, NULL, NULL, NULL, NULL, 'LOGISTICS', 'Setup auditorium và service report', 'Department Staff Cơ sở vật chất HN', 5, 'Logistics chuẩn bị phòng và teabreak đúng giờ. Cần kiểm tra micro trước buổi vì một khách ở cuối phòng nghe chưa rõ.', '2026-06-01 18:10:00'),
