INSERT INTO `minutes` (`minutes_id`, `visit_instance_id`, `title`, `content`, `status`, `edit_locked_by`, `edit_locked_at`, `edit_lock_expires_at`, `edit_lock_token`, `row_version`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES
	(1, 3006, 'Biên bản HN - SeoulTech AI lab follow-up discussion', '<h2>Tóm tắt buổi làm việc</h2><p>Đoàn <strong>SeoulTech AI lab follow-up discussion</strong> làm việc tại FPT University Hà Nội với mục tiêu: Làm rõ các đầu việc hợp tác AI lab sau chuyến tham quan đầu tiên.</p><h3>Nội dung đã thống nhất</h3><ul><li>IC là đầu mối tổng hợp tài liệu và gửi follow-up.</li><li>Department phụ trách trả lời các câu hỏi chuyên môn trong 5 ngày làm việc.</li><li>Host cập nhật action item, feedback và trạng thái news trước khi đóng hồ sơ.</li></ul><blockquote>Nội dung biên bản phản ánh riêng mục tiêu, kết quả và đầu việc của campus trong chuyến thăm này.</blockquote>', 'SAVED', NULL, NULL, NULL, NULL, 2, '2026-06-15 12:30:00', 4, '2026-08-08 17:05:05', 4),
	(2, 3007, 'Biên bản HN - Porto AI Hub closed delegation', '<h2>Tóm tắt buổi làm việc</h2><p>Đoàn <strong>Porto AI Hub closed delegation</strong> làm việc tại FPT University Hà Nội với mục tiêu: Ký biên bản hợp tác ngắn hạn về seminar AI ứng dụng và trao đổi lecturer.</p><h3>Nội dung đã thống nhất</h3><ul><li>IC là đầu mối tổng hợp tài liệu và gửi follow-up.</li><li>Department phụ trách trả lời các câu hỏi chuyên môn trong 5 ngày làm việc.</li><li>Host cập nhật action item, feedback và trạng thái news trước khi đóng hồ sơ.</li></ul><blockquote>Nội dung biên bản phản ánh riêng mục tiêu, kết quả và đầu việc của campus trong chuyến thăm này.</blockquote>', 'SAVED', NULL, NULL, NULL, NULL, 3, '2026-05-28 13:00:00', 4, '2026-08-08 17:05:05', 4),
	(3, 3113, 'Biên bản HN - After-visit hospitality and AI follow-up', '<h2>Tóm tắt buổi làm việc</h2><p>Đoàn <strong>After-visit hospitality and AI follow-up</strong> làm việc tại FPT University Hà Nội với mục tiêu: Theo dõi sau visit tại HN và Quy Nhơn về AI ứng dụng trong hospitality.</p><h3>Nội dung đã thống nhất</h3><ul><li>IC là đầu mối tổng hợp tài liệu và gửi follow-up.</li><li>Department phụ trách trả lời các câu hỏi chuyên môn trong 5 ngày làm việc.</li><li>Host cập nhật action item, feedback và trạng thái news trước khi đóng hồ sơ.</li></ul><blockquote>Nội dung biên bản phản ánh riêng mục tiêu, kết quả và đầu việc của campus trong chuyến thăm này.</blockquote>', 'DRAFT', 4, '2026-06-12 15:30:00', '2026-06-12 16:30:00', '11111111-2222-3333-4444-555555555555', 1, '2026-06-12 15:30:00', 4, '2026-08-08 17:05:05', 4),
	(4, 3115, 'Biên bản HN - Closed three-campus partnership tour', '<h2>Tóm tắt buổi làm việc</h2><p>Đoàn <strong>Closed three-campus partnership tour</strong> làm việc tại FPT University Hà Nội với mục tiêu: Tour ký kết và thảo luận học thuật tại ba campus.</p><h3>Nội dung đã thống nhất</h3><ul><li>IC là đầu mối tổng hợp tài liệu và gửi follow-up.</li><li>Department phụ trách trả lời các câu hỏi chuyên môn trong 5 ngày làm việc.</li><li>Host cập nhật action item, feedback và trạng thái news trước khi đóng hồ sơ.</li></ul><blockquote>Nội dung biên bản phản ánh riêng mục tiêu, kết quả và đầu việc của campus trong chuyến thăm này.</blockquote>', 'SAVED', NULL, NULL, NULL, NULL, 4, '2026-05-20 13:00:00', 4, '2026-08-08 17:05:05', 4),
	(49001, 42004, 'Biên bản nháp giao lưu văn hóa Korea Foundation', 'Host đang ghi nhận câu hỏi của sinh viên và các cam kết phối hợp phát sinh trong buổi làm việc.', 'DRAFT', 3, '2026-08-08 16:46:27', '2026-08-08 17:46:27', '49001000-0000-0000-0000-000000000001', 2, '2026-08-08 15:06:27', 3, '2026-08-08 16:46:27', 3),
