INSERT INTO `news_content_sections` (`section_id`, `news_translation_id`, `section_order`, `section_title`, `section_body_html`, `section_body_text`, `created_at`, `updated_at`) VALUES
	(171051, 171017, 1, 'Tin tức gắn với vòng đời chuyến thăm', '<p>News module trong PEMS được thiết kế để kết nối trực tiếp với vòng đời tiếp khách: sau khi chuyến thăm hoàn tất, host có thể tạo bài, gắn ảnh, gửi duyệt và xuất bản lên trang public khi đủ điều kiện.</p>', 'News module trong PEMS được thiết kế để kết nối trực tiếp với vòng đời tiếp khách: sau khi chuyến thăm hoàn tất, host có thể tạo bài, gắn ảnh, gửi duyệt và xuất bản lên trang public khi đủ điều kiện.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171052, 171017, 2, 'Kiểm soát ảnh và nội dung', '<p>Ảnh được lưu dưới dạng metadata trong bảng files và liên kết với section qua news_section_files. Cách này giúp tránh lưu base64 trong database, đồng thời cho phép kiểm soát quyền xem ảnh theo trạng thái bài viết.</p><ul><li>PUBLISHED: public có thể xem.</li><li>PENDING_REVIEW và REJECTED: chỉ dashboard nội bộ xem theo quyền.</li><li>HIDDEN: bài từng có thể publish nhưng đang bị ẩn khỏi public.</li></ul>', 'Ảnh được lưu dưới dạng metadata trong bảng files và liên kết với section qua news_section_files. Cách này giúp tránh lưu base64 trong database, đồng thời cho phép kiểm soát quyền xem ảnh theo trạng thái bài viết. PUBLISHED: public có thể xem. PENDING_REVIEW và REJECTED: chỉ dashboard nội bộ xem theo quyền. HIDDEN: bài từng có thể publish nhưng đang bị ẩn khỏi public.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171053, 171017, 3, 'Đa ngôn ngữ và dịch tự động', '<p>Mỗi bài có thể có nhiều bản dịch trong news_translations. Khi cấu hình Google Cloud Translation, người dùng có thể tạo bản dịch nháp, kiểm tra lại nội dung và lưu thành bản copy mới mà không ảnh hưởng bản gốc.</p>', 'Mỗi bài có thể có nhiều bản dịch trong news_translations. Khi cấu hình Google Cloud Translation, người dùng có thể tạo bản dịch nháp, kiểm tra lại nội dung và lưu thành bản copy mới mà không ảnh hưởng bản gốc.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171054, 171018, 1, 'News connected to visit lifecycle', '<p>The News module is linked to the reception lifecycle. After a visit is completed, hosts can create an article, attach images, submit for review and publish when all conditions are satisfied.</p>', 'The News module is linked to the reception lifecycle. After a visit is completed, hosts can create an article, attach images, submit for review and publish when all conditions are satisfied.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171055, 171018, 2, 'Content and image control', '<p>Images are stored as file metadata and connected to article sections through news_section_files. This avoids base64 payloads in the database and allows public access to be controlled by article status.</p>', 'Images are stored as file metadata and connected to article sections through news_section_files. This avoids base64 payloads in the database and allows public access to be controlled by article status.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171056, 171018, 3, 'Multilingual publishing', '<p>Each article can have multiple translations. With Google Cloud Translation configured, users can generate a draft translation, review it and save it as a new language copy.</p>', 'Each article can have multiple translations. With Google Cloud Translation configured, users can generate a draft translation, review it and save it as a new language copy.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171057, 171019, 1, '与接待流程联动', '<p>新闻模块与接待生命周期相连接。访问结束后，host可以创建文章、添加图片、提交审核并在符合条件后发布。</p>', '新闻模块与接待生命周期相连接。访问结束后，host可以创建文章、添加图片、提交审核并在符合条件后发布。', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171058, 171019, 2, '内容和图片管理', '<p>图片以文件元数据形式保存，并通过 news_section_files 与文章 section 建立关系，避免在数据库中保存 base64 内容。</p>', '图片以文件元数据形式保存，并通过 news_section_files 与文章 section 建立关系，避免在数据库中保存 base64 内容。', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171059, 171019, 3, '多语言发布', '<p>每篇文章可以拥有多个语言版本。配置翻译服务后，用户可以生成翻译草稿并保存为新的语言副本。</p>', '每篇文章可以拥有多个语言版本。配置翻译服务后，用户可以生成翻译草稿并保存为新的语言副本。', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171060, 171020, 1, 'Mục tiêu chương trình mentor', '<p>Chương trình hướng tới việc duy trì kết nối sau buổi tiếp khách, giúp sinh viên có kênh đặt câu hỏi về nghề nghiệp, kỹ năng dự án và tiêu chuẩn làm việc trong môi trường quốc tế.</p>', 'Chương trình hướng tới việc duy trì kết nối sau buổi tiếp khách, giúp sinh viên có kênh đặt câu hỏi về nghề nghiệp, kỹ năng dự án và tiêu chuẩn làm việc trong môi trường quốc tế.', '2026-08-11 10:10:00', NULL),
	(171061, 171020, 2, 'Cách vận hành đề xuất', '<p>Host đề xuất tạo lịch mentor theo nhóm nhỏ, mỗi buổi có chủ đề cụ thể và form ghi nhận câu hỏi trước. Nội dung nhạy cảm về doanh nghiệp sẽ không đưa vào bản public.</p>', 'Host đề xuất tạo lịch mentor theo nhóm nhỏ, mỗi buổi có chủ đề cụ thể và form ghi nhận câu hỏi trước. Nội dung nhạy cảm về doanh nghiệp sẽ không đưa vào bản public.', '2026-08-11 10:10:00', NULL),
	(171062, 171020, 3, 'Trạng thái hiện tại', '<p>Bài đã có bản tiếng Việt và tiếng Anh nhưng vẫn đang chờ Staff Leader rà soát giọng văn, mức độ công khai và tên đối tác trước khi xuất bản.</p>', 'Bài đã có bản tiếng Việt và tiếng Anh nhưng vẫn đang chờ Staff Leader rà soát giọng văn, mức độ công khai và tên đối tác trước khi xuất bản.', '2026-08-11 10:10:00', NULL),
	(171063, 171021, 1, 'Program objective', '<p>The program aims to maintain post-visit connections and give students a channel to ask about careers, project skills and international workplace standards.</p>', 'The program aims to maintain post-visit connections and give students a channel to ask about careers, project skills and international workplace standards.', '2026-08-11 10:10:00', NULL),
	(171064, 171021, 2, 'Proposed operation', '<p>The host suggests small-group mentor sessions with clear themes and a pre-collected question form. Sensitive business information will not be included in the public article.</p>', 'The host suggests small-group mentor sessions with clear themes and a pre-collected question form. Sensitive business information will not be included in the public article.', '2026-08-11 10:10:00', NULL),
	(171065, 171021, 3, 'Current status', '<p>The article already has Vietnamese and English versions but is waiting for Staff Leader review before publication.</p>', 'The article already has Vietnamese and English versions but is waiting for Staff Leader review before publication.', '2026-08-11 10:10:00', NULL),
	(171066, 171022, 1, 'Lễ ký kết và định hướng seminar', '<p>Đại diện FPTU Hà Nội và Porto AI Hub thống nhất kế hoạch tổ chức chuỗi seminar về AI ứng dụng. Thay vì chỉ tập trung vào lý thuyết, chương trình sẽ đưa vào các case study về xử lý dữ liệu, thiết kế sản phẩm AI và đánh giá rủi ro đạo đức.</p>', 'Đại diện FPTU Hà Nội và Porto AI Hub thống nhất kế hoạch tổ chức chuỗi seminar về AI ứng dụng. Thay vì chỉ tập trung vào lý thuyết, chương trình sẽ đưa vào các case study về xử lý dữ liệu, thiết kế sản phẩm AI và đánh giá rủi ro đạo đức.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171067, 171022, 2, 'Cấu trúc chương trình dự kiến', '<p>Chuỗi seminar gồm ba phần: bài nói mở đầu từ chuyên gia, phiên thảo luận nhóm và bài tập thực hành ngắn. Sinh viên có thể chuẩn bị câu hỏi trước thông qua form đăng ký để buổi seminar đi vào vấn đề cụ thể.</p>', 'Chuỗi seminar gồm ba phần: bài nói mở đầu từ chuyên gia, phiên thảo luận nhóm và bài tập thực hành ngắn. Sinh viên có thể chuẩn bị câu hỏi trước thông qua form đăng ký để buổi seminar đi vào vấn đề cụ thể.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171068, 171022, 3, 'Ý nghĩa với sinh viên', '<p>Hoạt động này giúp sinh viên nhìn thấy cách kiến thức AI được chuyển thành sản phẩm, đồng thời hiểu rõ hơn về yêu cầu giao tiếp khi làm việc trong nhóm quốc tế.</p>', 'Hoạt động này giúp sinh viên nhìn thấy cách kiến thức AI được chuyển thành sản phẩm, đồng thời hiểu rõ hơn về yêu cầu giao tiếp khi làm việc trong nhóm quốc tế.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171069, 171023, 1, 'Signing and seminar direction', '<p>FPTU Hanoi and Porto AI Hub agreed to develop a seminar series on applied AI. The program will include case studies on data processing, AI product design and ethical risk assessment.</p>', 'FPTU Hanoi and Porto AI Hub agreed to develop a seminar series on applied AI. The program will include case studies on data processing, AI product design and ethical risk assessment.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171070, 171023, 2, 'Expected program structure', '<p>Each seminar will include an expert talk, a group discussion and a short practical exercise. Students can submit questions in advance to make the session more focused.</p>', 'Each seminar will include an expert talk, a group discussion and a short practical exercise. Students can submit questions in advance to make the session more focused.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171071, 171023, 3, 'Meaning for students', '<p>The activity helps students understand how AI knowledge becomes real products and how communication works in international project teams.</p>', 'The activity helps students understand how AI knowledge becomes real products and how communication works in international project teams.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171072, 171024, 1, '세미나 방향', '<p>FPTU 하노이와 Porto AI Hub는 응용 AI 세미나 시리즈를 함께 추진하기로 했다. 프로그램에는 데이터 처리, AI 제품 설계, 윤리적 위험 평가 사례가 포함된다.</p>', 'FPTU 하노이와 Porto AI Hub는 응용 AI 세미나 시리즈를 함께 추진하기로 했다. 프로그램에는 데이터 처리, AI 제품 설계, 윤리적 위험 평가 사례가 포함된다.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171073, 171024, 2, '프로그램 구성', '<p>각 세미나는 전문가 발표, 그룹 토론, 짧은 실습으로 구성될 예정이다.</p>', '각 세미나는 전문가 발표, 그룹 토론, 짧은 실습으로 구성될 예정이다.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171074, 171024, 3, '학생에게 주는 의미', '<p>학생들은 AI 지식이 실제 제품으로 연결되는 과정을 이해하고 국제 프로젝트 팀에서의 소통 방식을 경험할 수 있다.</p>', '학생들은 AI 지식이 실제 제품으로 연결되는 과정을 이해하고 국제 프로젝트 팀에서의 소통 방식을 경험할 수 있다.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171078, 171026, 1, '', '<p>🎓&nbsp;Thông&nbsp;qua&nbsp;thỏa&nbsp;thuận&nbsp;hợp&nbsp;tác&nbsp;này,&nbsp;hai&nbsp;bên&nbsp;hướng&nbsp;tới&nbsp;việc&nbsp;mở&nbsp;rộng&nbsp;các&nbsp;hoạt&nbsp;động&nbsp;trao&nbsp;đổi&nbsp;sinh&nbsp;viên&nbsp;và&nbsp;giảng&nbsp;viên,&nbsp;phát&nbsp;triển&nbsp;các&nbsp;chương&nbsp;trình&nbsp;học&nbsp;tập&nbsp;quốc&nbsp;tế,&nbsp;thúc&nbsp;đẩy&nbsp;hợp&nbsp;tác&nbsp;nghiên&nbsp;cứu&nbsp;và&nbsp;tạo&nbsp;thêm&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;trải&nbsp;nghiệm&nbsp;học&nbsp;thuật&nbsp;toàn&nbsp;cầu&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;FPT&nbsp;University.</p><p>🌍&nbsp;Buổi&nbsp;lễ&nbsp;ký&nbsp;kết&nbsp;đánh&nbsp;dấu&nbsp;một&nbsp;bước&nbsp;tiến&nbsp;quan&nbsp;trọng&nbsp;trong&nbsp;chiến&nbsp;lược&nbsp;quốc&nbsp;tế&nbsp;hóa&nbsp;của&nbsp;FPT&nbsp;University,&nbsp;đồng&nbsp;thời&nbsp;góp&nbsp;phần&nbsp;tăng&nbsp;cường&nbsp;kết&nbsp;nối&nbsp;với&nbsp;các&nbsp;đối&nbsp;tác&nbsp;học&nbsp;thuật&nbsp;uy&nbsp;tín&nbsp;tại&nbsp;Hàn&nbsp;Quốc&nbsp;và&nbsp;khu&nbsp;vực&nbsp;châu&nbsp;Á.</p><p>✨&nbsp;FPT&nbsp;University&nbsp;xin&nbsp;trân&nbsp;trọng&nbsp;cảm&nbsp;ơn&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;từ&nbsp;Ajou&nbsp;University&nbsp;đã&nbsp;đến&nbsp;tham&nbsp;dự&nbsp;và&nbsp;cùng&nbsp;thực&nbsp;hiện&nbsp;lễ&nbsp;ký&nbsp;kết.&nbsp;Hy&nbsp;vọng&nbsp;mối&nbsp;quan&nbsp;hệ&nbsp;hợp&nbsp;tác&nbsp;giữa&nbsp;hai&nbsp;trường&nbsp;sẽ&nbsp;phát&nbsp;triển&nbsp;bền&nbsp;vững,&nbsp;mang&nbsp;lại&nbsp;nhiều&nbsp;giá&nbsp;trị&nbsp;thiết&nbsp;thực&nbsp;cho&nbsp;sinh&nbsp;viên,&nbsp;giảng&nbsp;viên&nbsp;và&nbsp;cộng&nbsp;đồng&nbsp;học&nbsp;thuật&nbsp;của&nbsp;cả&nbsp;hai&nbsp;bên.</p><p>ℹ️Mọi&nbsp;thắc&nbsp;mắc&nbsp;xin&nbsp;liên&nbsp;hệ:</p><p>-&nbsp;Địa&nbsp;điểm:&nbsp;Phòng&nbsp;L209,&nbsp;Toà&nbsp;nhà&nbsp;Alpha,&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;Hà&nbsp;Nội&nbsp;</p><p>-&nbsp;SĐT:&nbsp;(+84)&nbsp;24&nbsp;6680&nbsp;5910</p><p>-&nbsp;Fanpage:&nbsp;Phòng&nbsp;Hợp&nbsp;tác&nbsp;quốc&nbsp;tế&nbsp;FPTU&nbsp;Hà&nbsp;Nội</p><p>-&nbsp;Email:&nbsp;international.fptu@fpt.edu.vn</p><p>-&nbsp;Group&nbsp;Review&nbsp;chương&nbsp;trình&nbsp;quốc&nbsp;tế&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;</p>', '🎓 Thông qua thỏa thuận hợp tác này, hai bên hướng tới việc mở rộng các hoạt động trao đổi sinh viên và giảng viên, phát triển các chương trình học tập quốc tế, thúc đẩy hợp tác nghiên cứu và tạo thêm nhiều cơ hội trải nghiệm học thuật toàn cầu cho sinh viên FPT University. 🌍 Buổi lễ ký kết đánh dấu một bước tiến quan trọng trong chiến lược quốc tế hóa của FPT University, đồng thời góp phần tăng cường kết nối với các đối tác học thuật uy tín tại Hàn Quốc và khu vực châu Á. ✨ FPT University xin trân trọng cảm ơn đoàn đại biểu từ Ajou University đã đến tham dự và cùng thực hiện lễ ký kết. Hy vọng mối quan hệ hợp tác giữa hai trường sẽ phát triển bền vững, mang lại nhiều giá trị thiết thực cho sinh viên, giảng viên và cộng đồng học thuật của cả hai bên. ℹ️Mọi thắc mắc xin liên hệ: - Địa điểm: Phòng L209, Toà nhà Alpha, Trường Đại học FPT Hà Nội - SĐT: (+84) 24 6680 5910 - Fanpage: Phòng Hợp tác quốc tế FPTU Hà Nội - Email: international.fptu@fpt.edu.vn - Group Review chương trình quốc tế Đại học FPT', '2026-08-08 22:30:15', NULL),
	(171079, 171027, 1, '', '<p>🎓 Through this cooperation agreement, both parties aim to expand student and faculty exchange activities, develop international learning programs, promote research collaboration, and create more opportunities for global academic experiences for FPT University students.</p><p> 🌍 The signing ceremony marks a significant step in FPT University\'s internationalization strategy, while also contributing to strengthening connections with prestigious academic partners in South Korea and the Asian region.</p><p> ✨ FPT University would like to express its sincere gratitude to the delegation from Ajou University for attending and participating in the signing ceremony. We hope that the cooperative relationship between the two universities will develop sustainably, bringing many practical benefits to students, faculty, and the academic community of both sides.</p><p> ℹ️For any questions, please contact:</p><p> - Location: Room L209, Alpha Building, FPT University Hanoi</p><p> - Phone number: (+84) 24 6680 5910</p><p> - Fanpage: FPTU Hanoi International Cooperation Department</p><p> - Email: international.fptu@fpt.edu.vn</p><p> - Group Review of FPT University\'s International Programs</p>', '🎓 Through this cooperation agreement, both parties aim to expand student and faculty exchange activities, develop international learning programs, promote research collaboration, and create more opportunities for global academic experiences for FPT University students. 🌍 The signing ceremony marks a significant step in FPT University\'s internationalization strategy, while also contributing to strengthening connections with prestigious academic partners in South Korea and the Asian region. ✨ FPT University would like to express its sincere gratitude to the delegation from Ajou University for attending and participating in the signing ceremony. We hope that the cooperative relationship between the two universities will develop sustainably, bringing many practical benefits to students, faculty, and the academic community of both sides. ℹ️For any questions, please contact: - Location: Room L209, Alpha Building, FPT University Hanoi - Phone number: (+84) 24 6680 5910 - Fanpage: FPTU Hanoi International Cooperation Department - Email: international.fptu@fpt.edu.vn - Group Review of FPT University\'s International Programs', '2026-08-08 22:30:15', NULL),
	(171080, 171028, 1, '', '<p>🎓&nbsp;Trong&nbsp;chuyến&nbsp;thăm,&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;đã&nbsp;tham&nbsp;quan&nbsp;cơ&nbsp;sở&nbsp;vật&nbsp;chất,&nbsp;tìm&nbsp;hiểu&nbsp;mô&nbsp;hình&nbsp;đào&nbsp;tạo&nbsp;và&nbsp;hệ&nbsp;sinh&nbsp;thái&nbsp;giáo&nbsp;dục&nbsp;của&nbsp;&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT.&nbsp;Hai&nbsp;bên&nbsp;đã&nbsp;trao&nbsp;đổi&nbsp;về&nbsp;các&nbsp;định&nbsp;hướng&nbsp;hợp&nbsp;tác&nbsp;trong&nbsp;đào&nbsp;tạo&nbsp;vi&nbsp;mạch&nbsp;bán&nbsp;dẫn,&nbsp;phát&nbsp;triển&nbsp;chương&nbsp;trình&nbsp;giảng&nbsp;dạy&nbsp;về&nbsp;thiết&nbsp;kế&nbsp;vi&nbsp;mạch&nbsp;(IC&nbsp;Design)&nbsp;và&nbsp;VLSI,&nbsp;đồng&nbsp;thời&nbsp;thảo&nbsp;luận&nbsp;về&nbsp;các&nbsp;cơ&nbsp;hội&nbsp;trao&nbsp;đổi&nbsp;sinh&nbsp;viên,&nbsp;chương&nbsp;trình&nbsp;thực&nbsp;tập,&nbsp;trao&nbsp;đổi&nbsp;giảng&nbsp;viên&nbsp;và&nbsp;đồng&nbsp;hướng&nbsp;dẫn&nbsp;học&nbsp;viên&nbsp;sau&nbsp;đại&nbsp;học.</p><p>🌍&nbsp;Bên&nbsp;cạnh&nbsp;đó,&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;và&nbsp;Yuan&nbsp;Ze&nbsp;University&nbsp;cũng&nbsp;chia&nbsp;sẻ&nbsp;tầm&nbsp;nhìn&nbsp;về&nbsp;việc&nbsp;tăng&nbsp;cường&nbsp;hợp&nbsp;tác&nbsp;giữa&nbsp;nhà&nbsp;trường&nbsp;và&nbsp;doanh&nbsp;nghiệp,&nbsp;kết&nbsp;nối&nbsp;với&nbsp;hệ&nbsp;sinh&nbsp;thái&nbsp;công&nbsp;nghiệp&nbsp;bán&nbsp;dẫn&nbsp;của&nbsp;Đài&nbsp;Loan&nbsp;nhằm&nbsp;mang&nbsp;đến&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;học&nbsp;tập,&nbsp;nghiên&nbsp;cứu&nbsp;và&nbsp;phát&nbsp;triển&nbsp;nghề&nbsp;nghiệp&nbsp;cho&nbsp;sinh&nbsp;viên.</p><p>✨&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;xin&nbsp;trân&nbsp;trọng&nbsp;cảm&nbsp;ơn&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;từ&nbsp;Yuan&nbsp;Ze&nbsp;University&nbsp;đã&nbsp;dành&nbsp;thời&nbsp;gian&nbsp;đến&nbsp;thăm&nbsp;và&nbsp;làm&nbsp;việc.&nbsp;Hy&nbsp;vọng&nbsp;chuyến&nbsp;gặp&nbsp;gỡ&nbsp;sẽ&nbsp;mở&nbsp;ra&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;hợp&nbsp;tác&nbsp;thiết&nbsp;thực,&nbsp;góp&nbsp;phần&nbsp;thúc&nbsp;đẩy&nbsp;đào&nbsp;tạo&nbsp;nguồn&nbsp;nhân&nbsp;lực&nbsp;chất&nbsp;lượng&nbsp;cao&nbsp;cho&nbsp;ngành&nbsp;công&nbsp;nghiệp&nbsp;bán&nbsp;dẫn&nbsp;trong&nbsp;tương&nbsp;lai.</p><p>------------------------------------------------</p><p>&nbsp;ℹ️Mọi&nbsp;thắc&nbsp;mắc&nbsp;xin&nbsp;liên&nbsp;hệ:</p><p>-&nbsp;Địa&nbsp;điểm:&nbsp;Phòng&nbsp;L209,&nbsp;Toà&nbsp;nhà&nbsp;Alpha,&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;Hà&nbsp;Nội&nbsp;</p><p>-&nbsp;SĐT:&nbsp;(+84)&nbsp;24&nbsp;6680&nbsp;5910</p><p>-&nbsp;Fanpage:&nbsp;Phòng&nbsp;Hợp&nbsp;tác&nbsp;quốc&nbsp;tế&nbsp;FPTU&nbsp;Hà&nbsp;Nội</p><p>-&nbsp;Email:&nbsp;international.fptu@fpt.edu.vn</p><p>-&nbsp;Group&nbsp;Review&nbsp;chương&nbsp;trình&nbsp;quốc&nbsp;tế&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;</p>', '🎓 Trong chuyến thăm, đoàn đại biểu đã tham quan cơ sở vật chất, tìm hiểu mô hình đào tạo và hệ sinh thái giáo dục của Trường Đại học FPT. Hai bên đã trao đổi về các định hướng hợp tác trong đào tạo vi mạch bán dẫn, phát triển chương trình giảng dạy về thiết kế vi mạch (IC Design) và VLSI, đồng thời thảo luận về các cơ hội trao đổi sinh viên, chương trình thực tập, trao đổi giảng viên và đồng hướng dẫn học viên sau đại học. 🌍 Bên cạnh đó, Trường Đại học FPT và Yuan Ze University cũng chia sẻ tầm nhìn về việc tăng cường hợp tác giữa nhà trường và doanh nghiệp, kết nối với hệ sinh thái công nghiệp bán dẫn của Đài Loan nhằm mang đến nhiều cơ hội học tập, nghiên cứu và phát triển nghề nghiệp cho sinh viên. ✨ Trường Đại học FPT xin trân trọng cảm ơn đoàn đại biểu từ Yuan Ze University đã dành thời gian đến thăm và làm việc. Hy vọng chuyến gặp gỡ sẽ mở ra nhiều cơ hội hợp tác thiết thực, góp phần thúc đẩy đào tạo nguồn nhân lực chất lượng cao cho ngành công nghiệp bán dẫn trong tương lai. ------------------------------------------------ ℹ️Mọi thắc mắc xin liên hệ: - Địa điểm: Phòng L209, Toà nhà Alpha, Trường Đại học FPT Hà Nội - SĐT: (+84) 24 6680 5910 - Fanpage: Phòng Hợp tác quốc tế FPTU Hà Nội - Email: international.fptu@fpt.edu.vn - Group Review chương trình quốc tế Đại học FPT', '2026-08-09 00:41:39', NULL),
	(171081, 171029, 1, '', '<p>🎓 During the visit, the delegation toured the facilities and learned about the training model and educational ecosystem of FPT University. Both sides discussed directions for cooperation in semiconductor microchip training, curriculum development in integrated circuit design (IC Design) and VLSI, and explored opportunities for student exchange, internships, faculty exchange, and co-supervision of postgraduate students.</p><p> 🌍 In addition, FPT University and Yuan Ze University also share a vision of strengthening cooperation between universities and businesses, connecting with Taiwan\'s semiconductor industry ecosystem to provide more learning, research, and career development opportunities for students.</p><p> ✨ FPT University would like to express its sincere gratitude to the delegation from Yuan Ze University for taking the time to visit and work with us. We hope this meeting will open up many practical cooperation opportunities, contributing to promoting the training of high-quality human resources for the semiconductor industry in the future.</p><p> ------------------------------------------------</p><p> ℹ️For any questions, please contact:</p><p> - Location: Room L209, Alpha Building, FPT University Hanoi</p><p> - Phone number: (+84) 24 6680 5910</p><p> - Fanpage: FPTU Hanoi International Cooperation Department</p><p> - Email: international.fptu@fpt.edu.vn</p><p> - Group Review of FPT University\'s International Programs</p>', '🎓 During the visit, the delegation toured the facilities and learned about the training model and educational ecosystem of FPT University. Both sides discussed directions for cooperation in semiconductor microchip training, curriculum development in integrated circuit design (IC Design) and VLSI, and explored opportunities for student exchange, internships, faculty exchange, and co-supervision of postgraduate students. 🌍 In addition, FPT University and Yuan Ze University also share a vision of strengthening cooperation between universities and businesses, connecting with Taiwan\'s semiconductor industry ecosystem to provide more learning, research, and career development opportunities for students. ✨ FPT University would like to express its sincere gratitude to the delegation from Yuan Ze University for taking the time to visit and work with us. We hope this meeting will open up many practical cooperation opportunities, contributing to promoting the training of high-quality human resources for the semiconductor industry in the future. ------------------------------------------------ ℹ️For any questions, please contact: - Location: Room L209, Alpha Building, FPT University Hanoi - Phone number: (+84) 24 6680 5910 - Fanpage: FPTU Hanoi International Cooperation Department - Email: international.fptu@fpt.edu.vn - Group Review of FPT University\'s International Programs', '2026-08-09 00:41:39', NULL),
	(171082, 171030, 1, '', '<p>🎓&nbsp;Trong&nbsp;chuyến&nbsp;thăm,&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;đã&nbsp;tham&nbsp;quan&nbsp;cơ&nbsp;sở&nbsp;vật&nbsp;chất,&nbsp;tìm&nbsp;hiểu&nbsp;mô&nbsp;hình&nbsp;đào&nbsp;tạo,&nbsp;môi&nbsp;trường&nbsp;học&nbsp;tập&nbsp;và&nbsp;hệ&nbsp;sinh&nbsp;thái&nbsp;giáo&nbsp;dục&nbsp;của&nbsp;FPT&nbsp;University.&nbsp;Hai&nbsp;bên&nbsp;cũng&nbsp;trao&nbsp;đổi&nbsp;về&nbsp;các&nbsp;chương&nbsp;trình&nbsp;quốc&nbsp;tế,&nbsp;cơ&nbsp;hội&nbsp;trao&nbsp;đổi&nbsp;sinh&nbsp;viên,&nbsp;hợp&nbsp;tác&nbsp;học&nbsp;thuật&nbsp;và&nbsp;những&nbsp;định&nbsp;hướng&nbsp;phát&nbsp;triển&nbsp;nhằm&nbsp;mang&nbsp;đến&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;học&nbsp;tập&nbsp;và&nbsp;trải&nbsp;nghiệm&nbsp;quốc&nbsp;tế&nbsp;cho&nbsp;sinh&nbsp;viên.</p><p>🌍&nbsp;Buổi&nbsp;làm&nbsp;việc&nbsp;là&nbsp;dịp&nbsp;để&nbsp;FPT&nbsp;University&nbsp;và&nbsp;Singapore&nbsp;Management&nbsp;University&nbsp;tăng&nbsp;cường&nbsp;kết&nbsp;nối,&nbsp;mở&nbsp;rộng&nbsp;quan&nbsp;hệ&nbsp;hợp&nbsp;tác&nbsp;quốc&nbsp;tế,&nbsp;đồng&nbsp;thời&nbsp;thúc&nbsp;đẩy&nbsp;các&nbsp;hoạt&nbsp;động&nbsp;trao&nbsp;đổi&nbsp;sinh&nbsp;viên,&nbsp;giảng&nbsp;viên,&nbsp;nghiên&nbsp;cứu&nbsp;và&nbsp;phát&nbsp;triển&nbsp;nguồn&nbsp;nhân&nbsp;lực&nbsp;chất&nbsp;lượng&nbsp;cao&nbsp;trong&nbsp;bối&nbsp;cảnh&nbsp;toàn&nbsp;cầu.</p><p>✨&nbsp;FPT&nbsp;University&nbsp;xin&nbsp;trân&nbsp;trọng&nbsp;cảm&nbsp;ơn&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;từ&nbsp;Singapore&nbsp;Management&nbsp;University&nbsp;đã&nbsp;dành&nbsp;thời&nbsp;gian&nbsp;đến&nbsp;thăm&nbsp;và&nbsp;làm&nbsp;việc.&nbsp;Hy&nbsp;vọng&nbsp;chuyến&nbsp;gặp&nbsp;gỡ&nbsp;sẽ&nbsp;mở&nbsp;ra&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;hợp&nbsp;tác&nbsp;ý&nbsp;nghĩa&nbsp;trong&nbsp;thời&nbsp;gian&nbsp;tới.</p><p>-------------------------------------------------------------------</p><p>&nbsp;ℹ️Mọi&nbsp;thắc&nbsp;mắc&nbsp;xin&nbsp;liên&nbsp;hệ:</p><p>-&nbsp;Địa&nbsp;điểm:&nbsp;Phòng&nbsp;L209,&nbsp;Toà&nbsp;nhà&nbsp;Alpha,&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;Hà&nbsp;Nội&nbsp;</p><p>-&nbsp;SĐT:&nbsp;(+84)&nbsp;24&nbsp;6680&nbsp;5910</p><p>-&nbsp;Fanpage:&nbsp;Phòng&nbsp;Hợp&nbsp;tác&nbsp;quốc&nbsp;tế&nbsp;FPTU&nbsp;Hà&nbsp;Nội</p><p>-&nbsp;Email:&nbsp;international.fptu@fpt.edu.vn</p><p>-&nbsp;Group&nbsp;Review&nbsp;chương&nbsp;trình&nbsp;quốc&nbsp;tế&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;</p>', '🎓 Trong chuyến thăm, đoàn đại biểu đã tham quan cơ sở vật chất, tìm hiểu mô hình đào tạo, môi trường học tập và hệ sinh thái giáo dục của FPT University. Hai bên cũng trao đổi về các chương trình quốc tế, cơ hội trao đổi sinh viên, hợp tác học thuật và những định hướng phát triển nhằm mang đến nhiều cơ hội học tập và trải nghiệm quốc tế cho sinh viên. 🌍 Buổi làm việc là dịp để FPT University và Singapore Management University tăng cường kết nối, mở rộng quan hệ hợp tác quốc tế, đồng thời thúc đẩy các hoạt động trao đổi sinh viên, giảng viên, nghiên cứu và phát triển nguồn nhân lực chất lượng cao trong bối cảnh toàn cầu. ✨ FPT University xin trân trọng cảm ơn đoàn đại biểu từ Singapore Management University đã dành thời gian đến thăm và làm việc. Hy vọng chuyến gặp gỡ sẽ mở ra nhiều cơ hội hợp tác ý nghĩa trong thời gian tới. ------------------------------------------------------------------- ℹ️Mọi thắc mắc xin liên hệ: - Địa điểm: Phòng L209, Toà nhà Alpha, Trường Đại học FPT Hà Nội - SĐT: (+84) 24 6680 5910 - Fanpage: Phòng Hợp tác quốc tế FPTU Hà Nội - Email: international.fptu@fpt.edu.vn - Group Review chương trình quốc tế Đại học FPT', '2026-08-09 16:52:53', NULL),
	(171083, 171031, 1, '', '<p>🎓 During the visit, the delegation toured the facilities, learned about the training model, learning environment, and educational ecosystem of FPT University. Both sides also discussed international programs, student exchange opportunities, academic cooperation, and development directions aimed at providing more international learning and experience opportunities for students.</p><p> 🌍 This meeting provides an opportunity for FPT University and Singapore Management University to strengthen connections, expand international cooperation, and promote student and faculty exchange programs, research, and the development of high-quality human resources in a global context.</p><p> ✨ FPT University would like to express its sincere gratitude to the delegation from Singapore Management University for taking the time to visit and work with us. We hope this meeting will open up many meaningful opportunities for cooperation in the future.</p><p> -------------------------------------------------------------------</p><p> ℹ️For any questions, please contact:</p><p> - Location: Room L209, Alpha Building, FPT University Hanoi</p><p> - Phone number: (+84) 24 6680 5910</p><p> - Fanpage: FPTU Hanoi International Cooperation Department</p><p> - Email: international.fptu@fpt.edu.vn</p><p> - Group Review of FPT University\'s International Programs</p>', '🎓 During the visit, the delegation toured the facilities, learned about the training model, learning environment, and educational ecosystem of FPT University. Both sides also discussed international programs, student exchange opportunities, academic cooperation, and development directions aimed at providing more international learning and experience opportunities for students. 🌍 This meeting provides an opportunity for FPT University and Singapore Management University to strengthen connections, expand international cooperation, and promote student and faculty exchange programs, research, and the development of high-quality human resources in a global context. ✨ FPT University would like to express its sincere gratitude to the delegation from Singapore Management University for taking the time to visit and work with us. We hope this meeting will open up many meaningful opportunities for cooperation in the future. ------------------------------------------------------------------- ℹ️For any questions, please contact: - Location: Room L209, Alpha Building, FPT University Hanoi - Phone number: (+84) 24 6680 5910 - Fanpage: FPTU Hanoi International Cooperation Department - Email: international.fptu@fpt.edu.vn - Group Review of FPT University\'s International Programs', '2026-08-09 16:52:53', NULL),
	(171084, 171032, 1, '', '<p></p><p>✨&nbsp;Ngày&nbsp;01/07,&nbsp;FPT&nbsp;University&nbsp;hân&nbsp;hạnh&nbsp;đón&nbsp;tiếp&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;đến&nbsp;tham&nbsp;quan&nbsp;và&nbsp;làm&nbsp;việc.&nbsp;Trong&nbsp;chuyến&nbsp;thăm,&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;đã&nbsp;tham&nbsp;quan&nbsp;cơ&nbsp;sở&nbsp;vật&nbsp;chất,&nbsp;tìm&nbsp;hiểu&nbsp;môi&nbsp;trường&nbsp;học&nbsp;tập&nbsp;và&nbsp;hệ&nbsp;sinh&nbsp;thái&nbsp;đào&nbsp;tạo&nbsp;của&nbsp;FPT&nbsp;University.&nbsp;Đoàn&nbsp;cũng&nbsp;hòa&nbsp;mình&nbsp;cùng&nbsp;Tech&nbsp;Fest,&nbsp;&nbsp;trải&nbsp;nghiệm&nbsp;những&nbsp;sản&nbsp;phẩm&nbsp;công&nbsp;nghệ&nbsp;được&nbsp;phát&nbsp;minh&nbsp;bởi&nbsp;sinh&nbsp;viên&nbsp;FPTU.&nbsp;</p><p>🌏Đoàn&nbsp;RWE&nbsp;cũng&nbsp;ấn&nbsp;tượng&nbsp;bởi&nbsp;các&nbsp;dự&nbsp;án&nbsp;văn&nbsp;hóa&nbsp;do&nbsp;sinh&nbsp;viên&nbsp;thực&nbsp;hiện&nbsp;qua&nbsp;đó&nbsp;có&nbsp;cơ&nbsp;hội&nbsp;gặp&nbsp;gỡ,&nbsp;tìm&nbsp;hiểu&nbsp;về&nbsp;thế&nbsp;hệ&nbsp;nhân&nbsp;lực&nbsp;tương&nbsp;lai&nbsp;của&nbsp;FPT&nbsp;thông&nbsp;qua&nbsp;những&nbsp;hoạt&nbsp;động&nbsp;học&nbsp;tập,&nbsp;nghiên&nbsp;cứu&nbsp;và&nbsp;đổi&nbsp;mới&nbsp;sáng&nbsp;tạo&nbsp;của&nbsp;sinh&nbsp;viên.</p><p>✨&nbsp;FPT&nbsp;University&nbsp;xin&nbsp;trân&nbsp;trọng&nbsp;cảm&nbsp;ơn&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;từ&nbsp;RWE&nbsp;đã&nbsp;dành&nbsp;thời&nbsp;gian&nbsp;đến&nbsp;thăm&nbsp;và&nbsp;làm&nbsp;việc.&nbsp;Hy&nbsp;vọng&nbsp;chuyến&nbsp;thăm&nbsp;sẽ&nbsp;là&nbsp;tiền&nbsp;đề&nbsp;cho&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;hợp&nbsp;tác&nbsp;ý&nbsp;nghĩa&nbsp;trong&nbsp;thời&nbsp;gian&nbsp;tới.</p><p>------------------------------------------------</p><p>&nbsp;ℹ️Mọi&nbsp;thắc&nbsp;mắc&nbsp;xin&nbsp;liên&nbsp;hệ:</p><p>-&nbsp;Địa&nbsp;điểm:&nbsp;Phòng&nbsp;L209,&nbsp;Toà&nbsp;nhà&nbsp;Alpha,&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;Hà&nbsp;Nội&nbsp;</p><p>-&nbsp;SĐT:&nbsp;(+84)&nbsp;24&nbsp;6680&nbsp;5910</p><p>-&nbsp;Fanpage:&nbsp;Phòng&nbsp;Hợp&nbsp;tác&nbsp;quốc&nbsp;tế&nbsp;FPTU&nbsp;Hà&nbsp;Nội</p><p>-&nbsp;Email:&nbsp;international.fptu@fpt.edu.vn</p><p>-&nbsp;Group&nbsp;Review&nbsp;chương&nbsp;trình&nbsp;quốc&nbsp;tế&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;</p>', '✨ Ngày 01/07, FPT University hân hạnh đón tiếp đoàn đại biểu đến tham quan và làm việc. Trong chuyến thăm, đoàn đại biểu đã tham quan cơ sở vật chất, tìm hiểu môi trường học tập và hệ sinh thái đào tạo của FPT University. Đoàn cũng hòa mình cùng Tech Fest, trải nghiệm những sản phẩm công nghệ được phát minh bởi sinh viên FPTU. 🌏Đoàn RWE cũng ấn tượng bởi các dự án văn hóa do sinh viên thực hiện qua đó có cơ hội gặp gỡ, tìm hiểu về thế hệ nhân lực tương lai của FPT thông qua những hoạt động học tập, nghiên cứu và đổi mới sáng tạo của sinh viên. ✨ FPT University xin trân trọng cảm ơn đoàn đại biểu từ RWE đã dành thời gian đến thăm và làm việc. Hy vọng chuyến thăm sẽ là tiền đề cho nhiều cơ hội hợp tác ý nghĩa trong thời gian tới. ------------------------------------------------ ℹ️Mọi thắc mắc xin liên hệ: - Địa điểm: Phòng L209, Toà nhà Alpha, Trường Đại học FPT Hà Nội - SĐT: (+84) 24 6680 5910 - Fanpage: Phòng Hợp tác quốc tế FPTU Hà Nội - Email: international.fptu@fpt.edu.vn - Group Review chương trình quốc tế Đại học FPT', '2026-08-09 17:09:18', NULL),
	(171085, 171033, 1, '', '<p></p><p>✨ On July 1st, FPT University was honored to welcome a delegation for a visit and working session. During the visit, the delegation toured the facilities, learned about the learning environment and the training ecosystem of FPT University. The delegation also participated in Tech Fest, experiencing technological products invented by FPTU students.</p><p> 🌏 The RWE delegation was also impressed by the cultural projects carried out by students, providing an opportunity to meet and learn about the future workforce of FPT through students\' learning, research, and innovative activities.</p><p> ✨ FPT University would like to express its sincere gratitude to the delegation from RWE for taking the time to visit and work with us. We hope this visit will lay the groundwork for many meaningful collaboration opportunities in the future.</p><p> ------------------------------------------------</p><p> ℹ️For any questions, please contact:</p><p> - Location: Room L209, Alpha Building, FPT University Hanoi</p><p> - Phone number: (+84) 24 6680 5910</p><p> - Fanpage: FPTU Hanoi International Cooperation Department</p><p> - Email: international.fptu@fpt.edu.vn</p><p> - Group Review of FPT University\'s International Programs</p>', '✨ On July 1st, FPT University was honored to welcome a delegation for a visit and working session. During the visit, the delegation toured the facilities, learned about the learning environment and the training ecosystem of FPT University. The delegation also participated in Tech Fest, experiencing technological products invented by FPTU students. 🌏 The RWE delegation was also impressed by the cultural projects carried out by students, providing an opportunity to meet and learn about the future workforce of FPT through students\' learning, research, and innovative activities. ✨ FPT University would like to express its sincere gratitude to the delegation from RWE for taking the time to visit and work with us. We hope this visit will lay the groundwork for many meaningful collaboration opportunities in the future. ------------------------------------------------ ℹ️For any questions, please contact: - Location: Room L209, Alpha Building, FPT University Hanoi - Phone number: (+84) 24 6680 5910 - Fanpage: FPTU Hanoi International Cooperation Department - Email: international.fptu@fpt.edu.vn - Group Review of FPT University\'s International Programs', '2026-08-09 17:09:18', NULL),
	(171086, 171034, 1, '', '<p>Ngày&nbsp;17/6&nbsp;vừa&nbsp;qua,&nbsp;FPT&nbsp;University&nbsp;đã&nbsp;chào&nbsp;đón&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;từ&nbsp;Yangzhou&nbsp;University&nbsp;đến&nbsp;thăm&nbsp;và&nbsp;làm&nbsp;việc&nbsp;nhằm&nbsp;trao&nbsp;đổi&nbsp;về&nbsp;các&nbsp;cơ&nbsp;hội&nbsp;hợp&nbsp;tác&nbsp;trong&nbsp;đào&nbsp;tạo&nbsp;và&nbsp;nghiên&nbsp;cứu.</p><p>🤝&nbsp;Trong&nbsp;khuôn&nbsp;khổ&nbsp;buổi&nbsp;gặp&nbsp;gỡ,&nbsp;hai&nbsp;bên&nbsp;đã&nbsp;thảo&nbsp;luận&nbsp;về&nbsp;tiềm&nbsp;năng&nbsp;triển&nbsp;khai&nbsp;các&nbsp;chương&nbsp;trình&nbsp;thực&nbsp;tập&nbsp;(OJT),&nbsp;thúc&nbsp;đẩy&nbsp;trao&nbsp;đổi&nbsp;học&nbsp;thuật&nbsp;trong&nbsp;lĩnh&nbsp;vực&nbsp;vi&nbsp;điện&nbsp;tử&nbsp;và&nbsp;các&nbsp;ngành&nbsp;liên&nbsp;quan,&nbsp;đồng&nbsp;thời&nbsp;mở&nbsp;rộng&nbsp;cơ&nbsp;hội&nbsp;hợp&nbsp;tác&nbsp;nghiên&nbsp;cứu&nbsp;giữa&nbsp;giảng&nbsp;viên&nbsp;và&nbsp;sinh&nbsp;viên&nbsp;của&nbsp;hai&nbsp;trường.</p><p>💡&nbsp;Các&nbsp;nội&nbsp;dung&nbsp;trao&nbsp;đổi&nbsp;hướng&nbsp;tới&nbsp;việc&nbsp;tăng&nbsp;cường&nbsp;kết&nbsp;nối&nbsp;học&nbsp;thuật&nbsp;quốc&nbsp;tế,&nbsp;tạo&nbsp;điều&nbsp;kiện&nbsp;để&nbsp;sinh&nbsp;viên&nbsp;tiếp&nbsp;cận&nbsp;môi&nbsp;trường&nbsp;học&nbsp;tập&nbsp;và&nbsp;nghiên&nbsp;cứu&nbsp;đa&nbsp;quốc&nbsp;gia,&nbsp;cũng&nbsp;như&nbsp;nâng&nbsp;cao&nbsp;năng&nbsp;lực&nbsp;chuyên&nbsp;môn&nbsp;trong&nbsp;các&nbsp;lĩnh&nbsp;vực&nbsp;công&nbsp;nghệ&nbsp;trọng&nbsp;điểm.</p><p>🚀&nbsp;Buổi&nbsp;làm&nbsp;việc&nbsp;mở&nbsp;ra&nbsp;nhiều&nbsp;triển&nbsp;vọng&nbsp;hợp&nbsp;tác&nbsp;trong&nbsp;tương&nbsp;lai,&nbsp;góp&nbsp;phần&nbsp;mang&nbsp;đến&nbsp;thêm&nbsp;cơ&nbsp;hội&nbsp;học&nbsp;tập,&nbsp;nghiên&nbsp;cứu&nbsp;và&nbsp;phát&nbsp;triển&nbsp;nghề&nbsp;nghiệp&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;FPT&nbsp;University&nbsp;trong&nbsp;bối&nbsp;cảnh&nbsp;hội&nbsp;nhập&nbsp;toàn&nbsp;cầu.&nbsp;</p>', 'Ngày 17/6 vừa qua, FPT University đã chào đón đoàn đại biểu từ Yangzhou University đến thăm và làm việc nhằm trao đổi về các cơ hội hợp tác trong đào tạo và nghiên cứu. 🤝 Trong khuôn khổ buổi gặp gỡ, hai bên đã thảo luận về tiềm năng triển khai các chương trình thực tập (OJT), thúc đẩy trao đổi học thuật trong lĩnh vực vi điện tử và các ngành liên quan, đồng thời mở rộng cơ hội hợp tác nghiên cứu giữa giảng viên và sinh viên của hai trường. 💡 Các nội dung trao đổi hướng tới việc tăng cường kết nối học thuật quốc tế, tạo điều kiện để sinh viên tiếp cận môi trường học tập và nghiên cứu đa quốc gia, cũng như nâng cao năng lực chuyên môn trong các lĩnh vực công nghệ trọng điểm. 🚀 Buổi làm việc mở ra nhiều triển vọng hợp tác trong tương lai, góp phần mang đến thêm cơ hội học tập, nghiên cứu và phát triển nghề nghiệp cho sinh viên FPT University trong bối cảnh hội nhập toàn cầu.', '2026-08-09 17:12:08', NULL),
	(171087, 171035, 1, '', '<p>On June 17th, FPT University welcomed a delegation from Yangzhou University for a visit and working session to discuss opportunities for cooperation in training and research.</p><p> 🤝 During the meeting, both sides discussed the potential for implementing on-the-job training (OJT) programs, promoting academic exchange in microelectronics and related fields, and expanding opportunities for collaborative research between faculty and students of the two universities.</p><p> 💡 The discussions aim to strengthen international academic connections, facilitate students\' access to a multinational learning and research environment, and enhance their professional capabilities in key technology fields.</p><p> 🚀 This working session opened up many prospects for future cooperation, contributing to providing more learning, research, and career development opportunities for FPT University students in the context of global integration.</p>', 'On June 17th, FPT University welcomed a delegation from Yangzhou University for a visit and working session to discuss opportunities for cooperation in training and research. 🤝 During the meeting, both sides discussed the potential for implementing on-the-job training (OJT) programs, promoting academic exchange in microelectronics and related fields, and expanding opportunities for collaborative research between faculty and students of the two universities. 💡 The discussions aim to strengthen international academic connections, facilitate students\' access to a multinational learning and research environment, and enhance their professional capabilities in key technology fields. 🚀 This working session opened up many prospects for future cooperation, contributing to providing more learning, research, and career development opportunities for FPT University students in the context of global integration.', '2026-08-09 17:12:08', NULL),
	(171088, 171036, 1, '', '<p>Trong&nbsp;khuôn&nbsp;khổ&nbsp;chương&nbsp;trình,&nbsp;hai&nbsp;bên&nbsp;đã&nbsp;trao&nbsp;đổi&nbsp;về&nbsp;các&nbsp;nội&nbsp;dung:&nbsp;tìm&nbsp;hiểu&nbsp;cơ&nbsp;hội&nbsp;hợp&nbsp;tác,&nbsp;chương&nbsp;trình&nbsp;học&nbsp;bổng&nbsp;bậc&nbsp;tiến&nbsp;sĩ,&nbsp;chương&nbsp;trình&nbsp;đào&nbsp;tạo&nbsp;tiếng&nbsp;Anh&nbsp;cho&nbsp;giảng&nbsp;viên&nbsp;cũng&nbsp;như&nbsp;khả&nbsp;năng&nbsp;hợp&nbsp;tác&nbsp;nhằm&nbsp;thúc&nbsp;đẩy&nbsp;cơ&nbsp;hội&nbsp;và&nbsp;năng&nbsp;lực&nbsp;khởi&nbsp;nghiệp&nbsp;cho&nbsp;sinh&nbsp;viên.&nbsp;Trưởng&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;NUS,&nbsp;Prof.&nbsp;Ang&nbsp;Wee&nbsp;Han,&nbsp;Associate&nbsp;Provost,&nbsp;NUS&nbsp;Provost’s&nbsp;Office,&nbsp;đánh&nbsp;giá&nbsp;cao&nbsp;tính&nbsp;thực&nbsp;tiễn&nbsp;trong&nbsp;chương&nbsp;trình&nbsp;đào&nbsp;tạo&nbsp;của&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;và&nbsp;chỉ&nbsp;đạo&nbsp;các&nbsp;trưởng&nbsp;phòng&nbsp;ban&nbsp;trong&nbsp;đoàn&nbsp;thúc&nbsp;đẩy&nbsp;việc&nbsp;hợp&nbsp;tác&nbsp;đi&nbsp;vào&nbsp;thực&nbsp;chất.</p><p></p><p>Chuyến&nbsp;thăm&nbsp;đã&nbsp;giúp&nbsp;hai&nbsp;bên&nbsp;hiểu&nbsp;rõ&nbsp;về&nbsp;nhu&nbsp;cầu&nbsp;phát&nbsp;triển&nbsp;của&nbsp;nhau,&nbsp;góp&nbsp;phần&nbsp;tăng&nbsp;cường&nbsp;kết&nbsp;nối,&nbsp;mở&nbsp;ra&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;hợp&nbsp;tác&nbsp;học&nbsp;thuật&nbsp;và&nbsp;phát&nbsp;triển&nbsp;sinh&nbsp;viên&nbsp;giữa&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;và&nbsp;Đại&nbsp;học&nbsp;Quốc&nbsp;gia&nbsp;Singapore&nbsp;trong&nbsp;thời&nbsp;gian&nbsp;tới.</p><p></p>', 'Trong khuôn khổ chương trình, hai bên đã trao đổi về các nội dung: tìm hiểu cơ hội hợp tác, chương trình học bổng bậc tiến sĩ, chương trình đào tạo tiếng Anh cho giảng viên cũng như khả năng hợp tác nhằm thúc đẩy cơ hội và năng lực khởi nghiệp cho sinh viên. Trưởng đoàn đại biểu NUS, Prof. Ang Wee Han, Associate Provost, NUS Provost’s Office, đánh giá cao tính thực tiễn trong chương trình đào tạo của Trường Đại học FPT và chỉ đạo các trưởng phòng ban trong đoàn thúc đẩy việc hợp tác đi vào thực chất. Chuyến thăm đã giúp hai bên hiểu rõ về nhu cầu phát triển của nhau, góp phần tăng cường kết nối, mở ra nhiều cơ hội hợp tác học thuật và phát triển sinh viên giữa Trường Đại học FPT và Đại học Quốc gia Singapore trong thời gian tới.', '2026-08-09 17:17:07', NULL),
	(171089, 171037, 1, '', '<p>Within the framework of the program, the two sides exchanged views on topics such as exploring cooperation opportunities, doctoral scholarship programs, English language training programs for faculty, and potential collaborations to promote entrepreneurial opportunities and capabilities for students. The head of the NUS delegation, Prof. Ang Wee Han, Associate Provost, NUS Provost\'s Office, highly appreciated the practical nature of FPT University\'s training programs and instructed the heads of departments in the delegation to promote substantive cooperation.</p><p></p><p> The visit helped both sides gain a better understanding of each other\'s development needs, contributing to strengthening connections and opening up many opportunities for academic cooperation and student development between FPT University and the National University of Singapore in the future.</p><p></p>', 'Within the framework of the program, the two sides exchanged views on topics such as exploring cooperation opportunities, doctoral scholarship programs, English language training programs for faculty, and potential collaborations to promote entrepreneurial opportunities and capabilities for students. The head of the NUS delegation, Prof. Ang Wee Han, Associate Provost, NUS Provost\'s Office, highly appreciated the practical nature of FPT University\'s training programs and instructed the heads of departments in the delegation to promote substantive cooperation. The visit helped both sides gain a better understanding of each other\'s development needs, contributing to strengthening connections and opening up many opportunities for academic cooperation and student development between FPT University and the National University of Singapore in the future.', '2026-08-09 17:17:07', NULL),
	(171090, 171038, 1, '', '<p>🎓&nbsp;Trong&nbsp;chuyến&nbsp;thăm,&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;đã&nbsp;tìm&nbsp;hiểu&nbsp;về&nbsp;FPT&nbsp;University,&nbsp;mô&nbsp;hình&nbsp;đào&nbsp;tạo,&nbsp;môi&nbsp;trường&nbsp;học&nbsp;tập&nbsp;và&nbsp;các&nbsp;hoạt&nbsp;động&nbsp;phát&nbsp;triển&nbsp;toàn&nbsp;diện&nbsp;dành&nbsp;cho&nbsp;sinh&nbsp;viên.&nbsp;Sinh&nbsp;viên&nbsp;trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;Hà&nbsp;Nội&nbsp;đã&nbsp;có&nbsp;cơ&nbsp;hội&nbsp;lắng&nbsp;nghe&nbsp;về&nbsp;các&nbsp;chương&nbsp;trình&nbsp;thực&nbsp;tập&nbsp;và&nbsp;giao&nbsp;lưu&nbsp;quốc&nbsp;tế&nbsp;do&nbsp;phía&nbsp;AIESEC&nbsp;giới&nbsp;qua&nbsp;đó&nbsp;mở&nbsp;ra&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;để&nbsp;có&nbsp;thể&nbsp;có&nbsp;thêm&nbsp;trải&nbsp;nghiệm&nbsp;học&nbsp;tập&nbsp;và&nbsp;làm&nbsp;việc&nbsp;toàn&nbsp;cầu.&nbsp;</p><p>✨&nbsp;FPT&nbsp;University&nbsp;xin&nbsp;trân&nbsp;trọng&nbsp;cảm&nbsp;ơn&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;AIESEC&nbsp;Nhật&nbsp;Bản&nbsp;đã&nbsp;dành&nbsp;thời&nbsp;gian&nbsp;đến&nbsp;thăm&nbsp;và&nbsp;làm&nbsp;việc.&nbsp;Hy&nbsp;vọng&nbsp;chuyến&nbsp;gặp&nbsp;gỡ&nbsp;sẽ&nbsp;mở&nbsp;ra&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;hợp&nbsp;tác&nbsp;ý&nbsp;nghĩa&nbsp;trong&nbsp;thời&nbsp;gian&nbsp;tới.</p><p>------------------------------------------------</p>', '🎓 Trong chuyến thăm, đoàn đại biểu đã tìm hiểu về FPT University, mô hình đào tạo, môi trường học tập và các hoạt động phát triển toàn diện dành cho sinh viên. Sinh viên trường Đại học FPT Hà Nội đã có cơ hội lắng nghe về các chương trình thực tập và giao lưu quốc tế do phía AIESEC giới qua đó mở ra nhiều cơ hội cho sinh viên để có thể có thêm trải nghiệm học tập và làm việc toàn cầu. ✨ FPT University xin trân trọng cảm ơn đoàn đại biểu AIESEC Nhật Bản đã dành thời gian đến thăm và làm việc. Hy vọng chuyến gặp gỡ sẽ mở ra nhiều cơ hội hợp tác ý nghĩa trong thời gian tới. ------------------------------------------------', '2026-08-09 22:47:49', NULL),
	(171091, 171039, 1, '', '<p>🎓 During the visit, the delegation learned about FPT University, its training model, learning environment, and comprehensive development activities for students. Students from FPT University Hanoi had the opportunity to learn about internship and international exchange programs introduced by AIESEC, thereby opening up many opportunities for students to gain more global learning and work experience.</p><p> ✨ FPT University would like to express its sincere gratitude to the AIESEC Japan delegation for taking the time to visit and work with us. We hope this meeting will open up many meaningful opportunities for cooperation in the future.</p><p> ------------------------------------------------</p>', '🎓 During the visit, the delegation learned about FPT University, its training model, learning environment, and comprehensive development activities for students. Students from FPT University Hanoi had the opportunity to learn about internship and international exchange programs introduced by AIESEC, thereby opening up many opportunities for students to gain more global learning and work experience. ✨ FPT University would like to express its sincere gratitude to the AIESEC Japan delegation for taking the time to visit and work with us. We hope this meeting will open up many meaningful opportunities for cooperation in the future. ------------------------------------------------', '2026-08-09 22:47:49', NULL),
	(171092, 171040, 1, '', '<p>🎓&nbsp;Trong&nbsp;chuyến&nbsp;thăm,&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;đã&nbsp;tham&nbsp;quan&nbsp;cơ&nbsp;sở&nbsp;vật&nbsp;chất,&nbsp;tìm&nbsp;hiểu&nbsp;mô&nbsp;hình&nbsp;đào&nbsp;tạo,&nbsp;môi&nbsp;trường&nbsp;học&nbsp;tập&nbsp;và&nbsp;các&nbsp;chương&nbsp;trình&nbsp;quốc&nbsp;tế&nbsp;của&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT.&nbsp;Hai&nbsp;bên&nbsp;cũng&nbsp;trao&nbsp;đổi&nbsp;về&nbsp;cơ&nbsp;hội&nbsp;học&nbsp;tập&nbsp;dành&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;tại&nbsp;Brazil&nbsp;và&nbsp;Phần&nbsp;Lan,&nbsp;các&nbsp;chương&nbsp;trình&nbsp;trao&nbsp;đổi&nbsp;sinh&nbsp;viên,&nbsp;cũng&nbsp;như&nbsp;hợp&nbsp;tác&nbsp;trao&nbsp;đổi&nbsp;giảng&nbsp;viên&nbsp;và&nbsp;giáo&nbsp;sư&nbsp;nhằm&nbsp;thúc&nbsp;đẩy&nbsp;hoạt&nbsp;động&nbsp;giảng&nbsp;dạy,&nbsp;nghiên&nbsp;cứu&nbsp;và&nbsp;quốc&nbsp;tế&nbsp;hóa&nbsp;giáo&nbsp;dục.</p><p>✨&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;xin&nbsp;trân&nbsp;trọng&nbsp;cảm&nbsp;ơn&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;từ&nbsp;The&nbsp;Federal&nbsp;University&nbsp;of&nbsp;Rio&nbsp;Grande&nbsp;do&nbsp;Sul&nbsp;đã&nbsp;dành&nbsp;thời&nbsp;gian&nbsp;đến&nbsp;thăm&nbsp;và&nbsp;làm&nbsp;việc.&nbsp;Hy&nbsp;vọng&nbsp;chuyến&nbsp;gặp&nbsp;gỡ&nbsp;sẽ&nbsp;mở&nbsp;ra&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;hợp&nbsp;tác&nbsp;thiết&nbsp;thực&nbsp;và&nbsp;bền&nbsp;vững&nbsp;trong&nbsp;thời&nbsp;gian&nbsp;tới.</p><p>------------------------------------------------</p>', '🎓 Trong chuyến thăm, đoàn đại biểu đã tham quan cơ sở vật chất, tìm hiểu mô hình đào tạo, môi trường học tập và các chương trình quốc tế của Trường Đại học FPT. Hai bên cũng trao đổi về cơ hội học tập dành cho sinh viên tại Brazil và Phần Lan, các chương trình trao đổi sinh viên, cũng như hợp tác trao đổi giảng viên và giáo sư nhằm thúc đẩy hoạt động giảng dạy, nghiên cứu và quốc tế hóa giáo dục. ✨ Trường Đại học FPT xin trân trọng cảm ơn đoàn đại biểu từ The Federal University of Rio Grande do Sul đã dành thời gian đến thăm và làm việc. Hy vọng chuyến gặp gỡ sẽ mở ra nhiều cơ hội hợp tác thiết thực và bền vững trong thời gian tới. ------------------------------------------------', '2026-08-09 23:40:34', NULL),
	(171093, 171041, 1, '', '<p>🎓 During the visit, the delegation toured the facilities, learned about the training model, learning environment, and international programs of FPT University. Both sides also discussed study opportunities for students in Brazil and Finland, student exchange programs, and cooperation in faculty and professor exchanges to promote teaching, research, and the internationalization of education.</p><p> ✨ FPT University would like to express its sincere gratitude to the delegation from The Federal University of Rio Grande do Sul for taking the time to visit and work with us. We hope this meeting will open up many opportunities for practical and sustainable cooperation in the future.</p><p> ------------------------------------------------</p>', '🎓 During the visit, the delegation toured the facilities, learned about the training model, learning environment, and international programs of FPT University. Both sides also discussed study opportunities for students in Brazil and Finland, student exchange programs, and cooperation in faculty and professor exchanges to promote teaching, research, and the internationalization of education. ✨ FPT University would like to express its sincere gratitude to the delegation from The Federal University of Rio Grande do Sul for taking the time to visit and work with us. We hope this meeting will open up many opportunities for practical and sustainable cooperation in the future. ------------------------------------------------', '2026-08-09 23:40:34', NULL),
	(171094, 171042, 1, 'Chào đón đoàn khách tại FPT University Hà Nội', '<p>Trong&nbsp;khuôn&nbsp;khổ&nbsp;chương&nbsp;trình&nbsp;tham&nbsp;quan,&nbsp;FPT&nbsp;University&nbsp;Hà&nbsp;Nội&nbsp;đã&nbsp;chào&nbsp;đón&nbsp;đoàn&nbsp;khách&nbsp;đến&nbsp;tìm&nbsp;hiểu&nbsp;trực&nbsp;tiếp&nbsp;về&nbsp;môi&nbsp;trường&nbsp;học&nbsp;tập&nbsp;và&nbsp;các&nbsp;hoạt&nbsp;động&nbsp;tại&nbsp;trường.</p><p></p><p>Đoàn&nbsp;được&nbsp;giới&nbsp;thiệu&nbsp;tổng&nbsp;quan&nbsp;về&nbsp;FPT&nbsp;University,&nbsp;định&nbsp;hướng&nbsp;đào&nbsp;tạo,&nbsp;chương&nbsp;trình&nbsp;học&nbsp;và&nbsp;những&nbsp;nét&nbsp;đặc&nbsp;trưng&nbsp;trong&nbsp;môi&nbsp;trường&nbsp;giáo&nbsp;dục&nbsp;của&nbsp;nhà&nbsp;trường.&nbsp;Đại&nbsp;diện&nbsp;trường&nbsp;cũng&nbsp;chia&nbsp;sẻ&nbsp;về&nbsp;các&nbsp;cơ&nbsp;hội&nbsp;học&nbsp;tập,&nbsp;phát&nbsp;triển&nbsp;kỹ&nbsp;năng&nbsp;và&nbsp;trải&nbsp;nghiệm&nbsp;dành&nbsp;cho&nbsp;sinh&nbsp;viên.</p>', 'Trong khuôn khổ chương trình tham quan, FPT University Hà Nội đã chào đón đoàn khách đến tìm hiểu trực tiếp về môi trường học tập và các hoạt động tại trường. Đoàn được giới thiệu tổng quan về FPT University, định hướng đào tạo, chương trình học và những nét đặc trưng trong môi trường giáo dục của nhà trường. Đại diện trường cũng chia sẻ về các cơ hội học tập, phát triển kỹ năng và trải nghiệm dành cho sinh viên.', '2026-08-11 15:59:59', NULL),
	(171095, 171042, 2, 'Tham quan cơ sở vật chất và không gian học tập', '<p>Đoàn&nbsp;khách&nbsp;đã&nbsp;tham&nbsp;quan&nbsp;các&nbsp;khu&nbsp;vực&nbsp;học&nbsp;tập&nbsp;và&nbsp;sinh&nbsp;hoạt&nbsp;tại&nbsp;FPT&nbsp;University&nbsp;Hà&nbsp;Nội&nbsp;như&nbsp;giảng&nbsp;đường,&nbsp;phòng&nbsp;học,&nbsp;thư&nbsp;viện,&nbsp;khu&nbsp;vực&nbsp;sinh&nbsp;hoạt&nbsp;chung&nbsp;và&nbsp;các&nbsp;không&nbsp;gian&nbsp;phục&nbsp;vụ&nbsp;hoạt&nbsp;động&nbsp;của&nbsp;sinh&nbsp;viên.</p><p></p><p>Thông&nbsp;qua&nbsp;hoạt&nbsp;động&nbsp;tham&nbsp;quan&nbsp;thực&nbsp;tế,&nbsp;các&nbsp;thành&nbsp;viên&nbsp;trong&nbsp;đoàn&nbsp;có&nbsp;cơ&nbsp;hội&nbsp;quan&nbsp;sát&nbsp;môi&nbsp;trường&nbsp;học&nbsp;tập&nbsp;hiện&nbsp;đại,&nbsp;năng&nbsp;động&nbsp;cũng&nbsp;như&nbsp;tìm&nbsp;hiểu&nbsp;cách&nbsp;nhà&nbsp;trường&nbsp;tổ&nbsp;chức&nbsp;các&nbsp;hoạt&nbsp;động&nbsp;học&nbsp;tập&nbsp;và&nbsp;trải&nbsp;nghiệm&nbsp;cho&nbsp;sinh&nbsp;viên.</p>', 'Đoàn khách đã tham quan các khu vực học tập và sinh hoạt tại FPT University Hà Nội như giảng đường, phòng học, thư viện, khu vực sinh hoạt chung và các không gian phục vụ hoạt động của sinh viên. Thông qua hoạt động tham quan thực tế, các thành viên trong đoàn có cơ hội quan sát môi trường học tập hiện đại, năng động cũng như tìm hiểu cách nhà trường tổ chức các hoạt động học tập và trải nghiệm cho sinh viên.', '2026-08-11 15:59:59', NULL),
	(171096, 171042, 3, 'Giao lưu và chia sẻ cùng đại diện nhà trường', '<p>Bên&nbsp;cạnh&nbsp;hoạt&nbsp;động&nbsp;tham&nbsp;quan,&nbsp;đoàn&nbsp;khách&nbsp;còn&nbsp;có&nbsp;thời&nbsp;gian&nbsp;giao&nbsp;lưu&nbsp;và&nbsp;trao&nbsp;đổi&nbsp;với&nbsp;đại&nbsp;diện&nbsp;FPT&nbsp;University&nbsp;Hà&nbsp;Nội.</p><p></p><p>Các&nbsp;nội&nbsp;dung&nbsp;trao&nbsp;đổi&nbsp;tập&nbsp;trung&nbsp;vào&nbsp;chương&nbsp;trình&nbsp;đào&nbsp;tạo,&nbsp;phương&nbsp;pháp&nbsp;học&nbsp;tập,&nbsp;hoạt&nbsp;động&nbsp;sinh&nbsp;viên&nbsp;và&nbsp;những&nbsp;cơ&nbsp;hội&nbsp;phát&nbsp;triển&nbsp;trong&nbsp;quá&nbsp;trình&nbsp;học&nbsp;tại&nbsp;trường.&nbsp;Những&nbsp;câu&nbsp;hỏi&nbsp;của&nbsp;đoàn&nbsp;cũng&nbsp;được&nbsp;đại&nbsp;diện&nbsp;nhà&nbsp;trường&nbsp;giải&nbsp;đáp&nbsp;trực&nbsp;tiếp&nbsp;trong&nbsp;không&nbsp;khí&nbsp;cởi&nbsp;mở&nbsp;và&nbsp;thân&nbsp;thiện.</p>', 'Bên cạnh hoạt động tham quan, đoàn khách còn có thời gian giao lưu và trao đổi với đại diện FPT University Hà Nội. Các nội dung trao đổi tập trung vào chương trình đào tạo, phương pháp học tập, hoạt động sinh viên và những cơ hội phát triển trong quá trình học tại trường. Những câu hỏi của đoàn cũng được đại diện nhà trường giải đáp trực tiếp trong không khí cởi mở và thân thiện.', '2026-08-11 15:59:59', NULL),
	(171097, 171042, 4, 'Khép lại chuyến tham quan nhiều trải nghiệm', '<p>Chuyến&nbsp;tham&nbsp;quan&nbsp;đã&nbsp;kết&nbsp;thúc&nbsp;với&nbsp;nhiều&nbsp;trải&nbsp;nghiệm&nbsp;tích&nbsp;cực&nbsp;và&nbsp;những&nbsp;thông&nbsp;tin&nbsp;hữu&nbsp;ích&nbsp;dành&nbsp;cho&nbsp;đoàn&nbsp;khách.</p><p></p><p>FPT&nbsp;University&nbsp;Hà&nbsp;Nội&nbsp;hy&nbsp;vọng&nbsp;chương&nbsp;trình&nbsp;đã&nbsp;giúp&nbsp;các&nbsp;thành&nbsp;viên&nbsp;trong&nbsp;đoàn&nbsp;có&nbsp;cái&nbsp;nhìn&nbsp;trực&nbsp;quan&nbsp;hơn&nbsp;về&nbsp;môi&nbsp;trường&nbsp;học&nbsp;tập,&nbsp;cơ&nbsp;sở&nbsp;vật&nbsp;chất&nbsp;và&nbsp;văn&nbsp;hóa&nbsp;của&nbsp;nhà&nbsp;trường,&nbsp;đồng&nbsp;thời&nbsp;mở&nbsp;ra&nbsp;thêm&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;kết&nbsp;nối&nbsp;trong&nbsp;tương&nbsp;lai.</p>', 'Chuyến tham quan đã kết thúc với nhiều trải nghiệm tích cực và những thông tin hữu ích dành cho đoàn khách. FPT University Hà Nội hy vọng chương trình đã giúp các thành viên trong đoàn có cái nhìn trực quan hơn về môi trường học tập, cơ sở vật chất và văn hóa của nhà trường, đồng thời mở ra thêm nhiều cơ hội kết nối trong tương lai.', '2026-08-11 15:59:59', NULL),
	(171098, 171043, 1, 'Welcoming the delegation at FPT University Hanoi.', '<p>As part of the tour program, FPT University Hanoi welcomed a delegation to learn firsthand about the learning environment and activities at the university.</p><p></p><p> The delegation was given an overview of FPT University, its training orientation, academic programs, and the unique characteristics of the school\'s educational environment. Representatives from the university also shared information about learning opportunities, skill development, and experiences available to students.</p>', 'As part of the tour program, FPT University Hanoi welcomed a delegation to learn firsthand about the learning environment and activities at the university. The delegation was given an overview of FPT University, its training orientation, academic programs, and the unique characteristics of the school\'s educational environment. Representatives from the university also shared information about learning opportunities, skill development, and experiences available to students.', '2026-08-11 15:59:59', NULL),
	(171099, 171043, 2, 'Tour the facilities and learning spaces.', '<p>The delegation toured the learning and living areas at FPT University Hanoi, including lecture halls, classrooms, the library, common areas, and spaces for student activities.</p><p></p><p> Through this field trip, the delegation members had the opportunity to observe a modern and dynamic learning environment, as well as learn about how the school organizes learning and experiential activities for students.</p>', 'The delegation toured the learning and living areas at FPT University Hanoi, including lecture halls, classrooms, the library, common areas, and spaces for student activities. Through this field trip, the delegation members had the opportunity to observe a modern and dynamic learning environment, as well as learn about how the school organizes learning and experiential activities for students.', '2026-08-11 15:59:59', NULL),
	(171100, 171043, 3, 'Interact and share with school representatives.', '<p>Besides sightseeing, the delegation also had time to interact and exchange ideas with representatives from FPT University Hanoi.</p><p></p><p> The discussions focused on the training program, learning methods, student activities, and development opportunities during their studies at the school. The delegation\'s questions were also answered directly by school representatives in an open and friendly atmosphere.</p>', 'Besides sightseeing, the delegation also had time to interact and exchange ideas with representatives from FPT University Hanoi. The discussions focused on the training program, learning methods, student activities, and development opportunities during their studies at the school. The delegation\'s questions were also answered directly by school representatives in an open and friendly atmosphere.', '2026-08-11 15:59:59', NULL),
	(171101, 171043, 4, 'The tour, filled with many experiences, has come to an end.', '<p>The tour concluded with many positive experiences and useful information for the group of visitors.</p><p></p><p> FPT University Hanoi hopes that the program has helped the delegation members gain a more visual understanding of the learning environment, facilities, and culture of the university, while also opening up more opportunities for future networking.</p>', 'The tour concluded with many positive experiences and useful information for the group of visitors. FPT University Hanoi hopes that the program has helped the delegation members gain a more visual understanding of the learning environment, facilities, and culture of the university, while also opening up more opportunities for future networking.', '2026-08-11 15:59:59', NULL),
	(171102, 171044, 1, '🔗Link đăng ký: https://forms.gle/VuQjpWtNmuaKguTm9\n❗Hạn đăng ký: 07/04/2026', '<p>📌&nbsp;Chuyến&nbsp;thăm&nbsp;thú&nbsp;những&nbsp;điều&nbsp;hay&nbsp;ho&nbsp;của&nbsp;thủ&nbsp;đô&nbsp;xứ&nbsp;sở&nbsp;Chùa&nbsp;Vàng&nbsp;có&nbsp;gì&nbsp;vui&nbsp;nhỉ?!</p><p>👉&nbsp;Campus&nbsp;tour&nbsp;&amp;&nbsp;Sharing&nbsp;session&nbsp;tại&nbsp;trường&nbsp;đối&nbsp;tác&nbsp;Bangkok&nbsp;–&nbsp;giao&nbsp;lưu,&nbsp;học&nbsp;hỏi,&nbsp;kết&nbsp;nối&nbsp;thêm&nbsp;với&nbsp;những&nbsp;người&nbsp;bạn&nbsp;quốc&nbsp;tế</p><p>👉&nbsp;Gắn&nbsp;kết&nbsp;tình&nbsp;bạn&nbsp;với&nbsp;các&nbsp;“đồng&nbsp;đội”&nbsp;của&nbsp;mình</p><p>👉&nbsp;Lạc&nbsp;vào&nbsp;thiên&nbsp;đường&nbsp;mua&nbsp;sắm&nbsp;truyền&nbsp;thống&nbsp;Chatuchak,&nbsp;khám&nbsp;phá&nbsp;loạt&nbsp;thương&nbsp;hiệu&nbsp;từ&nbsp;local&nbsp;đến&nbsp;quốc&nbsp;tế&nbsp;ở&nbsp;các&nbsp;trung&nbsp;tâm&nbsp;thương&nbsp;mại&nbsp;nổi&nbsp;tiếng&nbsp;như&nbsp;Icon&nbsp;Siam,&nbsp;MBK&nbsp;Center,&nbsp;CentralWorld…</p><p>👉&nbsp;Khám&nbsp;phá&nbsp;văn&nbsp;hóa,&nbsp;truyền&nbsp;thống&nbsp;xa&nbsp;xưa&nbsp;qua&nbsp;các&nbsp;ngôi&nbsp;chùa,&nbsp;cung&nbsp;điện…</p><p>👉&nbsp;Thưởng&nbsp;thức&nbsp;những&nbsp;món&nbsp;ăn&nbsp;đường&nbsp;phố&nbsp;đã&nbsp;“làm&nbsp;mưa&nbsp;làm&nbsp;gió”&nbsp;trên&nbsp;Review&nbsp;Ti.ktok&nbsp;như&nbsp;gỏi&nbsp;chua&nbsp;cay&nbsp;Son&nbsp;Tam,&nbsp;xiên&nbsp;que&nbsp;nướng,&nbsp;hải&nbsp;sản&nbsp;sống…&nbsp;ở&nbsp;chợ&nbsp;đêm&nbsp;Jodd&nbsp;Fairs,&nbsp;ChinaTown.</p><p>👉Cơ&nbsp;hội&nbsp;để&nbsp;các&nbsp;Cóc&nbsp;tiếp&nbsp;thêm&nbsp;nhiên&nbsp;liệu&nbsp;cho&nbsp;kì&nbsp;Summer&nbsp;sắp&nbsp;tớiii</p><p>🌟&nbsp;Nhanh&nbsp;tay&nbsp;tag&nbsp;đồng&nbsp;đội&nbsp;cùng&nbsp;điền&nbsp;đơn&nbsp;để&nbsp;“join”&nbsp;vào&nbsp;chuyến&nbsp;Study&nbsp;Tour&nbsp;tại&nbsp;Bangkok,&nbsp;Thái&nbsp;Lan&nbsp;cùng&nbsp;IC&nbsp;nhaaaa!!</p><p>------------------------------------------------</p><p>THÔNG&nbsp;TIN&nbsp;CHƯƠNG&nbsp;TRÌNH</p><p>📍Thời&nbsp;gian&nbsp;(Dự&nbsp;kiến):&nbsp;06/05-09/05/2026&nbsp;(4N3Đ)</p><p>📍&nbsp;Đối&nbsp;tượng:&nbsp;Sinh&nbsp;viên&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;Hà&nbsp;Nội</p><p>📍Số&nbsp;lượng:&nbsp;20&nbsp;sinh&nbsp;viên&nbsp;</p><p>📍Chi&nbsp;phí:&nbsp;7,200,000&nbsp;VNĐ,&nbsp;bao&nbsp;gồm:&nbsp;Vé&nbsp;máy&nbsp;bay&nbsp;khứ&nbsp;hồi,&nbsp;chỗ&nbsp;ở,&nbsp;bảo&nbsp;hiểm,&nbsp;tham&nbsp;gia&nbsp;hoạt&nbsp;động,&nbsp;một&nbsp;phần&nbsp;chi&nbsp;phí&nbsp;ăn&nbsp;uống,&nbsp;di&nbsp;chuyển&nbsp;đủ&nbsp;cho&nbsp;các&nbsp;bữa&nbsp;ăn&nbsp;cơ&nbsp;bản&nbsp;trong&nbsp;ngày.&nbsp;Ngoài&nbsp;ra,&nbsp;sinh&nbsp;viên&nbsp;cần&nbsp;tự&nbsp;chi&nbsp;trả&nbsp;các&nbsp;khoản&nbsp;phí&nbsp;cá&nbsp;nhân</p><p>📍&nbsp;Hạn&nbsp;đăng&nbsp;ký:&nbsp;07/04/2026</p><p>📍&nbsp;Link&nbsp;đăng&nbsp;ký:&nbsp;https://forms.gle/VuQjpWtNmuaKguTm9</p><p>💡Lưu&nbsp;ý:&nbsp;Sinh&nbsp;viên&nbsp;cần&nbsp;có&nbsp;hộ&nbsp;chiếu&nbsp;trước&nbsp;ngày&nbsp;07/04/2026&nbsp;và&nbsp;hộ&nbsp;chiếu&nbsp;còn&nbsp;hạn&nbsp;tối&nbsp;thiểu&nbsp;6&nbsp;tháng&nbsp;so&nbsp;với&nbsp;thời&nbsp;gian&nbsp;diễn&nbsp;ra&nbsp;chương&nbsp;trình</p><p>------------------------------------------------</p><p>ℹ️Mọi&nbsp;thắc&nbsp;mắc&nbsp;xin&nbsp;liên&nbsp;hệ:</p><p>-&nbsp;Địa&nbsp;điểm:&nbsp;Phòng&nbsp;Delta&nbsp;102,&nbsp;Trường&nbsp;Đại&nbsp;học</p><p>-&nbsp;SĐT:&nbsp;(+84)&nbsp;24&nbsp;6680&nbsp;5910&nbsp;hoặc&nbsp;0961593742&nbsp;(Chị&nbsp;Hà)</p><p>-&nbsp;Fanpage:&nbsp;Phòng&nbsp;Hợp&nbsp;tác&nbsp;quốc&nbsp;tế&nbsp;FPTU&nbsp;Hà&nbsp;Nội</p><p>-&nbsp;Email:&nbsp;international.fptu@fpt.edu.vn&nbsp;hoặc&nbsp;hahkn@fe.edu.vn&nbsp;(Chị&nbsp;Hà)</p><p>-&nbsp;Group&nbsp;Review&nbsp;chương&nbsp;trình&nbsp;quốc&nbsp;tế&nbsp;Đại&nbsp;học&nbsp;FPT</p>', '📌 Chuyến thăm thú những điều hay ho của thủ đô xứ sở Chùa Vàng có gì vui nhỉ?! 👉 Campus tour & Sharing session tại trường đối tác Bangkok – giao lưu, học hỏi, kết nối thêm với những người bạn quốc tế 👉 Gắn kết tình bạn với các “đồng đội” của mình 👉 Lạc vào thiên đường mua sắm truyền thống Chatuchak, khám phá loạt thương hiệu từ local đến quốc tế ở các trung tâm thương mại nổi tiếng như Icon Siam, MBK Center, CentralWorld… 👉 Khám phá văn hóa, truyền thống xa xưa qua các ngôi chùa, cung điện… 👉 Thưởng thức những món ăn đường phố đã “làm mưa làm gió” trên Review Ti.ktok như gỏi chua cay Son Tam, xiên que nướng, hải sản sống… ở chợ đêm Jodd Fairs, ChinaTown. 👉Cơ hội để các Cóc tiếp thêm nhiên liệu cho kì Summer sắp tớiii 🌟 Nhanh tay tag đồng đội cùng điền đơn để “join” vào chuyến Study Tour tại Bangkok, Thái Lan cùng IC nhaaaa!! ------------------------------------------------ THÔNG TIN CHƯƠNG TRÌNH 📍Thời gian (Dự kiến): 06/05-09/05/2026 (4N3Đ) 📍 Đối tượng: Sinh viên Trường Đại học FPT Hà Nội 📍Số lượng: 20 sinh viên 📍Chi phí: 7,200,000 VNĐ, bao gồm: Vé máy bay khứ hồi, chỗ ở, bảo hiểm, tham gia hoạt động, một phần chi phí ăn uống, di chuyển đủ cho các bữa ăn cơ bản trong ngày. Ngoài ra, sinh viên cần tự chi trả các khoản phí cá nhân 📍 Hạn đăng ký: 07/04/2026 📍 Link đăng ký: https://forms.gle/VuQjpWtNmuaKguTm9 💡Lưu ý: Sinh viên cần có hộ chiếu trước ngày 07/04/2026 và hộ chiếu còn hạn tối thiểu 6 tháng so với thời gian diễn ra chương trình ------------------------------------------------ ℹ️Mọi thắc mắc xin liên hệ: - Địa điểm: Phòng Delta 102, Trường Đại học - SĐT: (+84) 24 6680 5910 hoặc 0961593742 (Chị Hà) - Fanpage: Phòng Hợp tác quốc tế FPTU Hà Nội - Email: international.fptu@fpt.edu.vn hoặc hahkn@fe.edu.vn (Chị Hà) - Group Review chương trình quốc tế Đại học FPT', '2026-08-13 17:11:15', NULL),
	(171103, 171045, 1, '🔗Registration link: https://forms.gle/VuQjpWtNmuaKguTm9\n❗Registration deadline: April 7, 2026', '<p>📌 What\'s so fun about exploring the wonders of the capital of the Land of the Golden Pagodas?!</p><p> 👉 Campus tour &amp; Sharing session at our partner school in Bangkok – interact, learn, and connect with international friends.</p><p> 👉 Strengthen friendships with your "teammates"</p><p> 👉 Immerse yourself in the traditional shopping paradise of Chatuchak, and discover a range of brands from local to international at famous shopping malls such as Icon Siam, MBK Center, CentralWorld…</p><p> 👉 Discover ancient culture and traditions through temples, palaces, and more…</p><p> 👉 Enjoy the street food that\'s been trending on TikTok reviews, such as Son Tam spicy and sour salad, grilled skewers, and raw seafood, at Jodd Fairs night market in Chinatown.</p><p> 👉An opportunity for the Frogs to refuel for the upcoming Summer!</p><p> 🌟 Quickly tag your teammates to fill out the application and "join" the Study Tour in Bangkok, Thailand with IC!!!</p><p> ------------------------------------------------</p><p> PROGRAM INFORMATION</p><p> 📍Date (Estimated): May 6-9, 2026 (4 days, 3 nights)</p><p> 📍 Target audience: Students of FPT University Hanoi</p><p> Number of students: 20</p><p> 📍Cost: 7,200,000 VND, including: Round-trip airfare, accommodation, insurance, participation in activities, and a portion of food and transportation costs sufficient for basic meals throughout the day. Students are responsible for any additional personal expenses.</p><p> 📍 Registration deadline: April 7, 2026</p><p> 📍 Registration link: https://forms.gle/VuQjpWtNmuaKguTm9</p><p> 💡Note: Students must have a passport before April 7, 2026, and the passport must be valid for at least 6 months beyond the program date.</p><p> ------------------------------------------------</p><p> ℹ️For any questions, please contact:</p><p> - Location: Delta Room 102, University</p><p> - Phone number: (+84) 24 6680 5910 or 0961593742 (Ms. Ha)</p><p> - Fanpage: FPTU Hanoi International Cooperation Department</p><p> - Email: international.fptu@fpt.edu.vn or hahkn@fe.edu.vn (Ms. Ha)</p><p> - Group Review of FPT University\'s International Programs</p>', '📌 What\'s so fun about exploring the wonders of the capital of the Land of the Golden Pagodas?! 👉 Campus tour & Sharing session at our partner school in Bangkok – interact, learn, and connect with international friends. 👉 Strengthen friendships with your "teammates" 👉 Immerse yourself in the traditional shopping paradise of Chatuchak, and discover a range of brands from local to international at famous shopping malls such as Icon Siam, MBK Center, CentralWorld… 👉 Discover ancient culture and traditions through temples, palaces, and more… 👉 Enjoy the street food that\'s been trending on TikTok reviews, such as Son Tam spicy and sour salad, grilled skewers, and raw seafood, at Jodd Fairs night market in Chinatown. 👉An opportunity for the Frogs to refuel for the upcoming Summer! 🌟 Quickly tag your teammates to fill out the application and "join" the Study Tour in Bangkok, Thailand with IC!!! ------------------------------------------------ PROGRAM INFORMATION 📍Date (Estimated): May 6-9, 2026 (4 days, 3 nights) 📍 Target audience: Students of FPT University Hanoi Number of students: 20 📍Cost: 7,200,000 VND, including: Round-trip airfare, accommodation, insurance, participation in activities, and a portion of food and transportation costs sufficient for basic meals throughout the day. Students are responsible for any additional personal expenses. 📍 Registration deadline: April 7, 2026 📍 Registration link: https://forms.gle/VuQjpWtNmuaKguTm9 💡Note: Students must have a passport before April 7, 2026, and the passport must be valid for at least 6 months beyond the program date. ------------------------------------------------ ℹ️For any questions, please contact: - Location: Delta Room 102, University - Phone number: (+84) 24 6680 5910 or 0961593742 (Ms. Ha) - Fanpage: FPTU Hanoi International Cooperation Department - Email: international.fptu@fpt.edu.vn or hahkn@fe.edu.vn (Ms. Ha) - Group Review of FPT University\'s International Programs', '2026-08-13 17:11:15', NULL),
	(171104, 171046, 1, '', '<p>Trong&nbsp;khuôn&nbsp;khổ&nbsp;chương&nbsp;trình,&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;đã&nbsp;tham&nbsp;quan&nbsp;cơ&nbsp;sở&nbsp;vật&nbsp;chất,&nbsp;tìm&nbsp;hiểu&nbsp;về&nbsp;mô&nbsp;hình&nbsp;đào&nbsp;tạo,&nbsp;môi&nbsp;trường&nbsp;học&nbsp;tập&nbsp;và&nbsp;hệ&nbsp;sinh&nbsp;thái&nbsp;giáo&nbsp;dục&nbsp;của&nbsp;FPT.&nbsp;Đồng&nbsp;thời,&nbsp;hai&nbsp;bên&nbsp;đã&nbsp;có&nbsp;những&nbsp;trao&nbsp;đổi&nbsp;xoay&nbsp;quanh&nbsp;hành&nbsp;trình&nbsp;chuyển&nbsp;đổi&nbsp;AI&nbsp;của&nbsp;FPT,&nbsp;từ&nbsp;chiến&nbsp;lược&nbsp;phát&nbsp;triển,&nbsp;ứng&nbsp;dụng&nbsp;công&nbsp;nghệ&nbsp;đến&nbsp;tầm&nbsp;nhìn&nbsp;xây&nbsp;dựng&nbsp;hệ&nbsp;sinh&nbsp;thái&nbsp;trí&nbsp;tuệ&nbsp;nhân&nbsp;tạo&nbsp;phục&nbsp;vụ&nbsp;giáo&nbsp;dục,&nbsp;doanh&nbsp;nghiệp&nbsp;và&nbsp;xã&nbsp;hội.</p><p>✨&nbsp;Một&nbsp;cuộc&nbsp;gặp&nbsp;gỡ&nbsp;ý&nbsp;nghĩa,&nbsp;mở&nbsp;ra&nbsp;những&nbsp;kết&nbsp;nối&nbsp;mới&nbsp;và&nbsp;nhiều&nbsp;kỳ&nbsp;vọng&nbsp;cho&nbsp;những&nbsp;dự&nbsp;án&nbsp;hợp&nbsp;tác&nbsp;sắp&nbsp;tới.</p><p>📸&nbsp;Cùng&nbsp;nhìn&nbsp;lại&nbsp;những&nbsp;khoảnh&nbsp;khắc&nbsp;nổi&nbsp;bật&nbsp;trong&nbsp;chuyến&nbsp;thăm&nbsp;của&nbsp;đoàn&nbsp;Harvard&nbsp;Business&nbsp;School&nbsp;tại&nbsp;FPT&nbsp;University!</p><p>------------------------------------------------</p><p>&nbsp;ℹ️Mọi&nbsp;thắc&nbsp;mắc&nbsp;xin&nbsp;liên&nbsp;hệ:</p><p>-&nbsp;Địa&nbsp;điểm:&nbsp;Phòng&nbsp;L209,&nbsp;Toà&nbsp;nhà&nbsp;Alpha,&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;Hà&nbsp;Nội&nbsp;</p><p>-&nbsp;SĐT:&nbsp;(+84)&nbsp;24&nbsp;6680&nbsp;5910</p><p>-&nbsp;Fanpage:&nbsp;Phòng&nbsp;Hợp&nbsp;tác&nbsp;quốc&nbsp;tế&nbsp;FPTU&nbsp;Hà&nbsp;Nội</p><p>-&nbsp;Email:&nbsp;international.fptu@fpt.edu.vn</p><p>-&nbsp;Group&nbsp;Review&nbsp;chương&nbsp;trình&nbsp;quốc&nbsp;tế&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;</p>', 'Trong khuôn khổ chương trình, đoàn đại biểu đã tham quan cơ sở vật chất, tìm hiểu về mô hình đào tạo, môi trường học tập và hệ sinh thái giáo dục của FPT. Đồng thời, hai bên đã có những trao đổi xoay quanh hành trình chuyển đổi AI của FPT, từ chiến lược phát triển, ứng dụng công nghệ đến tầm nhìn xây dựng hệ sinh thái trí tuệ nhân tạo phục vụ giáo dục, doanh nghiệp và xã hội. ✨ Một cuộc gặp gỡ ý nghĩa, mở ra những kết nối mới và nhiều kỳ vọng cho những dự án hợp tác sắp tới. 📸 Cùng nhìn lại những khoảnh khắc nổi bật trong chuyến thăm của đoàn Harvard Business School tại FPT University! ------------------------------------------------ ℹ️Mọi thắc mắc xin liên hệ: - Địa điểm: Phòng L209, Toà nhà Alpha, Trường Đại học FPT Hà Nội - SĐT: (+84) 24 6680 5910 - Fanpage: Phòng Hợp tác quốc tế FPTU Hà Nội - Email: international.fptu@fpt.edu.vn - Group Review chương trình quốc tế Đại học FPT', '2026-08-13 22:10:09', NULL),
	(171105, 171047, 1, '', '<p>As part of the program, the delegation toured FPT\'s facilities, learned about its training model, learning environment, and educational ecosystem. Simultaneously, both sides exchanged views on FPT\'s AI transformation journey, from development strategies and technology applications to its vision for building an artificial intelligence ecosystem to serve education, businesses, and society.</p><p> ✨ A meaningful meeting, opening up new connections and raising expectations for future collaborative projects.</p><p> 📸 Let\'s look back at some of the highlights from the Harvard Business School delegation\'s visit to FPT University!</p><p> ------------------------------------------------</p><p> ℹ️For any questions, please contact:</p><p> - Location: Room L209, Alpha Building, FPT University Hanoi</p><p> - Phone number: (+84) 24 6680 5910</p><p> - Fanpage: FPTU Hanoi International Cooperation Department</p><p> - Email: international.fptu@fpt.edu.vn</p><p> - Group Review of FPT University\'s International Programs</p>', 'As part of the program, the delegation toured FPT\'s facilities, learned about its training model, learning environment, and educational ecosystem. Simultaneously, both sides exchanged views on FPT\'s AI transformation journey, from development strategies and technology applications to its vision for building an artificial intelligence ecosystem to serve education, businesses, and society. ✨ A meaningful meeting, opening up new connections and raising expectations for future collaborative projects. 📸 Let\'s look back at some of the highlights from the Harvard Business School delegation\'s visit to FPT University! ------------------------------------------------ ℹ️For any questions, please contact: - Location: Room L209, Alpha Building, FPT University Hanoi - Phone number: (+84) 24 6680 5910 - Fanpage: FPTU Hanoi International Cooperation Department - Email: international.fptu@fpt.edu.vn - Group Review of FPT University\'s International Programs', '2026-08-13 22:10:09', NULL),
	(171106, 171048, 1, '', '<p>Buổi&nbsp;lễ&nbsp;có&nbsp;sự&nbsp;tham&nbsp;dự&nbsp;của&nbsp;lãnh&nbsp;đạo&nbsp;Kanto&nbsp;Seiki&nbsp;và&nbsp;đại&nbsp;diện&nbsp;tỉnh&nbsp;Gunma.&nbsp;Chủ&nbsp;tịch&nbsp;Takeshi&nbsp;Tozawa&nbsp;đã&nbsp;trực&nbsp;tiếp&nbsp;trao&nbsp;chứng&nbsp;nhận&nbsp;hoàn&nbsp;thành&nbsp;thực&nbsp;tập&nbsp;cho&nbsp;Khoa,&nbsp;đồng&nbsp;thời&nbsp;đánh&nbsp;giá&nbsp;cao&nbsp;những&nbsp;đóng&nbsp;góp&nbsp;của&nbsp;bạn&nbsp;trong&nbsp;suốt&nbsp;hai&nbsp;tuần&nbsp;làm&nbsp;việc.&nbsp;Khoa&nbsp;cũng&nbsp;chia&nbsp;sẻ&nbsp;bạn&nbsp;đã&nbsp;có&nbsp;một&nbsp;khoảng&nbsp;thời&nbsp;gian&nbsp;ý&nbsp;nghĩa&nbsp;và&nbsp;thể&nbsp;hiện&nbsp;nguyện&nbsp;vọng&nbsp;muốn&nbsp;quay&nbsp;trở&nbsp;lại&nbsp;Nhật&nbsp;Bản&nbsp;để&nbsp;làm&nbsp;việc.</p><p>Đáng&nbsp;chú&nbsp;ý,&nbsp;sự&nbsp;kiện&nbsp;này&nbsp;đã&nbsp;được&nbsp;đưa&nbsp;tin&nbsp;rộng&nbsp;rãi&nbsp;trên&nbsp;các&nbsp;kênh&nbsp;truyền&nbsp;thông&nbsp;lớn&nbsp;tại&nbsp;Nhật&nbsp;Bản&nbsp;như&nbsp;Yahoo!&nbsp;Nhật&nbsp;Bản,&nbsp;Nikkei,&nbsp;truyền&nbsp;hình&nbsp;Gunma&nbsp;và&nbsp;báo&nbsp;giấy&nbsp;địa&nbsp;phương.&nbsp;Điều&nbsp;đó&nbsp;cho&nbsp;thấy&nbsp;tầm&nbsp;quan&nbsp;trọng&nbsp;của&nbsp;chương&nbsp;trình,&nbsp;không&nbsp;chỉ&nbsp;với&nbsp;cá&nbsp;nhân&nbsp;Khoa&nbsp;mà&nbsp;còn&nbsp;với&nbsp;mối&nbsp;quan&nbsp;hệ&nbsp;hợp&nbsp;tác&nbsp;giữa&nbsp;tỉnh&nbsp;Gunma&nbsp;và&nbsp;Đại&nbsp;học&nbsp;FPT.</p><p>Nguyễn&nbsp;Đăng&nbsp;Khoa&nbsp;là&nbsp;sinh&nbsp;viên&nbsp;duy&nbsp;nhất&nbsp;được&nbsp;chọn&nbsp;trong&nbsp;chương&nbsp;trình&nbsp;học&nbsp;bổng&nbsp;thực&nbsp;tập&nbsp;sinh&nbsp;tài&nbsp;năng&nbsp;tại&nbsp;tỉnh&nbsp;Gunma,&nbsp;Nhật&nbsp;Bản.&nbsp;Đây&nbsp;là&nbsp;kết&nbsp;quả&nbsp;của&nbsp;quá&nbsp;trình&nbsp;hợp&nbsp;tác&nbsp;nhiều&nbsp;năm&nbsp;giữa&nbsp;trường&nbsp;Đại&nbsp;học&nbsp;FPT,&nbsp;tỉnh&nbsp;Gunma&nbsp;cùng&nbsp;các&nbsp;đối&nbsp;tác&nbsp;đồng&nbsp;hành.&nbsp;Sự&nbsp;kiện&nbsp;này&nbsp;đánh&nbsp;một&nbsp;dấu&nbsp;mốc&nbsp;quan&nbsp;trọng,&nbsp;thể&nbsp;hiện&nbsp;nguyện&nbsp;vọng&nbsp;hợp&nbsp;tác&nbsp;thực&nbsp;chất&nbsp;giữa&nbsp;các&nbsp;đơn&nbsp;vị,&nbsp;tạo&nbsp;tiền&nbsp;đề&nbsp;cho&nbsp;những&nbsp;chương&nbsp;trình&nbsp;ý&nbsp;nghĩa&nbsp;hơn&nbsp;trong&nbsp;tương&nbsp;lai.</p><p>Trong&nbsp;bối&nbsp;cảnh&nbsp;Nhật&nbsp;Bản&nbsp;đang&nbsp;tìm&nbsp;kiếm&nbsp;nhân&nbsp;lực&nbsp;CNTT&nbsp;chất&nbsp;lượng&nbsp;cao&nbsp;từ&nbsp;Việt&nbsp;Nam,&nbsp;trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;tự&nbsp;tin&nbsp;là&nbsp;cơ&nbsp;sở&nbsp;đào&nbsp;tạo&nbsp;đáp&nbsp;ứng&nbsp;được&nbsp;những&nbsp;yêu&nbsp;cầu&nbsp;khắt&nbsp;khe&nbsp;mà&nbsp;đối&nbsp;tác&nbsp;Nhật&nbsp;Bản&nbsp;đưa&nbsp;ra:&nbsp;truyền&nbsp;thống&nbsp;hợp&nbsp;tác&nbsp;lâu&nbsp;đời,&nbsp;chương&nbsp;trình&nbsp;CNTT&nbsp;gắn&nbsp;liền&nbsp;với&nbsp;thực&nbsp;tiễn&nbsp;và&nbsp;sinh&nbsp;viên&nbsp;được&nbsp;trang&nbsp;bị&nbsp;khả&nbsp;năng&nbsp;tiếng&nbsp;Nhật&nbsp;đáp&nbsp;ứng&nbsp;nhu&nbsp;cầu&nbsp;tuyển&nbsp;dụng&nbsp;từ&nbsp;doanh&nbsp;nghiệp.</p><p>-----------------------------------------------------</p><p>ℹ️&nbsp;Mọi&nbsp;thắc&nbsp;mắc&nbsp;xin&nbsp;vui&nbsp;lòng&nbsp;liên&nbsp;hệ:</p><p>Fanpage:&nbsp;ICPDP-Global&nbsp;Study&nbsp;Opportunities</p><p>Địa&nbsp;điểm:&nbsp;Phòng&nbsp;Delta&nbsp;102,&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT</p>', 'Buổi lễ có sự tham dự của lãnh đạo Kanto Seiki và đại diện tỉnh Gunma. Chủ tịch Takeshi Tozawa đã trực tiếp trao chứng nhận hoàn thành thực tập cho Khoa, đồng thời đánh giá cao những đóng góp của bạn trong suốt hai tuần làm việc. Khoa cũng chia sẻ bạn đã có một khoảng thời gian ý nghĩa và thể hiện nguyện vọng muốn quay trở lại Nhật Bản để làm việc. Đáng chú ý, sự kiện này đã được đưa tin rộng rãi trên các kênh truyền thông lớn tại Nhật Bản như Yahoo! Nhật Bản, Nikkei, truyền hình Gunma và báo giấy địa phương. Điều đó cho thấy tầm quan trọng của chương trình, không chỉ với cá nhân Khoa mà còn với mối quan hệ hợp tác giữa tỉnh Gunma và Đại học FPT. Nguyễn Đăng Khoa là sinh viên duy nhất được chọn trong chương trình học bổng thực tập sinh tài năng tại tỉnh Gunma, Nhật Bản. Đây là kết quả của quá trình hợp tác nhiều năm giữa trường Đại học FPT, tỉnh Gunma cùng các đối tác đồng hành. Sự kiện này đánh một dấu mốc quan trọng, thể hiện nguyện vọng hợp tác thực chất giữa các đơn vị, tạo tiền đề cho những chương trình ý nghĩa hơn trong tương lai. Trong bối cảnh Nhật Bản đang tìm kiếm nhân lực CNTT chất lượng cao từ Việt Nam, trường Đại học FPT tự tin là cơ sở đào tạo đáp ứng được những yêu cầu khắt khe mà đối tác Nhật Bản đưa ra: truyền thống hợp tác lâu đời, chương trình CNTT gắn liền với thực tiễn và sinh viên được trang bị khả năng tiếng Nhật đáp ứng nhu cầu tuyển dụng từ doanh nghiệp. ----------------------------------------------------- ℹ️ Mọi thắc mắc xin vui lòng liên hệ: Fanpage: ICPDP-Global Study Opportunities Địa điểm: Phòng Delta 102, Trường Đại học FPT', '2026-08-14 22:26:57', NULL),
	(171107, 171049, 1, '', '<p>The ceremony was attended by leaders from Kanto Seiki and representatives from Gunma Prefecture. Chairman Takeshi Tozawa personally presented Khoa with the internship completion certificate, praising his contributions during the two weeks of work. Khoa also shared that he had a meaningful time and expressed his desire to return to Japan for work.</p><p> Notably, this event received extensive coverage on major Japanese media outlets such as Yahoo! Japan, Nikkei, Gunma Television, and local newspapers. This demonstrates the importance of the program, not only to the Faculty personally but also to the collaborative relationship between Gunma Prefecture and FPT University.</p><p> Nguyen Dang Khoa is the only student selected for the talent internship scholarship program in Gunma Prefecture, Japan. This is the result of many years of cooperation between FPT University, Gunma Prefecture, and its partners. This event marks an important milestone, demonstrating the desire for genuine cooperation between the units and laying the groundwork for more meaningful programs in the future.</p><p> In the context of Japan\'s search for high-quality IT personnel from Vietnam, FPT University confidently positions itself as a training institution that meets the stringent requirements set by its Japanese partners: a long-standing tradition of cooperation, IT programs closely linked to practical applications, and students equipped with Japanese language skills to meet the recruitment needs of businesses.</p><p> -----------------------------------------------------</p><p> ℹ️ For any questions, please contact:</p><p> Fanpage: ICPDP-Global Study Opportunities</p><p> Location: Delta Room 102, FPT University</p>', 'The ceremony was attended by leaders from Kanto Seiki and representatives from Gunma Prefecture. Chairman Takeshi Tozawa personally presented Khoa with the internship completion certificate, praising his contributions during the two weeks of work. Khoa also shared that he had a meaningful time and expressed his desire to return to Japan for work. Notably, this event received extensive coverage on major Japanese media outlets such as Yahoo! Japan, Nikkei, Gunma Television, and local newspapers. This demonstrates the importance of the program, not only to the Faculty personally but also to the collaborative relationship between Gunma Prefecture and FPT University. Nguyen Dang Khoa is the only student selected for the talent internship scholarship program in Gunma Prefecture, Japan. This is the result of many years of cooperation between FPT University, Gunma Prefecture, and its partners. This event marks an important milestone, demonstrating the desire for genuine cooperation between the units and laying the groundwork for more meaningful programs in the future. In the context of Japan\'s search for high-quality IT personnel from Vietnam, FPT University confidently positions itself as a training institution that meets the stringent requirements set by its Japanese partners: a long-standing tradition of cooperation, IT programs closely linked to practical applications, and students equipped with Japanese language skills to meet the recruitment needs of businesses. ----------------------------------------------------- ℹ️ For any questions, please contact: Fanpage: ICPDP-Global Study Opportunities Location: Delta Room 102, FPT University', '2026-08-14 22:26:57', NULL),
	(171108, 171050, 1, 'Gian nan hành trình tìm chữ nơi vách núi', '<p><span>Trước&nbsp;đây,&nbsp;các&nbsp;em&nbsp;nhỏ&nbsp;tại&nbsp;Bản&nbsp;Xa&nbsp;phải&nbsp;học&nbsp;tập&nbsp;trong&nbsp;một&nbsp;ngôi&nbsp;nhà&nbsp;tạm&nbsp;bợ&nbsp;dựng&nbsp;bằng&nbsp;tranh&nbsp;tre,&nbsp;vách&nbsp;nứa.&nbsp;Vào&nbsp;mùa&nbsp;đông,&nbsp;gió&nbsp;lùa&nbsp;qua&nbsp;khe&nbsp;liếp&nbsp;rét&nbsp;buốt,&nbsp;còn&nbsp;mùa&nbsp;mưa&nbsp;thì&nbsp;mái&nbsp;lá&nbsp;dột&nbsp;nát&nbsp;khiến&nbsp;bàn&nbsp;ghế,&nbsp;sách&nbsp;vở&nbsp;ướt&nbsp;sũng.&nbsp;Đường&nbsp;xá&nbsp;xa&nbsp;xôi,&nbsp;cơ&nbsp;sở&nbsp;vật&nbsp;chất&nbsp;thiếu&nbsp;thốn&nbsp;khiến&nbsp;tỷ&nbsp;lệ&nbsp;trẻ&nbsp;em&nbsp;nghỉ&nbsp;học&nbsp;vào&nbsp;những&nbsp;ngày&nbsp;thời&nbsp;tiết&nbsp;xấu&nbsp;luôn&nbsp;ở&nbsp;mức&nbsp;cao.&nbsp;Việc&nbsp;dạy&nbsp;và&nbsp;học&nbsp;của&nbsp;cô&nbsp;trò&nbsp;nơi&nbsp;đây&nbsp;gặp&nbsp;vô&nbsp;vàn&nbsp;phương&nbsp;hại.</span></p><p></p><p></p>', 'Trước đây, các em nhỏ tại Bản Xa phải học tập trong một ngôi nhà tạm bợ dựng bằng tranh tre, vách nứa. Vào mùa đông, gió lùa qua khe liếp rét buốt, còn mùa mưa thì mái lá dột nát khiến bàn ghế, sách vở ướt sũng. Đường xá xa xôi, cơ sở vật chất thiếu thốn khiến tỷ lệ trẻ em nghỉ học vào những ngày thời tiết xấu luôn ở mức cao. Việc dạy và học của cô trò nơi đây gặp vô vàn phương hại.', '2026-08-15 11:16:23', NULL),
	(171109, 171050, 2, 'Ngôi trường mới từ những tấm lòng vàng', '<p><span>Trong&nbsp;ngày&nbsp;vui&nbsp;khánh&nbsp;thành,&nbsp;tiếng&nbsp;cười&nbsp;rộn&nbsp;rã&nbsp;ngập&nbsp;tràn&nbsp;khắp&nbsp;bản&nbsp;làng.&nbsp;Các&nbsp;em&nbsp;nhỏ&nbsp;hân&nbsp;hoan&nbsp;mặc&nbsp;những&nbsp;bộ&nbsp;quần&nbsp;áo&nbsp;mới,&nbsp;tay&nbsp;cầm&nbsp;chiếc&nbsp;ba&nbsp;lô&nbsp;vừa&nbsp;được&nbsp;trao&nbsp;tặng,&nbsp;mắt&nbsp;ngời&nbsp;sáng&nbsp;khi&nbsp;lần&nbsp;đầu&nbsp;tiên&nbsp;được&nbsp;bước&nbsp;vào&nbsp;lớp&nbsp;học&nbsp;có&nbsp;tường&nbsp;sơn&nbsp;màu&nbsp;vẽ,&nbsp;sân&nbsp;chơi&nbsp;trải&nbsp;cỏ&nbsp;nhân&nbsp;tạo&nbsp;và&nbsp;đầy&nbsp;đủ&nbsp;đồ&nbsp;chơi.</span></p><p><span>Đại&nbsp;diện&nbsp;ban&nbsp;giám&nbsp;hiệu&nbsp;xúc&nbsp;động&nbsp;chia&nbsp;sẻ,&nbsp;công&nbsp;trình&nbsp;kiên&nbsp;cố&nbsp;này&nbsp;không&nbsp;chỉ&nbsp;che&nbsp;mưa&nbsp;che&nbsp;nắng,&nbsp;mà&nbsp;còn&nbsp;là&nbsp;nguồn&nbsp;động&nbsp;viên&nbsp;to&nbsp;lớn&nbsp;để&nbsp;các&nbsp;thầy&nbsp;cô&nbsp;cắm&nbsp;bản&nbsp;yên&nbsp;tâm&nbsp;gieo&nbsp;chữ,&nbsp;đồng&nbsp;thời&nbsp;tiếp&nbsp;thêm&nbsp;động&nbsp;lực&nbsp;cho&nbsp;cha&nbsp;mẹ&nbsp;học&nbsp;sinh&nbsp;yên&nbsp;tâm&nbsp;gửi&nbsp;con&nbsp;bám&nbsp;lớp,&nbsp;hướng&nbsp;tới&nbsp;một&nbsp;tương&nbsp;lai&nbsp;tươi&nbsp;sáng&nbsp;hơn.</span></p><p></p><hr><p></p>', 'Trong ngày vui khánh thành, tiếng cười rộn rã ngập tràn khắp bản làng. Các em nhỏ hân hoan mặc những bộ quần áo mới, tay cầm chiếc ba lô vừa được trao tặng, mắt ngời sáng khi lần đầu tiên được bước vào lớp học có tường sơn màu vẽ, sân chơi trải cỏ nhân tạo và đầy đủ đồ chơi. Đại diện ban giám hiệu xúc động chia sẻ, công trình kiên cố này không chỉ che mưa che nắng, mà còn là nguồn động viên to lớn để các thầy cô cắm bản yên tâm gieo chữ, đồng thời tiếp thêm động lực cho cha mẹ học sinh yên tâm gửi con bám lớp, hướng tới một tương lai tươi sáng hơn.', '2026-08-15 11:16:23', NULL),
	(171110, 171051, 1, 'The arduous journey to find literacy in the cliffside.', '<p><span>Previously, children in Ban Xa had to study in a makeshift house built of thatch and bamboo walls. In winter, the wind blew through the gaps, making it bitterly cold, while in the rainy season, the leaky roof soaked the desks, chairs, and books. The remote location and lack of facilities meant that the rate of children missing school on days with bad weather was always high. Teaching and learning for both teachers and students here faced countless difficulties.</span></p><p></p><p></p>', 'Previously, children in Ban Xa had to study in a makeshift house built of thatch and bamboo walls. In winter, the wind blew through the gaps, making it bitterly cold, while in the rainy season, the leaky roof soaked the desks, chairs, and books. The remote location and lack of facilities meant that the rate of children missing school on days with bad weather was always high. Teaching and learning for both teachers and students here faced countless difficulties.', '2026-08-15 11:16:23', NULL),
	(171111, 171051, 2, 'A new school built with generous hearts.', '<p><span>On the joyous inauguration day, laughter filled the entire village. Children happily wore their new clothes, clutching their newly gifted backpacks, their eyes shining as they stepped into their classroom for the first time – a classroom with painted walls, a playground covered in artificial grass, and plenty of toys.</span></p><p> <span>The school\'s representatives emotionally shared that this sturdy building not only provides shelter from the rain and sun but also serves as a great source of encouragement for teachers working in remote areas, giving them peace of mind to continue teaching and motivating parents to confidently send their children to school, looking forward to a brighter future.</span></p><p></p><hr><p></p>', 'On the joyous inauguration day, laughter filled the entire village. Children happily wore their new clothes, clutching their newly gifted backpacks, their eyes shining as they stepped into their classroom for the first time – a classroom with painted walls, a playground covered in artificial grass, and plenty of toys. The school\'s representatives emotionally shared that this sturdy building not only provides shelter from the rain and sun but also serves as a great source of encouragement for teachers working in remote areas, giving them peace of mind to continue teaching and motivating parents to confidently send their children to school, looking forward to a brighter future.', '2026-08-15 11:16:23', NULL),
	(171116, 171054, 1, '', '<p><strong>🏫&nbsp;Guilin&nbsp;University&nbsp;of&nbsp;Electronic&nbsp;Technology&nbsp;(GUET)&nbsp;là&nbsp;một&nbsp;trong&nbsp;những&nbsp;trường&nbsp;đại&nbsp;học&nbsp;hàng&nbsp;đầu&nbsp;của&nbsp;Trung&nbsp;Quốc&nbsp;trong&nbsp;lĩnh&nbsp;vực&nbsp;điện&nbsp;tử,&nbsp;công&nbsp;nghệ&nbsp;thông&nbsp;tin,&nbsp;viễn&nbsp;thông&nbsp;và&nbsp;kỹ&nbsp;thuật.&nbsp;Với&nbsp;thế&nbsp;mạnh&nbsp;về&nbsp;đào&nbsp;tạo,&nbsp;nghiên&nbsp;cứu&nbsp;và&nbsp;đổi&nbsp;mới&nbsp;sáng&nbsp;tạo,&nbsp;GUET&nbsp;đã&nbsp;xây&nbsp;dựng&nbsp;mạng&nbsp;lưới&nbsp;hợp&nbsp;tác&nbsp;quốc&nbsp;tế&nbsp;rộng&nbsp;khắp&nbsp;và&nbsp;đào&nbsp;tạo&nbsp;nhiều&nbsp;thế&nbsp;hệ&nbsp;nhân&nbsp;lực&nbsp;chất&nbsp;lượng&nbsp;cao&nbsp;cho&nbsp;ngành&nbsp;công&nbsp;nghệ.</strong></p><p><strong>🎓&nbsp;Trong&nbsp;chuyến&nbsp;thăm,&nbsp;đoàn&nbsp;đại&nbsp;biểu&nbsp;đã&nbsp;tham&nbsp;quan&nbsp;hệ&nbsp;thống&nbsp;cơ&nbsp;sở&nbsp;vật&nbsp;chất,&nbsp;tìm&nbsp;hiểu&nbsp;môi&nbsp;trường&nbsp;đào&nbsp;tạo&nbsp;và&nbsp;hệ&nbsp;sinh&nbsp;thái&nbsp;giáo&nbsp;dục&nbsp;của&nbsp;FPT&nbsp;Education.&nbsp;Hai&nbsp;bên&nbsp;cũng&nbsp;trao&nbsp;đổi&nbsp;về&nbsp;các&nbsp;định&nbsp;hướng&nbsp;hợp&nbsp;tác&nbsp;trong&nbsp;đào&nbsp;tạo,&nbsp;trao&nbsp;đổi&nbsp;sinh&nbsp;viên&nbsp;và&nbsp;giảng&nbsp;viên,&nbsp;nghiên&nbsp;cứu&nbsp;khoa&nbsp;học,&nbsp;cũng&nbsp;như&nbsp;phát&nbsp;triển&nbsp;nguồn&nbsp;nhân&nbsp;lực&nbsp;chất&nbsp;lượng&nbsp;cao&nbsp;trong&nbsp;các&nbsp;lĩnh&nbsp;vực&nbsp;công&nbsp;nghệ&nbsp;và&nbsp;bán&nbsp;dẫn.</strong></p><p><strong>🌏&nbsp;Buổi&nbsp;làm&nbsp;việc&nbsp;là&nbsp;cơ&nbsp;hội&nbsp;để&nbsp;FPT&nbsp;Education&nbsp;và&nbsp;GUET&nbsp;tăng&nbsp;cường&nbsp;kết&nbsp;nối,&nbsp;mở&nbsp;rộng&nbsp;quan&nbsp;hệ&nbsp;hợp&nbsp;tác&nbsp;quốc&nbsp;tế,&nbsp;đồng&nbsp;thời&nbsp;tạo&nbsp;thêm&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;học&nbsp;tập,&nbsp;nghiên&nbsp;cứu&nbsp;và&nbsp;phát&nbsp;triển&nbsp;cho&nbsp;học&nbsp;sinh,&nbsp;sinh&nbsp;viên&nbsp;và&nbsp;giảng&nbsp;viên&nbsp;của&nbsp;hai&nbsp;bên.</strong></p><p><strong>------------------------------------------------</strong></p><p></p><p><strong>ℹ️Mọi&nbsp;thắc&nbsp;mắc&nbsp;xin&nbsp;liên&nbsp;hệ:</strong></p><p><strong>-&nbsp;Địa&nbsp;điểm:&nbsp;Phòng&nbsp;L209,&nbsp;Toà&nbsp;nhà&nbsp;Alpha,&nbsp;Trường&nbsp;Đại&nbsp;học&nbsp;FPT&nbsp;Hà&nbsp;Nội&nbsp;</strong></p><p><strong>-&nbsp;SĐT:&nbsp;(+84)&nbsp;24&nbsp;6680&nbsp;5910</strong></p><p><strong>-&nbsp;Fanpage:&nbsp;Phòng&nbsp;Hợp&nbsp;tác&nbsp;quốc&nbsp;tế&nbsp;FPTU&nbsp;Hà&nbsp;Nội</strong></p><p><strong>-&nbsp;Email:&nbsp;international.fptu@fpt.edu.vn</strong></p><p><strong>-&nbsp;Group&nbsp;Review&nbsp;chương&nbsp;trình&nbsp;quốc&nbsp;tế&nbsp;Đại&nbsp;học&nbsp;FPT</strong></p><p></p>', '🏫 Guilin University of Electronic Technology (GUET) là một trong những trường đại học hàng đầu của Trung Quốc trong lĩnh vực điện tử, công nghệ thông tin, viễn thông và kỹ thuật. Với thế mạnh về đào tạo, nghiên cứu và đổi mới sáng tạo, GUET đã xây dựng mạng lưới hợp tác quốc tế rộng khắp và đào tạo nhiều thế hệ nhân lực chất lượng cao cho ngành công nghệ. 🎓 Trong chuyến thăm, đoàn đại biểu đã tham quan hệ thống cơ sở vật chất, tìm hiểu môi trường đào tạo và hệ sinh thái giáo dục của FPT Education. Hai bên cũng trao đổi về các định hướng hợp tác trong đào tạo, trao đổi sinh viên và giảng viên, nghiên cứu khoa học, cũng như phát triển nguồn nhân lực chất lượng cao trong các lĩnh vực công nghệ và bán dẫn. 🌏 Buổi làm việc là cơ hội để FPT Education và GUET tăng cường kết nối, mở rộng quan hệ hợp tác quốc tế, đồng thời tạo thêm nhiều cơ hội học tập, nghiên cứu và phát triển cho học sinh, sinh viên và giảng viên của hai bên. ------------------------------------------------ ℹ️Mọi thắc mắc xin liên hệ: - Địa điểm: Phòng L209, Toà nhà Alpha, Trường Đại học FPT Hà Nội - SĐT: (+84) 24 6680 5910 - Fanpage: Phòng Hợp tác quốc tế FPTU Hà Nội - Email: international.fptu@fpt.edu.vn - Group Review chương trình quốc tế Đại học FPT', '2026-08-15 22:31:15', NULL),
	(171117, 171055, 1, '', '<p><strong>🏫 Guilin University of Electronic Technology (GUET) is one of China\'s leading universities in the fields of electronics, information technology, telecommunications, and engineering. With its strengths in education, research, and innovation, GUET has built a wide-ranging international cooperation network and trained many generations of high-quality personnel for the technology industry.</strong></p><p> <strong>🎓 During the visit, the delegation toured the facilities, learned about the training environment and educational ecosystem of FPT Education. The two sides also discussed directions for cooperation in training, student and faculty exchange, scientific research, and the development of high-quality human resources in the fields of technology and semiconductors.</strong></p><p> <strong>🌏 This meeting provides an opportunity for FPT Education and GUET to strengthen connections, expand international cooperation, and create more learning, research, and development opportunities for students and faculty members of both sides.</strong></p><p> <strong>------------------------------------------------</strong></p><p></p><p> <strong>ℹ️For any questions, please contact:</strong></p><p> <strong>- Location: Room L209, Alpha Building, FPT University Hanoi</strong></p><p> <strong>- Phone number: (+84) 24 6680 5910</strong></p><p> <strong>- Fanpage: FPTU Hanoi International Cooperation Department</strong></p><p> <strong>- Email: international.fptu@fpt.edu.vn</strong></p><p> <strong>- Group Review of FPT University\'s International Programs</strong></p><p></p>', '🏫 Guilin University of Electronic Technology (GUET) is one of China\'s leading universities in the fields of electronics, information technology, telecommunications, and engineering. With its strengths in education, research, and innovation, GUET has built a wide-ranging international cooperation network and trained many generations of high-quality personnel for the technology industry. 🎓 During the visit, the delegation toured the facilities, learned about the training environment and educational ecosystem of FPT Education. The two sides also discussed directions for cooperation in training, student and faculty exchange, scientific research, and the development of high-quality human resources in the fields of technology and semiconductors. 🌏 This meeting provides an opportunity for FPT Education and GUET to strengthen connections, expand international cooperation, and create more learning, research, and development opportunities for students and faculty members of both sides. ------------------------------------------------ ℹ️For any questions, please contact: - Location: Room L209, Alpha Building, FPT University Hanoi - Phone number: (+84) 24 6680 5910 - Fanpage: FPTU Hanoi International Cooperation Department - Email: international.fptu@fpt.edu.vn - Group Review of FPT University\'s International Programs', '2026-08-15 22:31:15', NULL),
	(171118, 171052, 1, 'Háo hức ngày đầu check-in "ngôi nhà thứ hai"', '<p>Ngay&nbsp;từ&nbsp;sáng&nbsp;sớm,&nbsp;bầu&nbsp;không&nbsp;khí&nbsp;tại&nbsp;khuôn&nbsp;viên&nbsp;trường&nbsp;đã&nbsp;vô&nbsp;cùng&nbsp;náo&nbsp;nhiệt.&nbsp;Không&nbsp;còn&nbsp;những&nbsp;gương&nbsp;mặt&nbsp;lo&nbsp;lắng,&nbsp;rụt&nbsp;rè&nbsp;thường&nbsp;thấy&nbsp;của&nbsp;các&nbsp;em&nbsp;học&nbsp;sinh&nbsp;lớp&nbsp;1&nbsp;và&nbsp;lớp&nbsp;6,&nbsp;ngày&nbsp;hội&nbsp;tham&nbsp;quan&nbsp;(School&nbsp;Tour)&nbsp;đã&nbsp;biến&nbsp;buổi&nbsp;tựu&nbsp;trường&nbsp;thành&nbsp;một&nbsp;chuyến&nbsp;phiêu&nbsp;lưu&nbsp;đầy&nbsp;thú&nbsp;vị.</p><p>Tại&nbsp;cổng&nbsp;trường,&nbsp;các&nbsp;thầy&nbsp;cô&nbsp;giáo&nbsp;trong&nbsp;trang&nbsp;phục&nbsp;rực&nbsp;rỡ&nbsp;cùng&nbsp;linh&nbsp;vật&nbsp;vui&nbsp;nhộn&nbsp;đã&nbsp;đứng&nbsp;đón,&nbsp;phát&nbsp;cho&nbsp;mỗi&nbsp;em&nbsp;một&nbsp;"Hộ&nbsp;chiếu&nbsp;trải&nbsp;nghiệm"&nbsp;để&nbsp;tích&nbsp;điểm&nbsp;qua&nbsp;từng&nbsp;trạm&nbsp;tham&nbsp;quan.&nbsp;Nhiều&nbsp;gia&nbsp;đình&nbsp;ba&nbsp;thế&nbsp;hệ&nbsp;cùng&nbsp;nhau&nbsp;lưu&nbsp;lại&nbsp;những&nbsp;bức&nbsp;ảnh&nbsp;kỷ&nbsp;niệm&nbsp;tại&nbsp;các&nbsp;tiểu&nbsp;cảnh&nbsp;được&nbsp;trang&nbsp;trí&nbsp;bắt&nbsp;mắt&nbsp;ở&nbsp;sân&nbsp;trường.</p>', 'Ngay từ sáng sớm, bầu không khí tại khuôn viên trường đã vô cùng náo nhiệt. Không còn những gương mặt lo lắng, rụt rè thường thấy của các em học sinh lớp 1 và lớp 6, ngày hội tham quan (School Tour) đã biến buổi tựu trường thành một chuyến phiêu lưu đầy thú vị. Tại cổng trường, các thầy cô giáo trong trang phục rực rỡ cùng linh vật vui nhộn đã đứng đón, phát cho mỗi em một "Hộ chiếu trải nghiệm" để tích điểm qua từng trạm tham quan. Nhiều gia đình ba thế hệ cùng nhau lưu lại những bức ảnh kỷ niệm tại các tiểu cảnh được trang trí bắt mắt ở sân trường.', '2026-08-16 01:36:33', NULL),
	(171119, 171052, 2, 'Trải nghiệm làm "học sinh thử nghiệm" trong lớp học thông minh', '<p>Điểm&nbsp;nhấn&nbsp;của&nbsp;buổi&nbsp;tham&nbsp;quan&nbsp;là&nbsp;hoạt&nbsp;động&nbsp;"Lớp&nbsp;học&nbsp;giả&nbsp;định".&nbsp;Phụ&nbsp;huynh&nbsp;và&nbsp;học&nbsp;sinh&nbsp;được&nbsp;trực&nbsp;tiếp&nbsp;trải&nbsp;nghiệm&nbsp;một&nbsp;tiết&nbsp;học&nbsp;ngắn&nbsp;có&nbsp;sự&nbsp;hỗ&nbsp;trợ&nbsp;của&nbsp;bảng&nbsp;tương&nbsp;tác&nbsp;thông&nbsp;minh&nbsp;và&nbsp;máy&nbsp;tính&nbsp;bảng&nbsp;cá&nbsp;nhân.</p><p>Nhiều&nbsp;bậc&nbsp;phụ&nbsp;huynh&nbsp;tỏ&nbsp;ra&nbsp;bất&nbsp;ngờ&nbsp;trước&nbsp;phương&nbsp;pháp&nbsp;giảng&nbsp;dạy&nbsp;đổi&nbsp;mới,&nbsp;nơi&nbsp;học&nbsp;sinh&nbsp;là&nbsp;trung&nbsp;tâm&nbsp;và&nbsp;kiến&nbsp;thức&nbsp;được&nbsp;truyền&nbsp;tải&nbsp;qua&nbsp;các&nbsp;trò&nbsp;chơi&nbsp;tương&nbsp;tác,&nbsp;thay&nbsp;vì&nbsp;cách&nbsp;đọc&nbsp;chép&nbsp;truyền&nbsp;thống.&nbsp;Cô&nbsp;Nguyễn&nbsp;Minh&nbsp;An,&nbsp;một&nbsp;phụ&nbsp;huynh&nbsp;tham&nbsp;gia&nbsp;buổi&nbsp;lễ&nbsp;chia&nbsp;sẻ:&nbsp;<em>"Tôi&nbsp;không&nbsp;nghĩ&nbsp;trường&nbsp;công&nbsp;lập&nbsp;ở&nbsp;khu&nbsp;vực&nbsp;chúng&nbsp;ta&nbsp;lại&nbsp;được&nbsp;đầu&nbsp;tư&nbsp;đồng&nbsp;bộ&nbsp;và&nbsp;hiện&nbsp;đại&nbsp;đến&nbsp;thế&nbsp;này.&nbsp;Nhìn&nbsp;con&nbsp;hào&nbsp;hứng&nbsp;tham&nbsp;gia&nbsp;hoạt&nbsp;động,&nbsp;tôi&nbsp;hoàn&nbsp;toàn&nbsp;yên&nbsp;tâm&nbsp;khi&nbsp;gửi&nbsp;gắm&nbsp;con&nbsp;tại&nbsp;đây."</em></p>', 'Điểm nhấn của buổi tham quan là hoạt động "Lớp học giả định". Phụ huynh và học sinh được trực tiếp trải nghiệm một tiết học ngắn có sự hỗ trợ của bảng tương tác thông minh và máy tính bảng cá nhân. Nhiều bậc phụ huynh tỏ ra bất ngờ trước phương pháp giảng dạy đổi mới, nơi học sinh là trung tâm và kiến thức được truyền tải qua các trò chơi tương tác, thay vì cách đọc chép truyền thống. Cô Nguyễn Minh An, một phụ huynh tham gia buổi lễ chia sẻ: "Tôi không nghĩ trường công lập ở khu vực chúng ta lại được đầu tư đồng bộ và hiện đại đến thế này. Nhìn con hào hứng tham gia hoạt động, tôi hoàn toàn yên tâm khi gửi gắm con tại đây."', '2026-08-16 01:36:33', NULL),
	(171120, 171053, 1, 'Excited to check in to my "second home" on my first day!', '<p><span>From early morning, the atmosphere on campus was incredibly lively. Gone were the anxious, shy faces usually seen of first and sixth graders; the School Tour had transformed the first day of school into an exciting adventure.</span></p><p> <span>At the school gate, teachers in vibrant costumes and cheerful mascots greeted the students, handing out "Experience Passports" to accumulate points at each tour station. Many three-generation families took commemorative photos together at the attractively decorated scenic spots in the schoolyard.</span></p>', 'From early morning, the atmosphere on campus was incredibly lively. Gone were the anxious, shy faces usually seen of first and sixth graders; the School Tour had transformed the first day of school into an exciting adventure. At the school gate, teachers in vibrant costumes and cheerful mascots greeted the students, handing out "Experience Passports" to accumulate points at each tour station. Many three-generation families took commemorative photos together at the attractively decorated scenic spots in the schoolyard.', '2026-08-16 01:36:34', NULL),
	(171121, 171053, 2, 'Experience being a "test student" in a smart classroom.', '<p><span>The highlight of the visit was the "Simulated Classroom" activity. Parents and students got to experience a short lesson firsthand, supported by interactive whiteboards and personal tablets.</span></p><p> <span>Many parents were surprised by the innovative teaching methods, where students are at the center and knowledge is conveyed through interactive games, instead of traditional rote learning. Ms. Nguyen Minh An, a parent attending the ceremony, shared:</span> <em>"I didn\'t think public schools in our area would be so comprehensively and modernly invested in. Seeing my child enthusiastically participating in the activities, I feel completely reassured entrusting my child to this school."</em></p>', 'The highlight of the visit was the "Simulated Classroom" activity. Parents and students got to experience a short lesson firsthand, supported by interactive whiteboards and personal tablets. Many parents were surprised by the innovative teaching methods, where students are at the center and knowledge is conveyed through interactive games, instead of traditional rote learning. Ms. Nguyen Minh An, a parent attending the ceremony, shared: "I didn\'t think public schools in our area would be so comprehensively and modernly invested in. Seeing my child enthusiastically participating in the activities, I feel completely reassured entrusting my child to this school."', '2026-08-16 01:36:34', NULL),
	(171122, 171056, 1, 'Mục 01', '<p>Nội&nbsp;dung&nbsp;của&nbsp;mục&nbsp;01</p>', 'Nội dung của mục 01', '2026-08-20 19:53:41', NULL),
	(171123, 171057, 1, 'Section 01', '<p>Content of item 01</p>', 'Content of item 01', '2026-08-20 19:53:41', NULL),
	(171124, 171058, 1, '', '<p>💡&nbsp;Trong&nbsp;buổi&nbsp;thảo&nbsp;luận,&nbsp;hai&nbsp;bên&nbsp;đã&nbsp;chia&nbsp;sẻ&nbsp;về&nbsp;khả&nbsp;năng&nbsp;triển&nbsp;khai&nbsp;các&nbsp;chương&nbsp;trình&nbsp;hỗ&nbsp;trợ&nbsp;học&nbsp;thuật,&nbsp;tài&nbsp;nguyên&nbsp;đào&nbsp;tạo,&nbsp;workshop&nbsp;chuyên&nbsp;môn&nbsp;cũng&nbsp;như&nbsp;cơ&nbsp;hội&nbsp;để&nbsp;sinh&nbsp;viên&nbsp;tiếp&nbsp;cận&nbsp;các&nbsp;nền&nbsp;tảng&nbsp;DBMS&nbsp;và&nbsp;công&nbsp;nghệ&nbsp;thực&nbsp;tiễn&nbsp;từ&nbsp;doanh&nbsp;nghiệp.&nbsp;</p><p>Đồng&nbsp;thời,&nbsp;TmaxTibero&nbsp;cũng&nbsp;giới&nbsp;thiệu&nbsp;thêm&nbsp;về&nbsp;các&nbsp;giải&nbsp;pháp&nbsp;cơ&nbsp;sở&nbsp;dữ&nbsp;liệu&nbsp;và&nbsp;hệ&nbsp;sinh&nbsp;thái&nbsp;công&nbsp;nghệ&nbsp;mà&nbsp;doanh&nbsp;nghiệp&nbsp;đang&nbsp;phát&nbsp;triển,&nbsp;mở&nbsp;ra&nbsp;nhiều&nbsp;tiềm&nbsp;năng&nbsp;hợp&nbsp;tác&nbsp;trong&nbsp;đào&nbsp;tạo,&nbsp;nghiên&nbsp;cứu&nbsp;và&nbsp;định&nbsp;hướng&nbsp;nghề&nbsp;nghiệp&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;ngành&nbsp;Công&nbsp;nghệ&nbsp;thông&nbsp;tin.</p><p>🚀&nbsp;Hoạt&nbsp;động&nbsp;hợp&nbsp;tác&nbsp;hứa&nbsp;hẹn&nbsp;sẽ&nbsp;mở&nbsp;ra&nbsp;thêm&nbsp;nhiều&nbsp;cơ&nbsp;hội&nbsp;để&nbsp;sinh&nbsp;viên&nbsp;nâng&nbsp;cao&nbsp;kỹ&nbsp;năng&nbsp;công&nbsp;nghệ,&nbsp;tiếp&nbsp;cận&nbsp;môi&nbsp;trường&nbsp;doanh&nbsp;nghiệp&nbsp;quốc&nbsp;tế&nbsp;và&nbsp;phát&nbsp;triển&nbsp;năng&nbsp;lực&nbsp;nghề&nbsp;nghiệp&nbsp;trong&nbsp;lĩnh&nbsp;vực&nbsp;IT&nbsp;và&nbsp;chuyển&nbsp;đổi&nbsp;số</p>', '💡 Trong buổi thảo luận, hai bên đã chia sẻ về khả năng triển khai các chương trình hỗ trợ học thuật, tài nguyên đào tạo, workshop chuyên môn cũng như cơ hội để sinh viên tiếp cận các nền tảng DBMS và công nghệ thực tiễn từ doanh nghiệp. Đồng thời, TmaxTibero cũng giới thiệu thêm về các giải pháp cơ sở dữ liệu và hệ sinh thái công nghệ mà doanh nghiệp đang phát triển, mở ra nhiều tiềm năng hợp tác trong đào tạo, nghiên cứu và định hướng nghề nghiệp cho sinh viên ngành Công nghệ thông tin. 🚀 Hoạt động hợp tác hứa hẹn sẽ mở ra thêm nhiều cơ hội để sinh viên nâng cao kỹ năng công nghệ, tiếp cận môi trường doanh nghiệp quốc tế và phát triển năng lực nghề nghiệp trong lĩnh vực IT và chuyển đổi số', '2026-08-21 20:54:20', NULL),
	(171125, 171059, 1, '', '<p>💡 During the discussion, both sides shared insights on the potential for implementing academic support programs, training resources, professional workshops, and opportunities for students to access DBMS platforms and practical technologies from businesses.</p><p> At the same time, TmaxTibero also introduced the database solutions and technology ecosystem that the company is developing, opening up many potential collaborations in training, research, and career orientation for Information Technology students.</p><p> 🚀 This collaborative effort promises to open up more opportunities for students to enhance their technological skills, access the international business environment, and develop their professional capabilities in the fields of IT and digital transformation.</p>', '💡 During the discussion, both sides shared insights on the potential for implementing academic support programs, training resources, professional workshops, and opportunities for students to access DBMS platforms and practical technologies from businesses. At the same time, TmaxTibero also introduced the database solutions and technology ecosystem that the company is developing, opening up many potential collaborations in training, research, and career orientation for Information Technology students. 🚀 This collaborative effort promises to open up more opportunities for students to enhance their technological skills, access the international business environment, and develop their professional capabilities in the fields of IT and digital transformation.', '2026-08-21 20:54:20', NULL),
	(171126, 171060, 1, '', '<p>🤝&nbsp;Đón&nbsp;tiếp&nbsp;đoàn&nbsp;có:</p><p>🔹&nbsp;Ms.&nbsp;Lê&nbsp;Nguyễn&nbsp;Minh&nbsp;Phương&nbsp;–&nbsp;Head&nbsp;of&nbsp;Korean&nbsp;Studies&nbsp;Department</p><p>🔹&nbsp;Mr.&nbsp;Nguyễn&nbsp;Khánh&nbsp;Toàn&nbsp;–&nbsp;International&nbsp;Cooperation&nbsp;Manager&nbsp;of&nbsp;FPT&nbsp;University&nbsp;Hanoi</p><p>Woosong&nbsp;University&nbsp;là&nbsp;một&nbsp;trong&nbsp;những&nbsp;trường&nbsp;đại&nbsp;học&nbsp;quốc&nbsp;tế&nbsp;nổi&nbsp;bật&nbsp;tại&nbsp;Hàn&nbsp;Quốc&nbsp;với&nbsp;thế&nbsp;mạnh&nbsp;trong&nbsp;lĩnh&nbsp;vực&nbsp;công&nbsp;nghệ,&nbsp;AI&nbsp;và&nbsp;đào&nbsp;tạo&nbsp;toàn&nbsp;cầu.&nbsp;Xuyên&nbsp;suốt&nbsp;workshop,&nbsp;sinh&nbsp;viên&nbsp;kỹ&nbsp;sư&nbsp;cầu&nbsp;nối&nbsp;Hàn&nbsp;Quốc&nbsp;và&nbsp;sinh&nbsp;viên&nbsp;ngôn&nbsp;ngữ&nbsp;Hàn&nbsp;đã&nbsp;có&nbsp;cơ&nbsp;hội&nbsp;tiếp&nbsp;cận&nbsp;góc&nbsp;nhìn&nbsp;toàn&nbsp;cảnh&nbsp;về&nbsp;sự&nbsp;phát&nbsp;triển&nbsp;của&nbsp;AI&nbsp;trong&nbsp;khu&nbsp;vực,&nbsp;những&nbsp;xu&nbsp;hướng&nbsp;công&nbsp;nghệ&nbsp;nổi&nbsp;bật.</p><p>💡&nbsp;Trong&nbsp;khuôn&nbsp;khổ&nbsp;workshop,&nbsp;sinh&nbsp;viên&nbsp;đã&nbsp;có&nbsp;cơ&nbsp;hội:</p><p>🔸&nbsp;Khám&nbsp;phá&nbsp;xu&nbsp;hướng&nbsp;phát&nbsp;triển&nbsp;AI&nbsp;tại&nbsp;châu&nbsp;Á&nbsp;và&nbsp;trên&nbsp;toàn&nbsp;cầu</p><p>🔸&nbsp;Tìm&nbsp;hiểu&nbsp;những&nbsp;lĩnh&nbsp;vực&nbsp;đang&nbsp;được&nbsp;AI&nbsp;thay&nbsp;đổi&nbsp;mạnh&nbsp;mẽ</p><p>🔸&nbsp;Cập&nbsp;nhật&nbsp;các&nbsp;kỹ&nbsp;năng&nbsp;và&nbsp;năng&nbsp;lực&nbsp;được&nbsp;doanh&nbsp;nghiệp&nbsp;tìm&nbsp;kiếm</p><p>🔸&nbsp;Định&nbsp;hình&nbsp;cơ&nbsp;hội&nbsp;nghề&nbsp;nghiệp&nbsp;trong&nbsp;kỷ&nbsp;nguyên&nbsp;trí&nbsp;tuệ&nbsp;nhân&nbsp;tạo</p><p>🚀&nbsp;Không&nbsp;chỉ&nbsp;là&nbsp;một&nbsp;buổi&nbsp;chia&nbsp;sẻ&nbsp;kiến&nbsp;thức,&nbsp;chương&nbsp;trình&nbsp;còn&nbsp;là&nbsp;cơ&nbsp;hội&nbsp;để&nbsp;sinh&nbsp;viên&nbsp;giao&nbsp;lưu&nbsp;với&nbsp;chuyên&nbsp;gia&nbsp;quốc&nbsp;tế,&nbsp;tiếp&nbsp;cận&nbsp;những&nbsp;góc&nbsp;nhìn&nbsp;thực&nbsp;tiễn&nbsp;từ&nbsp;ngành&nbsp;công&nbsp;nghiệp&nbsp;và&nbsp;chuẩn&nbsp;bị&nbsp;hành&nbsp;trang&nbsp;cho&nbsp;tương&nbsp;lai&nbsp;nghề&nbsp;nghiệp.</p><p>🌐&nbsp;Những&nbsp;hoạt&nbsp;động&nbsp;kết&nbsp;nối&nbsp;học&nbsp;thuật&nbsp;quốc&nbsp;tế&nbsp;như&nbsp;thế&nbsp;này&nbsp;tiếp&nbsp;tục&nbsp;khẳng&nbsp;định&nbsp;cam&nbsp;kết&nbsp;của&nbsp;FPT&nbsp;Education&nbsp;trong&nbsp;việc&nbsp;mang&nbsp;đến&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;cơ&nbsp;hội&nbsp;tiếp&nbsp;cận&nbsp;tri&nbsp;thức&nbsp;toàn&nbsp;cầu&nbsp;ngay&nbsp;từ&nbsp;khi&nbsp;còn&nbsp;trên&nbsp;giảng&nbsp;đường.</p>', '🤝 Đón tiếp đoàn có: 🔹 Ms. Lê Nguyễn Minh Phương – Head of Korean Studies Department 🔹 Mr. Nguyễn Khánh Toàn – International Cooperation Manager of FPT University Hanoi Woosong University là một trong những trường đại học quốc tế nổi bật tại Hàn Quốc với thế mạnh trong lĩnh vực công nghệ, AI và đào tạo toàn cầu. Xuyên suốt workshop, sinh viên kỹ sư cầu nối Hàn Quốc và sinh viên ngôn ngữ Hàn đã có cơ hội tiếp cận góc nhìn toàn cảnh về sự phát triển của AI trong khu vực, những xu hướng công nghệ nổi bật. 💡 Trong khuôn khổ workshop, sinh viên đã có cơ hội: 🔸 Khám phá xu hướng phát triển AI tại châu Á và trên toàn cầu 🔸 Tìm hiểu những lĩnh vực đang được AI thay đổi mạnh mẽ 🔸 Cập nhật các kỹ năng và năng lực được doanh nghiệp tìm kiếm 🔸 Định hình cơ hội nghề nghiệp trong kỷ nguyên trí tuệ nhân tạo 🚀 Không chỉ là một buổi chia sẻ kiến thức, chương trình còn là cơ hội để sinh viên giao lưu với chuyên gia quốc tế, tiếp cận những góc nhìn thực tiễn từ ngành công nghiệp và chuẩn bị hành trang cho tương lai nghề nghiệp. 🌐 Những hoạt động kết nối học thuật quốc tế như thế này tiếp tục khẳng định cam kết của FPT Education trong việc mang đến cho sinh viên cơ hội tiếp cận tri thức toàn cầu ngay từ khi còn trên giảng đường.', '2026-08-24 21:40:15', NULL),
	(171127, 171061, 1, '', '<p>🤝 Welcoming the delegation were:</p><p> 🔹 Ms. Lê Nguyễn Minh Phương – Head of Korean Studies Department</p><p> 🔹 Mr. Nguyen Khanh Toan – International Cooperation Manager of FPT University Hanoi</p><p> Woosong University is one of the leading international universities in South Korea, with strengths in technology, AI, and global education. Throughout the workshop, Korean bridge engineering students and Korean language students had the opportunity to gain a comprehensive overview of AI development in the region and prominent technological trends.</p><p> 💡 During the workshop, students had the opportunity to:</p><p> 🔸 Discover AI development trends in Asia and globally</p><p> 🔸 Learn about the areas where AI is dramatically changing things.</p><p> 🔸 Update the skills and competencies that businesses are looking for.</p><p> 🔸 Shaping career opportunities in the age of artificial intelligence</p><p> 🚀 More than just a knowledge-sharing session, the program is also an opportunity for students to network with international experts, gain practical insights from the industry, and prepare for their future careers.</p><p> 🌐 International academic networking activities like these further affirm FPT Education\'s commitment to providing students with opportunities to access global knowledge right from their time in university.</p>', '🤝 Welcoming the delegation were: 🔹 Ms. Lê Nguyễn Minh Phương – Head of Korean Studies Department 🔹 Mr. Nguyen Khanh Toan – International Cooperation Manager of FPT University Hanoi Woosong University is one of the leading international universities in South Korea, with strengths in technology, AI, and global education. Throughout the workshop, Korean bridge engineering students and Korean language students had the opportunity to gain a comprehensive overview of AI development in the region and prominent technological trends. 💡 During the workshop, students had the opportunity to: 🔸 Discover AI development trends in Asia and globally 🔸 Learn about the areas where AI is dramatically changing things. 🔸 Update the skills and competencies that businesses are looking for. 🔸 Shaping career opportunities in the age of artificial intelligence 🚀 More than just a knowledge-sharing session, the program is also an opportunity for students to network with international experts, gain practical insights from the industry, and prepare for their future careers. 🌐 International academic networking activities like these further affirm FPT Education\'s commitment to providing students with opportunities to access global knowledge right from their time in university.', '2026-08-24 21:40:15', NULL),
	(171128, 171062, 1, 'thăm quan trường đại học fpt', '<p>thăm&nbsp;quan&nbsp;trường&nbsp;đại&nbsp;học&nbsp;fpt</p>', 'thăm quan trường đại học fpt', '2026-08-25 01:13:04', NULL),
	(171129, 171063, 1, 'Visiting FPT University', '<p>Visiting FPT University</p>', 'Visiting FPT University', '2026-08-25 01:13:04', NULL),
	(171130, 171064, 1, '', '<p>💡&nbsp;Tại&nbsp;buổi&nbsp;làm&nbsp;việc,&nbsp;các&nbsp;bên&nbsp;đã&nbsp;thảo&nbsp;luận&nbsp;về&nbsp;việc&nbsp;triển&nbsp;khai&nbsp;phần&nbsp;mềm&nbsp;ứng&nbsp;dụng&nbsp;đánh&nbsp;giá&nbsp;năng&nbsp;lực&nbsp;dành&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;ngành&nbsp;Ngôn&nbsp;ngữ&nbsp;Hàn,&nbsp;góp&nbsp;phần&nbsp;hỗ&nbsp;trợ&nbsp;quá&nbsp;trình&nbsp;học&nbsp;tập,&nbsp;rèn&nbsp;luyện&nbsp;và&nbsp;nâng&nbsp;cao&nbsp;chất&nbsp;lượng&nbsp;đào&nbsp;tạo.</p><p>🚀&nbsp;Bên&nbsp;cạnh&nbsp;đó,&nbsp;chương&nbsp;trình&nbsp;OJT&nbsp;dành&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;ngành&nbsp;IC&nbsp;Design&nbsp;cũng&nbsp;là&nbsp;một&nbsp;trong&nbsp;những&nbsp;nội&nbsp;dung&nbsp;trọng&nbsp;tâm&nbsp;được&nbsp;trao&nbsp;đổi,&nbsp;hướng&nbsp;tới&nbsp;việc&nbsp;tạo&nbsp;điều&nbsp;kiện&nbsp;để&nbsp;sinh&nbsp;viên&nbsp;tiếp&nbsp;cận&nbsp;môi&nbsp;trường&nbsp;làm&nbsp;việc&nbsp;thực&nbsp;tế,&nbsp;tích&nbsp;lũy&nbsp;kinh&nbsp;nghiệm&nbsp;chuyên&nbsp;môn&nbsp;và&nbsp;nâng&nbsp;cao&nbsp;năng&nbsp;lực&nbsp;nghề&nbsp;nghiệp&nbsp;ngay&nbsp;từ&nbsp;khi&nbsp;còn&nbsp;trên&nbsp;giảng&nbsp;đường.</p><p>🌏&nbsp;Buổi&nbsp;làm&nbsp;việc&nbsp;là&nbsp;cơ&nbsp;hội&nbsp;để&nbsp;các&nbsp;bên&nbsp;tăng&nbsp;cường&nbsp;kết&nbsp;nối,&nbsp;đồng&nbsp;thời&nbsp;mở&nbsp;ra&nbsp;những&nbsp;định&nbsp;hướng&nbsp;hợp&nbsp;tác&nbsp;mới,&nbsp;góp&nbsp;phần&nbsp;mang&nbsp;đến&nbsp;nhiều&nbsp;giá&nbsp;trị&nbsp;thiết&nbsp;thực&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;trong&nbsp;bối&nbsp;cảnh&nbsp;hội&nbsp;nhập&nbsp;và&nbsp;phát&nbsp;triển&nbsp;công&nbsp;nghệ&nbsp;toàn&nbsp;cầu.</p>', '💡 Tại buổi làm việc, các bên đã thảo luận về việc triển khai phần mềm ứng dụng đánh giá năng lực dành cho sinh viên ngành Ngôn ngữ Hàn, góp phần hỗ trợ quá trình học tập, rèn luyện và nâng cao chất lượng đào tạo. 🚀 Bên cạnh đó, chương trình OJT dành cho sinh viên ngành IC Design cũng là một trong những nội dung trọng tâm được trao đổi, hướng tới việc tạo điều kiện để sinh viên tiếp cận môi trường làm việc thực tế, tích lũy kinh nghiệm chuyên môn và nâng cao năng lực nghề nghiệp ngay từ khi còn trên giảng đường. 🌏 Buổi làm việc là cơ hội để các bên tăng cường kết nối, đồng thời mở ra những định hướng hợp tác mới, góp phần mang đến nhiều giá trị thiết thực cho sinh viên trong bối cảnh hội nhập và phát triển công nghệ toàn cầu.', '2026-08-25 21:59:16', NULL),
	(171131, 171065, 1, '', '<p>💡 During the meeting, the parties discussed the implementation of a competency assessment software application for Korean Language students, contributing to supporting their learning, training, and improving the quality of education.</p><p> 🚀 In addition, the On-the-Job Training (OJT) program for IC Design students was also a key topic of discussion, aiming to provide students with access to a real-world work environment, accumulate professional experience, and enhance their career capabilities while still in university.</p><p> 🌏 This meeting provides an opportunity for all parties to strengthen connections and explore new avenues for collaboration, contributing to tangible benefits for students in the context of global technological integration and development.</p>', '💡 During the meeting, the parties discussed the implementation of a competency assessment software application for Korean Language students, contributing to supporting their learning, training, and improving the quality of education. 🚀 In addition, the On-the-Job Training (OJT) program for IC Design students was also a key topic of discussion, aiming to provide students with access to a real-world work environment, accumulate professional experience, and enhance their career capabilities while still in university. 🌏 This meeting provides an opportunity for all parties to strengthen connections and explore new avenues for collaboration, contributing to tangible benefits for students in the context of global technological integration and development.', '2026-08-25 21:59:16', NULL),
	(171132, 171066, 1, '', '<p>Đoàn&nbsp;đại&nbsp;biểu&nbsp;UNIMAS&nbsp;gồm:</p><p>🔹&nbsp;Professor&nbsp;Dr.&nbsp;Ahmad&nbsp;Hata&nbsp;Rasit&nbsp;–&nbsp;Vice&nbsp;Chancellor&nbsp;(President),&nbsp;Universiti&nbsp;Malaysia&nbsp;Sarawak</p><p>🔹&nbsp;Professor&nbsp;Dr.&nbsp;Puah&nbsp;Chin&nbsp;Hong&nbsp;–&nbsp;CEO,&nbsp;UNIMAS&nbsp;Business&nbsp;School</p><p>🔹&nbsp;Mr.&nbsp;Thian&nbsp;Foong&nbsp;Fatt&nbsp;–&nbsp;Director,&nbsp;UNIMAS&nbsp;Global</p><p>Trong&nbsp;khuôn&nbsp;khổ&nbsp;buổi&nbsp;làm&nbsp;việc,&nbsp;hai&nbsp;bên&nbsp;đã&nbsp;thảo&nbsp;luận&nbsp;về&nbsp;cơ&nbsp;hội&nbsp;triển&nbsp;khai&nbsp;chương&nbsp;trình&nbsp;Intensive&nbsp;English,&nbsp;giúp&nbsp;sinh&nbsp;viên&nbsp;nâng&nbsp;cao&nbsp;năng&nbsp;lực&nbsp;tiếng&nbsp;Anh&nbsp;trong&nbsp;môi&nbsp;trường&nbsp;học&nbsp;tập&nbsp;quốc&nbsp;tế&nbsp;được&nbsp;thiết&nbsp;kế&nbsp;riêng&nbsp;cho&nbsp;từng&nbsp;cơ&nbsp;sở,&nbsp;đồng&nbsp;thời&nbsp;trao&nbsp;đổi&nbsp;về&nbsp;các&nbsp;chương&nbsp;trình&nbsp;Internship&nbsp;nhằm&nbsp;tạo&nbsp;điều&nbsp;kiện&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;tiếp&nbsp;cận&nbsp;môi&nbsp;trường&nbsp;làm&nbsp;việc&nbsp;thực&nbsp;tế&nbsp;và&nbsp;tích&nbsp;lũy&nbsp;kinh&nbsp;nghiệm&nbsp;toàn&nbsp;cầu.</p><p>✨&nbsp;Đặc&nbsp;biệt,&nbsp;FPT&nbsp;Education&nbsp;và&nbsp;UNIMAS&nbsp;đã&nbsp;tiến&nbsp;hành&nbsp;ký&nbsp;kết&nbsp;Letter&nbsp;of&nbsp;Intent&nbsp;(LOI)&nbsp;về&nbsp;chương&nbsp;trình&nbsp;Internship,&nbsp;đánh&nbsp;dấu&nbsp;bước&nbsp;khởi&nbsp;đầu&nbsp;cho&nbsp;những&nbsp;cơ&nbsp;hội&nbsp;thực&nbsp;tập&nbsp;quốc&nbsp;tế&nbsp;dành&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;trong&nbsp;tương&nbsp;lai.</p><p>🌍&nbsp;Với&nbsp;sự&nbsp;hợp&nbsp;tác&nbsp;này,&nbsp;sinh&nbsp;viên&nbsp;FPT&nbsp;sẽ&nbsp;có&nbsp;thêm&nbsp;nhiều&nbsp;lựa&nbsp;chọn&nbsp;để&nbsp;phát&nbsp;triển&nbsp;ngoại&nbsp;ngữ,&nbsp;mở&nbsp;rộng&nbsp;trải&nbsp;nghiệm&nbsp;quốc&nbsp;tế&nbsp;và&nbsp;chuẩn&nbsp;bị&nbsp;hành&nbsp;trang&nbsp;nghề&nbsp;nghiệp&nbsp;trong&nbsp;môi&nbsp;trường&nbsp;hội&nbsp;nhập.</p><p>🤝&nbsp;Buổi&nbsp;gặp&nbsp;gỡ&nbsp;không&nbsp;chỉ&nbsp;góp&nbsp;phần&nbsp;thắt&nbsp;chặt&nbsp;mối&nbsp;quan&nbsp;hệ&nbsp;giữa&nbsp;FPT&nbsp;Education&nbsp;và&nbsp;UNIMAS&nbsp;mà&nbsp;còn&nbsp;mở&nbsp;ra&nbsp;những&nbsp;cơ&nbsp;hội&nbsp;học&nbsp;tập&nbsp;và&nbsp;phát&nbsp;triển&nbsp;mới&nbsp;cho&nbsp;sinh&nbsp;viên&nbsp;trên&nbsp;hành&nbsp;trình&nbsp;vươn&nbsp;ra&nbsp;thế&nbsp;giới.</p>', 'Đoàn đại biểu UNIMAS gồm: 🔹 Professor Dr. Ahmad Hata Rasit – Vice Chancellor (President), Universiti Malaysia Sarawak 🔹 Professor Dr. Puah Chin Hong – CEO, UNIMAS Business School 🔹 Mr. Thian Foong Fatt – Director, UNIMAS Global Trong khuôn khổ buổi làm việc, hai bên đã thảo luận về cơ hội triển khai chương trình Intensive English, giúp sinh viên nâng cao năng lực tiếng Anh trong môi trường học tập quốc tế được thiết kế riêng cho từng cơ sở, đồng thời trao đổi về các chương trình Internship nhằm tạo điều kiện cho sinh viên tiếp cận môi trường làm việc thực tế và tích lũy kinh nghiệm toàn cầu. ✨ Đặc biệt, FPT Education và UNIMAS đã tiến hành ký kết Letter of Intent (LOI) về chương trình Internship, đánh dấu bước khởi đầu cho những cơ hội thực tập quốc tế dành cho sinh viên trong tương lai. 🌍 Với sự hợp tác này, sinh viên FPT sẽ có thêm nhiều lựa chọn để phát triển ngoại ngữ, mở rộng trải nghiệm quốc tế và chuẩn bị hành trang nghề nghiệp trong môi trường hội nhập. 🤝 Buổi gặp gỡ không chỉ góp phần thắt chặt mối quan hệ giữa FPT Education và UNIMAS mà còn mở ra những cơ hội học tập và phát triển mới cho sinh viên trên hành trình vươn ra thế giới.', '2026-08-26 14:55:45', NULL),
	(171133, 171067, 1, '', '<p>The UNIMAS delegation included:</p><p> 🔹 ProfessorDr. Ahmad Hata Rasit – Vice Chancellor (President), Universiti Malaysia Sarawak</p><p> 🔹 ProfessorDr. Puah Chin Hong – CEO, UNIMAS Business School</p><p> 🔹 Mr. Thian Foong Fatt – Director, UNIMAS Global</p><p> During the meeting, both sides discussed opportunities to implement an Intensive English program, helping students improve their English skills in an international learning environment tailored to each institution. They also exchanged views on internship programs aimed at providing students with access to real-world work environments and global experience.</p><p> ✨ Notably, FPT Education and UNIMAS have signed a Letter of Intent (LOI) for the Internship program, marking the beginning of international internship opportunities for students in the future.</p><p> 🌍 Through this collaboration, FPT students will have more options to develop their foreign language skills, expand their international experiences, and prepare for careers in an integrated environment.</p><p> 🤝 This meeting not only strengthened the relationship between FPT Education and UNIMAS but also opened up new learning and development opportunities for students on their journey to reach out to the world.</p>', 'The UNIMAS delegation included: 🔹 ProfessorDr. Ahmad Hata Rasit – Vice Chancellor (President), Universiti Malaysia Sarawak 🔹 ProfessorDr. Puah Chin Hong – CEO, UNIMAS Business School 🔹 Mr. Thian Foong Fatt – Director, UNIMAS Global During the meeting, both sides discussed opportunities to implement an Intensive English program, helping students improve their English skills in an international learning environment tailored to each institution. They also exchanged views on internship programs aimed at providing students with access to real-world work environments and global experience. ✨ Notably, FPT Education and UNIMAS have signed a Letter of Intent (LOI) for the Internship program, marking the beginning of international internship opportunities for students in the future. 🌍 Through this collaboration, FPT students will have more options to develop their foreign language skills, expand their international experiences, and prepare for careers in an integrated environment. 🤝 This meeting not only strengthened the relationship between FPT Education and UNIMAS but also opened up new learning and development opportunities for students on their journey to reach out to the world.', '2026-08-26 14:55:45', NULL);
