INSERT INTO `news_translations` (`news_translation_id`, `news_id`, `language_code`, `title`, `slug`, `summary`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES
	(171017, 17009, 'vi', 'PEMS cải tiến quy trình xuất bản tin tức sau mỗi chuyến tiếp khách', 'pems-cai-tien-quy-trinh-xuat-ban-tin-tuc-sau-moi-chuyen-tiep-khach', 'Hệ thống PEMS bổ sung quy trình quản lý tin tức với upload ảnh qua Drive, bản dịch đa ngôn ngữ và kiểm soát trạng thái public rõ ràng.', 'PEMS cải tiến quy trình xuất bản tin tức sau mỗi chuyến tiếp khách', 'Hệ thống PEMS bổ sung quy trình quản lý tin tức với upload ảnh qua Drive, bản dịch đa ngôn ngữ và kiểm soát trạng thái public rõ ràng.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171018, 17009, 'en', 'PEMS improves news publishing workflow after delegation visits', 'pems-improves-news-publishing-workflow-after-visit', 'PEMS now supports Drive-based image upload, multilingual article copies and clear public visibility control for news after visits.', 'PEMS improves news publishing workflow after delegation visits', 'PEMS now supports Drive-based image upload, multilingual article copies and clear public visibility control for news after visits.', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171019, 17009, 'zh-CN', 'PEMS优化接待后新闻发布流程', 'pems-news-publishing-workflow-zh-cn', 'PEMS支持通过Drive上传图片、多语言文章副本以及清晰的公开可见性控制。', 'PEMS优化接待后新闻发布流程', 'PEMS支持通过Drive上传图片、多语言文章副本以及清晰的公开可见性控制。', '2026-08-12 08:00:00', '2026-08-12 09:30:00'),
	(171020, 17010, 'vi', 'Bản nháp song ngữ về chương trình kết nối mentor doanh nghiệp', 'ban-nhap-song-ngu-ket-noi-mentor-doanh-nghiep', 'Bài đang chờ duyệt mô tả cách FPTU TP.HCM kết nối mentor doanh nghiệp với sinh viên trong hoạt động hậu sự kiện.', 'Bản nháp song ngữ về chương trình kết nối mentor doanh nghiệp', 'Bài đang chờ duyệt mô tả cách FPTU TP.HCM kết nối mentor doanh nghiệp với sinh viên trong hoạt động hậu sự kiện.', '2026-08-11 10:10:00', NULL),
	(171021, 17010, 'en', 'Bilingual draft on the industry mentor connection program', 'bilingual-draft-industry-mentor-connection-program', 'This pending article describes how FPTU Ho Chi Minh City connects industry mentors with students after partner visits.', 'Bilingual draft on the industry mentor connection program', 'This pending article describes how FPTU Ho Chi Minh City connects industry mentors with students after partner visits.', '2026-08-11 10:10:00', NULL),
	(171022, 17011, 'vi', 'FPTU Hà Nội và Porto AI Hub thống nhất chuỗi seminar AI ứng dụng', 'fptu-ha-noi-porto-ai-hub-thong-nhat-chuoi-seminar-ai-ung-dung', 'Chuỗi seminar AI ứng dụng dự kiến giúp sinh viên tiếp cận case study từ đối tác quốc tế, kết hợp thảo luận học thuật và bài tập thực hành.', 'FPTU Hà Nội và Porto AI Hub thống nhất chuỗi seminar AI ứng dụng', 'Chuỗi seminar AI ứng dụng dự kiến giúp sinh viên tiếp cận case study từ đối tác quốc tế, kết hợp thảo luận học thuật và bài tập thực hành.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171023, 17011, 'en', 'FPTU Hanoi and Porto AI Hub agree on applied AI seminar series', 'fptu-hanoi-porto-ai-hub-applied-ai-seminar-series', 'The applied AI seminar series will expose students to international case studies, academic discussion and practical exercises.', 'FPTU Hanoi and Porto AI Hub agree on applied AI seminar series', 'The applied AI seminar series will expose students to international case studies, academic discussion and practical exercises.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171024, 17011, 'ko', 'FPTU 하노이와 Porto AI Hub, 응용 AI 세미나 시리즈 합의', 'fptu-hanoi-porto-ai-hub-applied-ai-seminar-ko', '응용 AI 세미나 시리즈는 학생들에게 국제 사례, 학술 토론, 실습 과제를 제공할 예정이다.', 'FPTU 하노이와 Porto AI Hub, 응용 AI 세미나 시리즈 합의', '응용 AI 세미나 시리즈는 학생들에게 국제 사례, 학술 토론, 실습 과제를 제공할 예정이다.', '2026-08-10 08:20:00', '2026-08-10 10:40:00'),
	(171026, 17013, 'vi', '🤝 FPT UNIVERSITY KÝ KẾT BIÊN BẢN GHI NHỚ HỢP TÁC (MOU) VỚI AJOU UNIVERSITY, HÀN QUỐC 🤝', 'fpt-university-ky-ket-bien-ban-ghi-nho-hop-tac-mou-voi-ajou-university-han-quoc-17013', '🌏 FPT University vừa chính thức ký kết Biên bản ghi nhớ hợp tác (MOU) với Ajou University – một trong những trường đại học hàng đầu Hàn Quốc, nổi bật với thế mạnh về công nghệ, kỹ thuật, kinh doanh và nghiên cứu quốc tế.', '🤝 FPT UNIVERSITY KÝ KẾT BIÊN BẢN GHI NHỚ HỢP TÁC (MOU) VỚI AJOU UNIVERSITY, HÀN QUỐC 🤝', '🌏 FPT University vừa chính thức ký kết Biên bản ghi nhớ hợp tác (MOU) với Ajou University – một trong những trường đại học hàng đầu Hàn Quốc, nổi bật với thế mạnh về công nghệ, kỹ thuật, kinh doanh và nghiên cứu quốc tế.', '2026-08-08 22:30:15', NULL),
	(171027, 17013, 'en', '🤝 FPT UNIVERSITY SIGNS MEMORANDUM OF COOPERATION (MOU) WITH AJOU UNIVERSITY, SOUTH KOREA 🤝', 'fpt-university-signs-memorandum-of-cooperation-mou-with-ajou-university-south-korea-17013-en', '🌏 FPT University has officially signed a Memorandum of Understanding (MOU) with Ajou University – one of South Korea\'s leading universities, renowned for its strengths in technology, engineering, business, and international research.', '🤝 FPT UNIVERSITY SIGNS MEMORANDUM OF COOPERATION (MOU) WITH AJOU UNIVERSITY, SOUTH KOREA 🤝', '🌏 FPT University has officially signed a Memorandum of Understanding (MOU) with Ajou University – one of South Korea\'s leading universities, renowned for its strengths in technology, engineering, business, and international research.', '2026-08-08 22:30:15', NULL),
	(171028, 17014, 'vi', '🤝 TRƯỜNG ĐẠI HỌC FPT HÂN HẠNH CHÀO ĐÓN ĐOÀN ĐẠI BIỂU TỪ YUAN ZE UNIVERSITY ĐẾN THAM QUAN VÀ LÀM VIỆC🤝', 'truong-ai-hoc-fpt-han-hanh-chao-on-oan-ai-bieu-tu-yuan-ze-university-en-tham-quan-va-lam-viec-17014', '🌏 Yuan Ze University (YZU) - Trường Đại học Nguyên Trí  là một trong những trường đại học hàng đầu tại Đài Loan, nổi bật với thế mạnh về kỹ thuật, công nghệ, trí tuệ nhân tạo và đào tạo nguồn nhân lực cho ngành công nghiệp bán dẫn. Nhà trường có mối liên kết chặt chẽ với doanh nghiệp và tích cực thúc đẩy hợp tác quốc tế trong giáo dục và nghiên cứu.', '🤝 TRƯỜNG ĐẠI HỌC FPT HÂN HẠNH CHÀO ĐÓN ĐOÀN ĐẠI BIỂU TỪ YUAN ZE UNIVERSITY ĐẾN THAM QUAN VÀ LÀM VIỆC🤝', '🌏 Yuan Ze University (YZU) - Trường Đại học Nguyên Trí  là một trong những trường đại học hàng đầu tại Đài Loan, nổi bật với thế mạnh về kỹ thuật, công nghệ, trí tuệ nhân tạo và đào tạo nguồn nhân lực cho ngành công nghiệp bán dẫn. Nhà trường có mối liên kết chặt chẽ với doanh nghiệp và tích cực thúc đẩy hợp tác quốc tế trong giáo dục và nghiên cứu.', '2026-08-09 00:41:39', NULL),
	(171029, 17014, 'en', '🤝 FPT UNIVERSITY IS HONORED TO WELCOME THE DELEGATION FROM YUAN ZE UNIVERSITY FOR A VISIT AND WORKING TRIP 🤝', 'fpt-university-is-honored-to-welcome-the-delegation-from-yuan-ze-university-for-a-visit-and-working--17014-en', '🌏 Yuan Ze University (YZU) is one of Taiwan\'s leading universities, excelling in engineering, technology, artificial intelligence, and training human resources for the semiconductor industry. The university maintains strong ties with businesses and actively promotes international cooperation in education and research.', '🤝 FPT UNIVERSITY IS HONORED TO WELCOME THE DELEGATION FROM YUAN ZE UNIVERSITY FOR A VISIT AND WORKING TRIP 🤝', '🌏 Yuan Ze University (YZU) is one of Taiwan\'s leading universities, excelling in engineering, technology, artificial intelligence, and training human resources for the semiconductor industry. The university maintains strong ties with businesses and actively promotes international cooperation in education and research.', '2026-08-09 00:41:39', NULL),
	(171030, 17015, 'vi', '🌐🇸🇬 MỞ RỘNG CƠ HỘI HỢP TÁC CÙNG SINGAPORE MANAGEMENT UNIVERSITY🌐🇸🇬\n[English below]', 'mo-rong-co-hoi-hop-tac-cung-singapore-management-university-english-below-17015', '🌏 Singapore Management University (SMU) là một trong những trường đại học hàng đầu Singapore, nổi bật với thế mạnh về kinh doanh, quản lý, kinh tế, công nghệ và đổi mới sáng tạo. Với môi trường học tập hiện đại và mạng lưới hợp tác quốc tế rộng khắp, SMU là điểm đến của nhiều chương trình nghiên cứu và trao đổi học thuật trên toàn cầu.', '🌐🇸🇬 MỞ RỘNG CƠ HỘI HỢP TÁC CÙNG SINGAPORE MANAGEMENT UNIVERSITY🌐🇸🇬\n[English below]', '🌏 Singapore Management University (SMU) là một trong những trường đại học hàng đầu Singapore, nổi bật với thế mạnh về kinh doanh, quản lý, kinh tế, công nghệ và đổi mới sáng tạo. Với môi trường học tập hiện đại và mạng lưới hợp tác quốc tế rộng khắp, SMU là điểm đến của nhiều chương trình nghiên cứu và trao đổi học thuật trên toàn cầu.', '2026-08-09 16:52:53', NULL),
	(171031, 17015, 'en', '🌐🇸🇬 EXPANDING OPPORTUNITIES FOR COLLABORATION WITH SINGAPORE MANAGEMENT UNIVERSITY🌐🇸🇬\n[English below]', 'expanding-opportunities-for-collaboration-with-singapore-management-university-english-below-17015-en', '🌏 Singapore Management University (SMU) is one of Singapore\'s leading universities, excelling in business, management, economics, technology, and innovation. With its modern learning environment and extensive international collaboration network, SMU is a destination for numerous research and academic exchange programs worldwide.', '🌐🇸🇬 EXPANDING OPPORTUNITIES FOR COLLABORATION WITH SINGAPORE MANAGEMENT UNIVERSITY🌐🇸🇬\n[English below]', '🌏 Singapore Management University (SMU) is one of Singapore\'s leading universities, excelling in business, management, economics, technology, and innovation. With its modern learning environment and extensive international collaboration network, SMU is a destination for numerous research and academic exchange programs worldwide.', '2026-08-09 16:52:53', NULL),
	(171032, 17016, 'vi', '🎓 RWE KHÁM PHÁ HỆ SINH THÁI GIÁO DỤC VÀ ĐỔI MỚI SÁNG TẠO TẠI FPT UNIVERSITY 🎓', 'rwe-kham-pha-he-sinh-thai-giao-duc-va-oi-moi-sang-tao-tai-fpt-university-17016', '🌏Đoàn RWE cũng ấn tượng bởi các dự án văn hóa do sinh viên thực hiện qua đó có cơ hội gặp gỡ, tìm hiểu về thế hệ nhân lực tương lai của FPT thông qua những hoạt động học tập, nghiên cứu và đổi mới sáng tạo của sinh viên.', '🎓 RWE KHÁM PHÁ HỆ SINH THÁI GIÁO DỤC VÀ ĐỔI MỚI SÁNG TẠO TẠI FPT UNIVERSITY 🎓', '🌏Đoàn RWE cũng ấn tượng bởi các dự án văn hóa do sinh viên thực hiện qua đó có cơ hội gặp gỡ, tìm hiểu về thế hệ nhân lực tương lai của FPT thông qua những hoạt động học tập, nghiên cứu và đổi mới sáng tạo của sinh viên.', '2026-08-09 17:09:18', NULL),
	(171033, 17016, 'en', '🎓 RWE EXPLORE THE EDUCATIONAL AND INNOVATION ECOSYSTEM AT FPT UNIVERSITY 🎓', 'rwe-explore-the-educational-and-innovation-ecosystem-at-fpt-university-17016-en', '🌏 The RWE delegation was also impressed by the cultural projects carried out by students, providing an opportunity to meet and learn about the future workforce of FPT through students\' learning, research, and innovative activities.', '🎓 RWE EXPLORE THE EDUCATIONAL AND INNOVATION ECOSYSTEM AT FPT UNIVERSITY 🎓', '🌏 The RWE delegation was also impressed by the cultural projects carried out by students, providing an opportunity to meet and learn about the future workforce of FPT through students\' learning, research, and innovative activities.', '2026-08-09 17:09:18', NULL),
	(171034, 17017, 'vi', '🌏FPT UNIVERSITY VÀ YANGZHOU UNIVERSITY TRAO ĐỔI CƠ HỘI HỢP TÁC HỌC THUẬT VÀ NGHIÊN CỨU 🌏', 'fpt-university-va-yangzhou-university-trao-oi-co-hoi-hop-tac-hoc-thuat-va-nghien-cuu-17017', '🤝 Trong khuôn khổ buổi gặp gỡ, hai bên đã thảo luận về tiềm năng triển khai các chương trình thực tập (OJT), thúc đẩy trao đổi học thuật trong lĩnh vực vi điện tử và các ngành liên quan, đồng thời mở rộng cơ hội hợp tác nghiên cứu giữa giảng viên và sinh viên của hai trường.', '🌏FPT UNIVERSITY VÀ YANGZHOU UNIVERSITY TRAO ĐỔI CƠ HỘI HỢP TÁC HỌC THUẬT VÀ NGHIÊN CỨU 🌏', '🤝 Trong khuôn khổ buổi gặp gỡ, hai bên đã thảo luận về tiềm năng triển khai các chương trình thực tập (OJT), thúc đẩy trao đổi học thuật trong lĩnh vực vi điện tử và các ngành liên quan, đồng thời mở rộng cơ hội hợp tác nghiên cứu giữa giảng viên và sinh viên của hai trường.', '2026-08-09 17:12:08', NULL),
	(171035, 17017, 'en', '🌏 FPT UNIVERSITY AND YANGZHOU UNIVERSITY EXCHANGE OPPORTUNITIES FOR ACADEMIC AND RESEARCH COLLABORATION 🌏', 'fpt-university-and-yangzhou-university-exchange-opportunities-for-academic-and-research-collaboratio-17017-en', '🤝 During the meeting, both sides discussed the potential for implementing on-the-job training (OJT) programs, promoting academic exchange in microelectronics and related fields, and expanding opportunities for collaborative research between faculty and students of the two universities.', '🌏 FPT UNIVERSITY AND YANGZHOU UNIVERSITY EXCHANGE OPPORTUNITIES FOR ACADEMIC AND RESEARCH COLLABORATION 🌏', '🤝 During the meeting, both sides discussed the potential for implementing on-the-job training (OJT) programs, promoting academic exchange in microelectronics and related fields, and expanding opportunities for collaborative research between faculty and students of the two universities.', '2026-08-09 17:12:08', NULL),
	(171036, 17018, 'vi', 'TRƯỜNG ĐẠI HỌC FPT VINH DỰ ĐÓN TIẾP ĐOÀN ĐẠI BIỂU NATIONAL UNIVERSITY OF SINGAPORE', 'truong-ai-hoc-fpt-vinh-du-on-tiep-oan-ai-bieu-national-university-of-singapore-17018', '✨Ngày 20/04, Phòng Hợp tác Quốc tế Trường Đại học FPT vinh dự chào đón đoàn đại biểu đến từ National University of Singapore (NUS) - trường đại học hàng đầu Singapore và trên thế giới.', 'TRƯỜNG ĐẠI HỌC FPT VINH DỰ ĐÓN TIẾP ĐOÀN ĐẠI BIỂU NATIONAL UNIVERSITY OF SINGAPORE', '✨Ngày 20/04, Phòng Hợp tác Quốc tế Trường Đại học FPT vinh dự chào đón đoàn đại biểu đến từ National University of Singapore (NUS) - trường đại học hàng đầu Singapore và trên thế giới.', '2026-08-09 17:17:07', NULL),
	(171037, 17018, 'en', 'FPT University is honored to welcome the delegation from the National University of Singapore.', 'fpt-university-is-honored-to-welcome-the-delegation-from-the-national-university-of-singapore-17018-en', '✨On April 20th, the International Cooperation Office of FPT University was honored to welcome a delegation from the National University of Singapore (NUS) - a leading university in Singapore and worldwide.', 'FPT University is honored to welcome the delegation from the National University of Singapore.', '✨On April 20th, the International Cooperation Office of FPT University was honored to welcome a delegation from the National University of Singapore (NUS) - a leading university in Singapore and worldwide.', '2026-08-09 17:17:07', NULL),
	(171038, 17019, 'vi', '🤝 FPT UNIVERSITY HÂN HẠNH CHÀO ĐÓN ĐOÀN ĐẠI BIỂU AIESEC NHẬT BẢN ĐẾN THAM QUAN VÀ LÀM VIỆC🤝', 'fpt-university-han-hanh-chao-on-oan-ai-bieu-aiesec-nhat-ban-en-tham-quan-va-lam-viec-17019', '🌏 AIESEC là tổ chức thanh niên quốc tế lớn nhất thế giới, hoạt động tại hơn 100 quốc gia và vùng lãnh thổ, với sứ mệnh phát triển năng lực lãnh đạo của thế hệ trẻ thông qua các chương trình trao đổi, thực tập và trải nghiệm quốc tế.', '🤝 FPT UNIVERSITY HÂN HẠNH CHÀO ĐÓN ĐOÀN ĐẠI BIỂU AIESEC NHẬT BẢN ĐẾN THAM QUAN VÀ LÀM VIỆC🤝', '🌏 AIESEC là tổ chức thanh niên quốc tế lớn nhất thế giới, hoạt động tại hơn 100 quốc gia và vùng lãnh thổ, với sứ mệnh phát triển năng lực lãnh đạo của thế hệ trẻ thông qua các chương trình trao đổi, thực tập và trải nghiệm quốc tế.', '2026-08-09 22:47:49', NULL),
	(171039, 17019, 'en', '🤝 FPT UNIVERSITY IS HONORED TO WELCOME THE AIESEC JAPAN DELEGATION TO VISIT AND WORK WITH US 🤝', 'fpt-university-is-honored-to-welcome-the-aiesec-japan-delegation-to-visit-and-work-with-us-17019-en', '🌏 AIESEC is the world\'s largest international youth organization, operating in over 100 countries and territories, with a mission to develop the leadership capabilities of young people through international exchange, internship, and experience programs.', '🤝 FPT UNIVERSITY IS HONORED TO WELCOME THE AIESEC JAPAN DELEGATION TO VISIT AND WORK WITH US 🤝', '🌏 AIESEC is the world\'s largest international youth organization, operating in over 100 countries and territories, with a mission to develop the leadership capabilities of young people through international exchange, internship, and experience programs.', '2026-08-09 22:47:49', NULL),
	(171040, 17020, 'vi', '🌏TRƯỜNG ĐẠI HỌC FPT HÂN HẠNH CHÀO ĐÓN ĐOÀN ĐẠI BIỂU TỪ THE FEDERAL UNIVERSITY OF RIO GRANDE DO SUL (UFRGS) 🌏', 'truong-ai-hoc-fpt-han-hanh-chao-on-oan-ai-bieu-tu-the-federal-university-of-rio-grande-do-sul-ufrgs-17020', '✨The Federal University of Rio Grande do Sul (UFRGS) là một trong những trường đại học công lập hàng đầu Brazil, nổi tiếng về chất lượng đào tạo, nghiên cứu khoa học và mạng lưới hợp tác quốc tế trong nhiều lĩnh vực.', '🌏TRƯỜNG ĐẠI HỌC FPT HÂN HẠNH CHÀO ĐÓN ĐOÀN ĐẠI BIỂU TỪ THE FEDERAL UNIVERSITY OF RIO GRANDE DO SUL (UFRGS) 🌏', '✨The Federal University of Rio Grande do Sul (UFRGS) là một trong những trường đại học công lập hàng đầu Brazil, nổi tiếng về chất lượng đào tạo, nghiên cứu khoa học và mạng lưới hợp tác quốc tế trong nhiều lĩnh vực.', '2026-08-09 23:40:34', NULL),
	(171041, 17020, 'en', '🌏 FPT University is honored to welcome the delegation from The Federal University of Rio Grande Do Sul (UFRGS) 🌏', 'fpt-university-is-honored-to-welcome-the-delegation-from-the-federal-university-of-rio-grande-do-sul-17020-en', '✨The Federal University of Rio Grande do Sul (UFRGS) is one of Brazil\'s leading public universities, renowned for its quality of education, scientific research, and international collaboration network across many fields.', '🌏 FPT University is honored to welcome the delegation from The Federal University of Rio Grande Do Sul (UFRGS) 🌏', '✨The Federal University of Rio Grande do Sul (UFRGS) is one of Brazil\'s leading public universities, renowned for its quality of education, scientific research, and international collaboration network across many fields.', '2026-08-09 23:40:34', NULL),
	(171042, 17021, 'vi', 'Đoàn khách tham quan và trải nghiệm môi trường học tập tại FPT University Hà Nội', 'oan-khach-tham-quan-va-trai-nghiem-moi-truong-hoc-tap-tai-fpt-university-ha-noi-17021', 'FPT University Hà Nội đã đón tiếp đoàn khách đến tham quan khuôn viên, tìm hiểu môi trường học tập, cơ sở vật chất và các hoạt động dành cho sinh viên. Chuyến tham quan mang đến cơ hội trải nghiệm thực tế và tìm hiểu rõ hơn về mô hình đào tạo tại FPT University.', 'Đoàn khách tham quan và trải nghiệm môi trường học tập tại FPT University Hà Nội', 'FPT University Hà Nội đã đón tiếp đoàn khách đến tham quan khuôn viên, tìm hiểu môi trường học tập, cơ sở vật chất và các hoạt động dành cho sinh viên. Chuyến tham quan mang đến cơ hội trải nghiệm thực tế và tìm hiểu rõ hơn về mô hình đào tạo tại FPT University.', '2026-08-11 15:59:59', NULL),
	(171043, 17021, 'en', 'The group visited and experienced the learning environment at FPT University Hanoi.', 'the-group-visited-and-experienced-the-learning-environment-at-fpt-university-hanoi-17021-en', 'FPT University Hanoi welcomed a delegation to tour the campus, learn about the learning environment, facilities, and student activities. The visit provided an opportunity for hands-on experience and a better understanding of the training model at FPT University.', 'The group visited and experienced the learning environment at FPT University Hanoi.', 'FPT University Hanoi welcomed a delegation to tour the campus, learn about the learning environment, facilities, and student activities. The visit provided an opportunity for hands-on experience and a better understanding of the training model at FPT University.', '2026-08-11 15:59:59', NULL),
	(171044, 17022, 'vi', '[STUDY TOUR SPRING 2026] SAWADEEKAA - ĐI THÁI LAN NHAA!!!', 'study-tour-spring-2026-sawadeekaa---i-thai-lan-nhaa-17022', '📌 Bangkok - thủ đô và cũng là thành phố quan trọng nhất Thái Lan - một trong những điểm đến có sức hút siêu khủng đối trên bản đồ du lịch Châu Á.', '[STUDY TOUR SPRING 2026] SAWADEEKAA - ĐI THÁI LAN NHAA!!!', '📌 Bangkok - thủ đô và cũng là thành phố quan trọng nhất Thái Lan - một trong những điểm đến có sức hút siêu khủng đối trên bản đồ du lịch Châu Á.', '2026-08-13 17:11:15', NULL),
	(171045, 17022, 'en', '[STUDY TOUR SPRING 2026] SAWADEEKAA - LET\'S GO TO THAILAND!!!', 'study-tour-spring-2026-sawadeekaa---lets-go-to-thailand-17022-en', '📌 Bangkok – the capital and most important city of Thailand – is one of the most attractive destinations on the Asian tourism map.', '[STUDY TOUR SPRING 2026] SAWADEEKAA - LET\'S GO TO THAILAND!!!', '📌 Bangkok – the capital and most important city of Thailand – is one of the most attractive destinations on the Asian tourism map.', '2026-08-13 17:11:15', NULL),
	(171046, 17023, 'vi', '🌍 HARVARD BUSINESS SCHOOL × TRƯỜNG ĐẠI HỌC FPT', 'harvard-business-school-truong-ai-hoc-fpt-17023', 'Ngày 30/06 vừa qua, Trường Đại học FPT vinh dự chào đón đoàn đại diện từ Harvard Business School trong chuyến thăm và làm việc tại FPT Education.', '🌍 HARVARD BUSINESS SCHOOL × TRƯỜNG ĐẠI HỌC FPT', 'Ngày 30/06 vừa qua, Trường Đại học FPT vinh dự chào đón đoàn đại diện từ Harvard Business School trong chuyến thăm và làm việc tại FPT Education.', '2026-08-13 22:10:09', NULL),
	(171047, 17023, 'en', '🌍 HARVARD BUSINESS SCHOOL × FPT UNIVERSITY', 'harvard-business-school-fpt-university-17023-en', 'On June 30th, FPT University had the honor of welcoming a delegation from Harvard Business School for a visit and working session at FPT Education.', '🌍 HARVARD BUSINESS SCHOOL × FPT UNIVERSITY', 'On June 30th, FPT University had the honor of welcoming a delegation from Harvard Business School for a visit and working session at FPT Education.', '2026-08-13 22:10:09', NULL),
	(171048, 17024, 'vi', '[HOT] Hàng loạt kênh truyền thông Nhật Bản đưa tin về thực tập sinh đến từ Trường Đại học FPT Hà Nội', 'hot-hang-loat-kenh-truyen-thong-nhat-ban-ua-tin-ve-thuc-tap-sinh-en-tu-truong-ai-hoc-fpt-ha-noi-17024', 'Ngày 06/02 vừa qua, Nguyễn Đăng Khoa, sinh viên Kỹ thuật phần mềm chuyên ngành hẹp JS - đã chính thức hoàn thành kỳ thực tập tại công ty Kanto Seiki (Gunma, Nhật Bản). Trong buổi tổng kết, Khoa đã thuyết trình bằng tiếng Nhật về quá trình phát triển ứng dụng hỗ trợ sản xuất cùng các kỹ sư tại đây.', '[HOT] Hàng loạt kênh truyền thông Nhật Bản đưa tin về thực tập sinh đến từ Trường Đại học FPT Hà Nội', 'Ngày 06/02 vừa qua, Nguyễn Đăng Khoa, sinh viên Kỹ thuật phần mềm chuyên ngành hẹp JS - đã chính thức hoàn thành kỳ thực tập tại công ty Kanto Seiki (Gunma, Nhật Bản). Trong buổi tổng kết, Khoa đã thuyết trình bằng tiếng Nhật về quá trình phát triển ứng dụng hỗ trợ sản xuất cùng các kỹ sư tại đây.', '2026-08-14 22:26:57', NULL),
	(171049, 17024, 'en', '[HOT] Numerous Japanese media outlets report on interns from FPT University Hanoi.', 'hot-numerous-japanese-media-outlets-report-on-interns-from-fpt-university-hanoi-17024-en', 'On February 6th, Nguyen Dang Khoa, a Software Engineering student specializing in JS, officially completed his internship at Kanto Seiki Company (Gunma, Japan). During the closing ceremony, Khoa gave a presentation in Japanese about the development process of a production support application with the engineers there.', '[HOT] Numerous Japanese media outlets report on interns from FPT University Hanoi.', 'On February 6th, Nguyen Dang Khoa, a Software Engineering student specializing in JS, officially completed his internship at Kanto Seiki Company (Gunma, Japan). During the closing ceremony, Khoa gave a presentation in Japanese about the development process of a production support application with the engineers there.', '2026-08-14 22:26:57', NULL),
	(171050, 17025, 'vi', 'Khánh thành điểm trường vùng cao: Thắp sáng ước mơ tìm chữ của trẻ em nghèo', 'khanh-thanh-iem-truong-vung-cao-thap-sang-uoc-mo-tim-chu-cua-tre-em-ngheo-17025', 'Sáng ngày 15/8, chính quyền địa phương phối hợp cùng các nhà hảo tâm đã chính thức cắt băng khánh thành điểm trường mầm non mới tại vùng sâu vùng xa, mở ra không gian học tập an toàn, ấm áp cho hơn 100 học sinh dân tộc thiểu số trước thềm năm học mới.', 'Khánh thành điểm trường vùng cao: Thắp sáng ước mơ tìm chữ của trẻ em nghèo', 'Sáng ngày 15/8, chính quyền địa phương phối hợp cùng các nhà hảo tâm đã chính thức cắt băng khánh thành điểm trường mầm non mới tại vùng sâu vùng xa, mở ra không gian học tập an toàn, ấm áp cho hơn 100 học sinh dân tộc thiểu số trước thềm năm học mới.', '2026-08-15 11:16:23', NULL),
	(171051, 17025, 'en', 'Inauguration of a school in a remote mountainous area: Lighting up the dream of literacy for poor children.', 'inauguration-of-a-school-in-a-remote-mountainous-area-lighting-up-the-dream-of-literacy-for-poor-chi-17025-en', 'On the morning of August 15th, local authorities, in collaboration with philanthropists, officially inaugurated a new preschool in a remote area, creating a safe and warm learning environment for over 100 ethnic minority students ahead of the new school year.', 'Inauguration of a school in a remote mountainous area: Lighting up the dream of literacy for poor children.', 'On the morning of August 15th, local authorities, in collaboration with philanthropists, officially inaugurated a new preschool in a remote area, creating a safe and warm learning environment for over 100 ethnic minority students ahead of the new school year.', '2026-08-15 11:16:23', NULL),
	(171052, 17026, 'vi', 'Rộn ràng ngày hội trải nghiệm: Phụ huynh ngỡ ngàng trước diện mạo mới của trường Bản Mây', 'ron-rang-ngay-hoi-trai-nghiem-phu-huynh-va-hoc-sinh-ngo-ngang-truoc-dien-mao-moi-cua-truong-ban-may-17026', 'Sáng ngày 15/8/2026, cụm trường Bản Mây đã mở cửa đón tiếp hơn 300 phụ huynh và học sinh đến tham quan, trải nghiệm không gian học tập trước thềm năm học mới. Đây là hoạt động thiết thực giúp các em học sinh đầu cấp xóa tan bỡ ngỡ, đồng thời chứng kiến sự thay đổi ngoạn mục về cơ sở vật chất sau chiến dịch đại trùng tu.', 'Rộn ràng ngày hội trải nghiệm: Phụ huynh ngỡ ngàng trước diện mạo mới của trường Bản Mây', 'Sáng ngày 15/8/2026, cụm trường Bản Mây đã mở cửa đón tiếp hơn 300 phụ huynh và học sinh đến tham quan, trải nghiệm không gian học tập trước thềm năm học mới. Đây là hoạt động thiết thực giúp các em học sinh đầu cấp xóa tan bỡ ngỡ, đồng thời chứng kiến sự thay đổi ngoạn mục về cơ sở vật chất sau chiến dịch đại trùng tu.', '2026-08-15 11:19:47', '2026-08-16 01:36:33'),
	(171053, 17026, 'en', 'A bustling experience day: Parents and students amazed by the new look of Ban May School.', 'a-bustling-experience-day-parents-and-students-amazed-by-the-new-look-of-ban-may-school-17026-en', 'On the morning of August 15, 2026, the Ban May school complex opened its doors to welcome over 300 parents and students to visit and experience the learning environment ahead of the new school year. This practical activity helps students entering the first grade overcome their initial anxieties and witness the spectacular changes in facilities after the major renovation campaign.', 'A bustling experience day: Parents and students amazed by the new look of Ban May School.', 'On the morning of August 15, 2026, the Ban May school complex opened its doors to welcome over 300 parents and students to visit and experience the learning environment ahead of the new school year. This practical activity helps students entering the first grade overcome their initial anxieties and witness the spectacular changes in facilities after the major renovation campaign.', '2026-08-15 11:19:47', '2026-08-16 01:36:34'),
	(171054, 17027, 'vi', 'Tiêu đề :     \n\n🤝 FPT EDUCATION THÚC ĐẨY HỢP TÁC VỚI GUILIN UNIVERSITY OF ELECTRONIC TECHNOLOGY 🤝', 'tieu-e-fpt-education-thuc-ay-hop-tac-voi-guilin-university-of-electronic-technology-17027', 'Guilin University of Electronic Technology (GUET) là một trong những trường đại học hàng đầu của Trung Quốc trong lĩnh vực điện tử, công nghệ thông tin, viễn thông và kỹ thuật.', 'Tiêu đề :     \n\n🤝 FPT EDUCATION THÚC ĐẨY HỢP TÁC VỚI GUILIN UNIVERSITY OF ELECTRONIC TECHNOLOGY 🤝', 'Guilin University of Electronic Technology (GUET) là một trong những trường đại học hàng đầu của Trung Quốc trong lĩnh vực điện tử, công nghệ thông tin, viễn thông và kỹ thuật.', '2026-08-15 22:31:15', NULL),
	(171055, 17027, 'en', 'Title:\n\n🤝 FPT EDUCATION PROMOTES COLLABORATION WITH GUILIN UNIVERSITY OF ELECTRONIC TECHNOLOGY 🤝', 'title-fpt-education-promotes-collaboration-with-guilin-university-of-electronic-technology-17027-en', 'Guilin University of Electronic Technology (GUET) is one of China\'s leading universities in the fields of electronics, information technology, telecommunications, and engineering.', 'Title:\n\n🤝 FPT EDUCATION PROMOTES COLLABORATION WITH GUILIN UNIVERSITY OF ELECTRONIC TECHNOLOGY 🤝', 'Guilin University of Electronic Technology (GUET) is one of China\'s leading universities in the fields of electronics, information technology, telecommunications, and engineering.', '2026-08-15 22:31:15', NULL),
