	(6, 6, 'vi', 'Nordic Sustainability Alliance', 'NSA', 'Phần Lan', 'Helsinki', 'Tổ chức phi lợi nhuận về phát triển bền vững; thường yêu cầu nội dung campus xanh và workshop sinh viên.', 'Helsinki Innovation Hub', 'LEGACY', 'READY', '3ed5d9e89ea7a6017fd864a9bea8b0c77e6902b0e0b8b3638c7963eedace45c9', '2026-03-05 11:00:00', '2026-03-05 09:00:00', 2, '2026-03-05 11:00:00', 2),
