	(8, 102, 'vi', 'Politecnico di Milano Mobility Lab', 'Polimi Mobility', 'Ý', 'Milan', 'Politecnico di Milano Mobility Lab quan tâm mô hình campus xanh, quản trị di chuyển nội khu và thiết kế trải nghiệm tham quan cho đoàn nghiên cứu đô thị. Cần Staff Leader rà soát phạm vi truyền thông trước khi public.', 'Milan partnership district', 'LEGACY', 'READY', 'd4fd25cfff74c6e208f917c10d0b1172c8364750c0415771131a192e999d9c77', '2026-08-08 17:05:04', '2026-04-12 08:00:00', 4, '2026-08-08 17:05:04', NULL),
	(9, 103, 'vi', 'University of Technology Sydney Student Exchange', 'UTS Exchange', 'Úc', 'Sydney', 'UTS Student Exchange là đối tác đã xác minh cho workshop kỹ năng toàn cầu, trao đổi sinh viên ngắn hạn và phiên tư vấn học kỳ quốc tế. Hồ sơ dùng tốt cho public partner listing.', 'Sydney partnership district', 'LEGACY', 'READY', '1d75d29fd0c6a2a7d585fb1fab95fea4b7c2ad5ed5e7c0360c2d941bd3552eb2', '2026-08-09 16:04:38', '2026-04-12 08:00:00', 4, '2026-08-09 16:04:38', 3),
	(10, 104, 'vi', 'Nordic Green Campus Alliance', 'Nordic Green', 'Đan Mạch', 'Copenhagen', 'Nordic Green Campus Alliance từng đề xuất hợp tác phát triển bền vững nhưng bộ hồ sơ pháp lý chưa chứng minh được tư cách đại diện mạng lưới, vì vậy bị từ chối public.', 'Copenhagen partnership district', 'LEGACY', 'READY', 'b377244f59e5ed3d3156a8db05a0d2b8bbe5f9f92ce44cabd19780df605a4490', '2026-08-08 17:05:04', '2026-04-12 08:00:00', 4, '2026-08-08 17:05:04', 2),
	(11, 105, 'vi', 'Paris Digital Arts Institute', 'Paris Digital', 'Pháp', 'Paris', 'Paris Digital Arts Institute là đối tác cũ về media art và thiết kế tương tác; hiện tạm inactive vì chưa có chương trình trao đổi mới trong năm học hiện tại.', 'Paris partnership district', 'LEGACY', 'READY', '21b8bcfe38eaa4db36d02d289b5eaef4e2929caf30036d260ba1578db90d784c', '2026-08-09 16:03:15', '2026-04-12 08:00:00', 4, '2026-08-09 16:03:15', 3),
