	(89, 158, 'vi', 'Asia-Pacific Academic Alliance', NULL, 'Philippines', NULL, 'Tạo từ biên bản cuộc họp #49011', NULL, 'LEGACY', 'READY', 'bb72278b9b2f462138846118b9344757fad4f69908882ea9a19a8271fc42fc62', '2026-08-25 11:47:40', '2026-08-25 11:47:40', 3, NULL, NULL),
	(90, 159, 'vi', 'LGCNS', NULL, 'Hàn Quốc', 'Andong-si', 'LG CNS is a major South Korean IT services and consulting corporation established in 1987. It specializes in digital business innovation, AI transformation (AX), cloud computing, smart factories, and smart logistics. Operating globally with thousands of employees, it also has a strong presence in Vietnam (located in Hanoi).', NULL, 'LEGACY', 'READY', '555e7d1cd38a83e48de290ca4635b4156c41d4b4a2744b4180991b9b5836bc13', '2026-08-25 21:51:20', '2026-08-25 21:51:20', 3, NULL, NULL),
