	(1, 1, 'P-SEOU-TECH', 'SeoulTech Global Engagement Center Korean', 'SeoulTech GEC', 'Hàn Quốc', 'Seoul', 'https://seoultechglobal.org/', 'COMPANY', 'ACTIVE', 'Đối tác trọng tâm cho trao đổi sinh viên kỹ thuật, seminar AI ứng dụng và mô hình campus thông minh.', 57, 58, '232 Gongneung-ro, Nowon-gu, Seoul', 'seoultech-global-engagement-center', 'APPROVED', 'Đã xác minh hồ sơ và liên hệ chính.', 2, '2026-03-01 14:00:00', 'PUBLIC', '2026-03-01 08:30:00', 4, '2026-08-14 18:40:42', 3),
	(2, 1, 'P-KYOTO-ROBO', 'Kyoto Robotics Collaboration Lab', 'Kyoto RoboLab', 'Nhật Bản', 'Kyoto', 'https://www.robot.soc.i.kyoto-u.ac.jp/en/', 'COMPANY', 'ACTIVE', 'Phòng thí nghiệm doanh nghiệp về robot dịch vụ; quan tâm workshop ngắn hạn và showcase tại campus.', 59, 60, 'Sakyo Innovation Quarter, Kyoto', 'kyoto-robotics-collaboration-lab', 'APPROVED', 'Logo được scan từ business card, cần cập nhật cover sau chuyến thăm.', 3, '2026-03-02 15:00:00', 'INTERNAL', '2026-03-02 09:20:00', 4, '2026-08-09 16:09:12', 3),
	(3, 1, 'P-GREEN-MOB', 'Singapore Green Mobility Council', 'SGMC', 'Singapore', 'Singapore', 'https://greenmobility.example.sg', 'GOVERNMENT', 'POTENTIAL', 'Hội đồng thúc đẩy giao thông xanh; đang trao đổi khả năng ký MOU về workshop xe điện trong khuôn viên.', NULL, NULL, '1 Marina Boulevard, Singapore', 'singapore-green-mobility-council', 'PENDING_APPROVAL', 'Đang chờ hoàn tất hồ sơ pháp lý và xác nhận phạm vi hợp tác giữa các campus.', NULL, NULL, 'PRIVATE', '2026-03-03 10:30:00', 4, NULL, NULL),
	(4, 5, 'P-ASEAN-HOSP', 'ASEAN Hospitality Network', 'AHN', 'Thái Lan', 'Bangkok', 'https://asean-hospitality.example.org', 'NGO', 'ACTIVE', 'Mạng lưới khách sạn và du lịch khu vực; phù hợp với campus Quy Nhơn và chương trình hospitality.', NULL, NULL, '88 Sukhumvit Road, Bangkok', 'asean-hospitality-network', 'APPROVED', 'Ưu tiên dùng cho đoàn thăm Quy Nhơn.', 2, '2026-03-04 10:00:00', 'PUBLIC', '2026-03-04 09:30:00', 15, '2026-03-04 10:00:00', 2),
	(5, 1, 'P-MUNICH-AI', 'Munich Applied AI Institute', 'MAAI', 'Đức', 'Munich', NULL, 'UNIVERSITY', 'POTENTIAL', 'Nhóm nghiên cứu AI ứng dụng quan tâm mô hình blended learning và phòng lab tại campus HN.', NULL, NULL, 'Garching Research District, Munich', 'munich-applied-ai-institute', 'DRAFT', NULL, NULL, NULL, 'PRIVATE', '2026-03-05 08:30:00', 4, NULL, NULL),
	(6, 1, 'P-NORDIC-SUS', 'Nordic Sustainability Alliance', 'NSA', 'Phần Lan', 'Helsinki', 'https://nordic-sustainability.example.fi', 'NGO', 'ACTIVE', 'Tổ chức phi lợi nhuận về phát triển bền vững; thường yêu cầu nội dung campus xanh và workshop sinh viên.', NULL, NULL, 'Helsinki Innovation Hub', 'nordic-sustainability-alliance', 'APPROVED', 'Hồ sơ public chỉ hiển thị sau khi bổ sung ảnh hoạt động.', 2, '2026-03-05 11:00:00', 'INTERNAL', '2026-03-05 09:00:00', 2, '2026-03-05 11:00:00', 2),
	(101, 1, 'P-IIT-DELHI', 'Indian Institute of Technology Delhi International Office', 'IIT Delhi IO', 'Ấn Độ', 'New Delhi', 'https://p-iit-delhi.example.org', 'UNIVERSITY', 'POTENTIAL', 'IIT Delhi International Office gửi đề xuất trao đổi học thuật về AI ứng dụng, kiểm định chương trình và mô hình cố vấn sinh viên quốc tế. Hồ sơ còn thiếu thư giới thiệu chính thức nên giữ ở trạng thái draft.', NULL, NULL, 'New Delhi partnership district', 'p-iit-delhi', 'DRAFT', 'Chờ thư giới thiệu chính thức và danh sách người đại diện trước khi gửi duyệt.', NULL, NULL, 'PRIVATE', '2026-04-12 08:00:00', 4, '2026-08-08 17:05:04', NULL),
	(102, 1, 'P-POLIMI', 'Politecnico di Milano Mobility Lab', 'Polimi Mobility', 'Ý', 'Milan', 'https://p-polimi.example.org', 'UNIVERSITY', 'ACTIVE', 'Politecnico di Milano Mobility Lab quan tâm mô hình campus xanh, quản trị di chuyển nội khu và thiết kế trải nghiệm tham quan cho đoàn nghiên cứu đô thị. Cần Staff Leader rà soát phạm vi truyền thông trước khi public.', NULL, NULL, 'Milan partnership district', 'p-polimi', 'PENDING_APPROVAL', 'Cần Staff Leader kiểm tra nội dung hợp tác mobility có liên quan nhiều campus hay chỉ trong campus sở hữu.', NULL, NULL, 'INTERNAL', '2026-04-12 08:00:00', 4, '2026-08-08 17:05:04', NULL),
	(103, 1, 'P-UTS-AUS', 'University of Technology Sydney Student Exchange', 'UTS Exchange', 'Úc', 'Sydney', 'https://study.anu.edu.au/apply/postgraduate-research?utm_source=google&utm_medium=paid_search&utm_campaign=intl_vietnam_sem_y26&utm_id=ANU005.2.04&utm_journey=ao_prosp_alwayson&utm_format=search&utm_content=search_research_phd&gad_source=1&gad_campaignid=23716326844&gbraid=0AAAAA-CX_HktE1aJv6_xNmpv9OIrP3q00&gclid=CjwKCAjwyuDTBhB-EiwANCQhLBfmT4o92aGL5tzNPi4U77LAN_38_hdd6QhQ820pmm3Y17XxT8vXzRoCfp8QAvD_BwE', 'UNIVERSITY', 'ACTIVE', 'UTS Student Exchange là đối tác đã xác minh cho workshop kỹ năng toàn cầu, trao đổi sinh viên ngắn hạn và phiên tư vấn học kỳ quốc tế. Hồ sơ dùng tốt cho public partner listing.', 55, 56, 'Sydney partnership district', 'p-uts-aus', 'APPROVED', 'Đã xác minh email domain, đầu mối liên hệ và phạm vi trao đổi sinh viên.', 2, '2026-04-12 10:00:00', 'PUBLIC', '2026-04-12 08:00:00', 4, '2026-08-09 16:04:38', 3),
	(104, 1, 'P-NORDIC-GREEN', 'Nordic Green Campus Alliance', 'Nordic Green', 'Đan Mạch', 'Copenhagen', 'https://p-nordic-green.example.org', 'NGO', 'POTENTIAL', 'Nordic Green Campus Alliance từng đề xuất hợp tác phát triển bền vững nhưng bộ hồ sơ pháp lý chưa chứng minh được tư cách đại diện mạng lưới, vì vậy bị từ chối public.', NULL, NULL, 'Copenhagen partnership district', 'p-nordic-green', 'REJECTED', 'Từ chối vì thiếu giấy tờ pháp nhân và chưa xác định được đơn vị chịu trách nhiệm ký kết.', 2, '2026-04-12 10:00:00', 'PRIVATE', '2026-04-12 08:00:00', 4, '2026-08-08 17:05:04', 2),
	(105, 1, 'P-PARIS-DIGITAL', 'Paris Digital Arts Institute', 'Paris Digital', 'Pháp', 'Paris', 'https://p-paris-digital.example.org', 'OTHER', 'INACTIVE', 'Paris Digital Arts Institute là đối tác cũ về media art và thiết kế tương tác; hiện tạm inactive vì chưa có chương trình trao đổi mới trong năm học hiện tại.', NULL, NULL, 'Paris partnership district', 'p-paris-digital', 'APPROVED', 'Giữ approved/internal để lưu lịch sử, chưa khuyến nghị đưa public.', 2, '2026-04-12 10:00:00', 'PRIVATE', '2026-04-12 08:00:00', 4, '2026-08-09 16:03:15', 3),
	(106, 1, 'P-GULF-INNOV', 'Gulf Innovation Fund for Education', 'Gulf InnovFund', 'UAE', 'Dubai', 'https://p-gulf-innov.example.org', 'GOVERNMENT', 'BLACKLISTED', 'Gulf Innovation Fund for Education có đề xuất tài trợ nhưng chưa hoàn tất kiểm tra nguồn quỹ và điều kiện truyền thông; hồ sơ được giữ ở trạng thái cảnh báo rủi ro.', NULL, NULL, 'Dubai partnership district', 'p-gulf-innov', 'REJECTED', 'Từ chối vì rủi ro nguồn tài trợ và điều kiện truyền thông chưa rõ.', 2, '2026-04-12 10:00:00', 'PRIVATE', '2026-04-12 08:00:00', 4, '2026-08-08 17:05:04', 2),
	(107, 1, 'P-SEATTLE-EDTECH', 'Seattle EdTech Studio', 'Seattle EdTech', 'Hoa Kỳ', 'Seattle', 'https://www.wested.org/subscribe/?gad_source=1&gad_campaignid=22333553670&gbraid=0AAAAAqZBEZRiQ-2Zn6N4_F1Ieepdl71Wn&gclid=CjwKCAjwyuDTBhB-EiwANCQhLBtcCyOsQ4CpzNeW0D0H4pjUQUhug_BdxPKdgZrgRhS75FIbTqpiqhoCs34QAvD_BwE', 'COMPANY', 'ACTIVE', 'Seattle EdTech Studio là doanh nghiệp công nghệ giáo dục, phù hợp các buổi demo adaptive learning, analytics lớp học và workshop sản phẩm sinh viên.', 53, 54, 'Seattle partnership district', 'p-seattle-edtech', 'APPROVED', 'Đã xác minh business profile, phù hợp demo sản phẩm và workshop nội bộ.', 2, '2026-04-12 10:00:00', 'PUBLIC', '2026-04-12 08:00:00', 4, '2026-08-09 16:02:17', 3),
