	(152, 1, 'GUILIN', 'GUILIN UNIVERSITY OF ELECTRONIC TECHNOLOGY', 'GUILIN', 'Trung Quốc', 'Aksu', 'https://htqt.ftu.edu.vn/lien-he/doi-tac/chau-a/10-%F0%9F%87%A8%F0%9F%87%B3-guilin-university-of-electronic-technology/', 'UNIVERSITY', 'POTENTIAL', 'Đại học Khoa học và Công nghệ Điện tử Quế Lâm là một trường đại học công lập tại thành phố Quế Lâm, Quảng Tây, Trung Quốc. Được thành lập vào năm 1960, hiện nay trường hoạt động trên ba cơ sở: Cơ sở Đông, Cơ sở Tây và Cơ sở Yaoshan.', 254, 255, NULL, NULL, 'APPROVED', NULL, 3, '2026-08-21 20:58:04', 'PUBLIC', '2026-08-15 22:17:16', 3, '2026-08-21 20:58:04', 3),
	(153, 1, NULL, 'NANNING UNIVERSITY', NULL, 'Hàn Quốc', 'Anseong', NULL, 'UNIVERSITY', 'POTENTIAL', 'Tạo từ biên bản cuộc họp #49015', NULL, NULL, NULL, NULL, 'PENDING_APPROVAL', NULL, NULL, NULL, 'INTERNAL', '2026-08-16 09:49:55', 3, NULL, NULL),
	(154, 1, 'TMAXTIBERO', 'TMAXTIBERO', 'TMAXTIBERO', 'Hàn Quốc', 'Ansan-si', 'https://docs.tibero.com/home/en', 'UNIVERSITY', 'POTENTIAL', 'TmaxTibero là một công ty phần mềm chuyên về hệ quản trị cơ sở dữ liệu (DBMS) thuộc tập đoàn Tmax (Hàn Quốc), nổi bật với sản phẩm chủ lực Tibero – một hệ quản trị cơ sở dữ liệu quan hệ (RDBMS) cấp độ doanh nghiệp có khả năng tương thích cao với Oracle', 245, 246, NULL, NULL, 'APPROVED', NULL, 3, '2026-08-21 20:55:56', 'INTERNAL', '2026-08-21 20:50:16', 3, '2026-08-21 20:55:56', 3),
	(155, 1, 'WU', 'Woosong University', 'WU', 'Hàn Quốc', 'Anseong', 'https://english.wsu.ac.kr/', 'UNIVERSITY', 'POTENTIAL', 'Được dịch từ tiếng Anh-Đại học Woosong là trường đại học 4 năm tọa lạc tại Daejeon, Hàn Quốc, cung cấp chương trình giảng dạy chuyên biệt dựa trên giáo dục ngoại ngữ và CNTT cho mọi lĩnh vực nghiên cứu chính.', 270, 271, NULL, NULL, 'APPROVED', NULL, 3, '2026-08-24 21:55:44', 'PUBLIC', '2026-08-24 21:30:06', 3, '2026-08-24 21:57:03', 3),
