	(99061, 70018, 'VISIT_PARTICIPANT', 99518, '[PEMS] Mời sinh viên hỗ trợ tiếp đón đoàn HARVARD BUSINESS SCHOOL', '<!DOCTYPE html>\n<html lang="vi"><head><meta charset="UTF-8"></head>\n<body style="font-family:Arial,sans-serif;background:#f4f6f9;margin:0;padding:20px">\n  <div style="max-width:560px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08)">\n    <div style="background:linear-gradient(135deg,#004c91,#013565);padding:28px 32px">\n      <h1 style="color:#fff;margin:0;font-size:22px">PEMS — Campus Visit</h1>\n      <p style="color:#b3c8e8;margin:6px 0 0;font-size:13px">FPT University</p>\n    </div>\n    <div style="padding:32px;color:#374151;font-size:14px"><p style="margin:0 0 16px;color:#334155">Xin chào <strong>Student Buddy H&#224; Nội</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">IC Staff Leader H&#224; Nội mời bạn tham gia hỗ trợ một chuyến tiếp khách tại FPT University H&#224; Nội. Đây là hoạt động tự nguyện dành cho sinh viên.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">HARVARD BUSINESS SCHOOL</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">09:00 20/08/2026 - 10:00 20/08/2026</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">FPT University H&#224; Nội</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Vai trò của bạn</td><td style="padding:10px 14px;font-weight:600;color:#334155">Sinh vi&#234;n hỗ trợ</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em></em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới. Nếu bạn nhận lời, thông tin tập trung và hướng dẫn chi tiết sẽ được gửi trước ngày diễn ra.</p></div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>IC Staff Leader H&#224; Nội</strong><br/>IC Staff — LEADER<br/>Ph&#242;ng Hợp t&#225;c Quốc tế<br/>staff.leader.hn@fpt.edu.vn</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p></div>\n    <div style="background:#f9fafb;padding:16px 32px;text-align:center">\n      <p style="color:#9ca3af;font-size:11px;margin:0">© 2026 PEMS — FPT University. Không trả lời email này.</p>\n    </div>\n  </div>\n</body></html>', 'HTML', NULL, NULL, 0, '2026-08-13 21:29:04', NULL, 'SENT', NULL, 3, '2026-08-13 21:29:04', '2026-08-13 21:29:04'),
	(99062, 70023, 'LOGISTICS_ITEM', 99013, '[PEMS] Yêu cầu hậu cần: Xe điện', '<!DOCTYPE html>\n<html lang="vi"><head><meta charset="UTF-8"></head>\n<body style="font-family:Arial,sans-serif;background:#f4f6f9;margin:0;padding:20px">\n  <div style="max-width:560px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08)">\n    <div style="background:linear-gradient(135deg,#004c91,#013565);padding:28px 32px">\n      <h1 style="color:#fff;margin:0;font-size:22px">PEMS — Campus Visit</h1>\n      <p style="color:#b3c8e8;margin:6px 0 0;font-size:13px">FPT University</p>\n    </div>\n    <div style="padding:32px;color:#374151;font-size:14px"><p style="margin:0 0 16px;color:#334155">Xin chào <strong>Department Lead Đ&#224;o tạo HN</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">IC Staff Leader H&#224; Nội gửi tới phòng ban của bạn một yêu cầu hậu cần phục vụ công tác tiếp khách.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Xe điện</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Loại</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Xe / Di chuyển</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Số lượng</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">5</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu sử dụng</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">09:00 20/08/2026</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kết thúc sử dụng</td><td style="padding:10px 14px;font-weight:600;color:#334155">10:00 20/08/2026</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Nội dung chi tiết công việc:</strong> Cho t&#244;i 5 xe</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để chúng tôi tiếp tục xử lý. Nếu cần điều chỉnh số lượng hoặc thời gian, hãy chọn thao tác trong hệ thống để gửi đề xuất thay đổi.</p></div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>IC Staff Leader H&#224; Nội</strong><br/>IC Staff — LEADER<br/>Ph&#242;ng Hợp t&#225;c Quốc tế<br/>staff.leader.hn@fpt.edu.vn</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p></div>\n    <div style="background:#f9fafb;padding:16px 32px;text-align:center">\n      <p style="color:#9ca3af;font-size:11px;margin:0">© 2026 PEMS — FPT University. Không trả lời email này.</p>\n    </div>\n  </div>\n</body></html>', 'HTML', NULL, NULL, 0, '2026-08-13 21:30:08', NULL, 'SENT', NULL, 3, '2026-08-13 21:30:08', '2026-08-13 21:30:08'),
	(99063, 70025, 'LOGISTICS_ITEM', 99013, '[PEMS] Đề xuất thay đổi hạng mục hậu cần: Xe điện', '<!DOCTYPE html>\n<html lang="vi"><head><meta charset="UTF-8"></head>\n<body style="font-family:Arial,sans-serif;background:#f4f6f9;margin:0;padding:20px">\n  <div style="max-width:560px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08)">\n    <div style="background:linear-gradient(135deg,#004c91,#013565);padding:28px 32px">\n      <h1 style="color:#fff;margin:0;font-size:22px">PEMS — Campus Visit</h1>\n      <p style="color:#b3c8e8;margin:6px 0 0;font-size:13px">FPT University</p>\n    </div>\n    <div style="padding:32px;color:#374151;font-size:14px"><p style="margin:0 0 16px;color:#334155">Xin chào <strong>IC Staff Leader H&#224; Nội</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">Phòng Ph&#242;ng Đ&#224;o tạo đề xuất điều chỉnh một hạng mục hậu cần của đoàn HARVARD BUSINESS SCHOOL.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Xe điện</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Số lượng ban đầu</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">5</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Số lượng đề xuất</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">2</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu sử dụng đề xuất</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">09:00 20/08/2026</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kết thúc sử dụng đề xuất</td><td style="padding:10px 14px;font-weight:600;color:#334155">09:15 20/08/2026</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Mô tả đề xuất:</strong> hehe</p><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Lý do đề xuất:</strong> duy khoai to</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới. Nếu bạn chấp nhận, hạng mục sẽ được cập nhật theo nội dung đề xuất.</p></div><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>Department Lead Đ&#224;o tạo HN</strong><br/>Department Personnel — LEADER<br/>Ph&#242;ng Đ&#224;o tạo<br/>dept.leader.hn@fpt.edu.vn</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p></div>\n    <div style="background:#f9fafb;padding:16px 32px;text-align:center">\n      <p style="color:#9ca3af;font-size:11px;margin:0">© 2026 PEMS — FPT University. Không trả lời email này.</p>\n    </div>\n  </div>\n</body></html>', 'HTML', NULL, NULL, 0, '2026-08-13 21:31:55', NULL, 'SENT', NULL, 5, '2026-08-13 21:31:55', '2026-08-13 21:31:54'),
	(99064, NULL, 'VISIT_INSTANCE', 47129, '[PEMS] Cập nhật công tác chuẩn bị đón đoàn HARVARD BUSINESS SCHOOL', '<p style="margin: 0 0 16px; color: #334155">Kính gửi Quý vị,</p><p style="margin: 0 0 14px; color: #334155; line-height: 1.65">Chúng tôi xin gửi tới Quý vị thông tin cập nhật về công tác chuẩn bị đón đoàn HARVARD BUSINESS SCHOOL tại FPT University Hà Nội.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse: collapse; width: 100%; margin: 18px 0; border: 1px solid #dbe4ee; border-radius: 8px"><tbody><tr><td style="padding: 10px 14px; color: #64748b; width: 34%; border-bottom: 1px solid #e5e7eb">Đoàn khách</td><td style="padding: 10px 14px; font-weight: 600; color: #334155; border-bottom: 1px solid #e5e7eb">HARVARD BUSINESS SCHOOL</td></tr><tr><td style="padding: 10px 14px; color: #64748b; width: 34%; border-bottom: 1px solid #e5e7eb">Bắt đầu</td><td style="padding: 10px 14px; font-weight: 600; color: #334155; border-bottom: 1px solid #e5e7eb">09:00 20/08/2026</td></tr><tr><td style="padding: 10px 14px; color: #64748b; width: 34%; border-bottom: 1px solid #e5e7eb">Kết thúc</td><td style="padding: 10px 14px; font-weight: 600; color: #334155; border-bottom: 1px solid #e5e7eb">10:00 20/08/2026</td></tr><tr><td style="padding: 10px 14px; color: #64748b; width: 34%; border-bottom: 1px solid #e5e7eb">Cơ sở</td><td style="padding: 10px 14px; font-weight: 600; color: #334155; border-bottom: 1px solid #e5e7eb">FPT University Hà Nội</td></tr><tr><td style="padding: 10px 14px; color: #64748b; width: 34%">Đầu mối phía FPT</td><td style="padding: 10px 14px; font-weight: 600; color: #334155">IC Staff Leader Hà Nội</td></tr></tbody></table><h3 style="font-size: 14px; margin: 18px 0 6px; color: #004c91">1. Thông tin chung</h3><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="border-collapse: collapse; width: 100%; table-layout: fixed; font-size: 13px; border: 1px solid #374151"><colgroup><c