	(99120, 70017, 'VISIT_PARTICIPANT', 99541, '[PEMS] Mời tham gia hỗ trợ tiếp đón đoàn Đại học FPT', '<!DOCTYPE html>\n<html lang="vi"><head><meta charset="UTF-8"></head>\n<body style="font-family:Arial,sans-serif;background:#f4f6f9;margin:0;padding:20px">\n  <div style="max-width:560px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08)">\n    <div style="background:linear-gradient(135deg,#004c91,#013565);padding:28px 32px">\n      <h1 style="color:#fff;margin:0;font-size:22px">PEMS — Campus Visit</h1>\n      <p style="color:#b3c8e8;margin:6px 0 0;font-size:13px">FPT University</p>\n    </div>\n    <div style="padding:32px;color:#374151;font-size:14px"><p style="margin:0 0 16px;color:#334155">Xin chào <strong>IC Host Protocol HN</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">IC Staff H&#224; Nội mời bạn tham gia hỗ trợ một chuyến tiếp khách tại FPT University H&#224; Nội.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Đại học FPT</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">09:00 31/08/2026 - 10:00 31/08/2026</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">FPT University H&#224; Nội</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Vai trò của bạn</td><td style="padding:10px 14px;font-weight:600;color:#334155">Staff hỗ trợ IC</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em></em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để chúng tôi chốt danh sách nhân sự tham gia.</p></div><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Liên kết phản hồi sẽ hết hạn sau 14 ngày và chỉ sử dụng được một lần.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>IC Staff H&#224; Nội</strong><br/>IC Staff — STAFF<br/>Ph&#242;ng Hợp t&#225;c Quốc tế<br/>staff.hn@fpt.edu.vn</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p></div>\n    <div style="background:#f9fafb;padding:16px 32px;text-align:center">\n      <p style="color:#9ca3af;font-size:11px;margin:0">© 2026 PEMS — FPT University. Không trả lời email này.</p>\n    </div>\n  </div>\n</body></html>', 'HTML', NULL, NULL, 0, '2026-08-25 01:01:45', NULL, 'SENT', NULL, 4, '2026-08-25 01:01:45', '2026-08-25 01:01:45'),
	(99121, 70018, 'VISIT_PARTICIPANT', 99542, '[PEMS] Mời sinh viên hỗ trợ tiếp đón đoàn Đại học FPT', '<!DOCTYPE html>\n<html lang="vi"><head><meta charset="UTF-8"></head>\n<body style="font-family:Arial,sans-serif;background:#f4f6f9;margin:0;padding:20px">\n  <div style="max-width:560px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08)">\n    <div style="background:linear-gradient(135deg,#004c91,#013565);padding:28px 32px">\n      <h1 style="color:#fff;margin:0;font-size:22px">PEMS — Campus Visit</h1>\n      <p style="color:#b3c8e8;margin:6px 0 0;font-size:13px">FPT University</p>\n    </div>\n    <div style="padding:32px;color:#374151;font-size:14px"><p style="margin:0 0 16px;color:#334155">Xin chào <strong>Student Buddy H&#224; Nội</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">IC Staff H&#224; Nội mời bạn tham gia hỗ trợ một chuyến tiếp khách tại FPT University H&#224; Nội. Đây là hoạt động tự nguyện dành cho sinh viên.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Đoàn khách</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Đại học FPT</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Thời gian dự kiến</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">09:00 31/08/2026 - 10:00 31/08/2026</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Cơ sở</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">FPT University H&#224; Nội</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Vai trò của bạn</td><td style="padding:10px 14px;font-weight:600;color:#334155">Sinh vi&#234;n hỗ trợ</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><em></em></p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới. Nếu bạn nhận lời, thông tin tập trung và hướng dẫn chi tiết sẽ được gửi trước ngày diễn ra.</p></div><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Liên kết phản hồi sẽ hết hạn sau 14 ngày và chỉ sử dụng được một lần.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>IC Staff H&#224; Nội</strong><br/>IC Staff — STAFF<br/>Ph&#242;ng Hợp t&#225;c Quốc tế<br/>staff.hn@fpt.edu.vn</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p></div>\n    <div style="background:#f9fafb;padding:16px 32px;text-align:center">\n      <p style="color:#9ca3af;font-size:11px;margin:0">© 2026 PEMS — FPT University. Không trả lời email này.</p>\n    </div>\n  </div>\n</body></html>', 'HTML', NULL, NULL, 0, '2026-08-25 01:02:00', NULL, 'SENT', NULL, 4, '2026-08-25 01:02:00', '2026-08-25 01:02:00'),
	(99122, 70023, 'LOGISTICS_ITEM', 99022, '[PEMS] Yêu cầu hậu cần: Welcome LED', '<!DOCTYPE html>\n<html lang="vi"><head><meta charset="UTF-8"></head>\n<body style="font-family:Arial,sans-serif;background:#f4f6f9;margin:0;padding:20px">\n  <div style="max-width:560px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08)">\n    <div style="background:linear-gradient(135deg,#004c91,#013565);padding:28px 32px">\n      <h1 style="color:#fff;margin:0;font-size:22px">PEMS — Campus Visit</h1>\n      <p style="color:#b3c8e8;margin:6px 0 0;font-size:13px">FPT University</p>\n    </div>\n    <div style="padding:32px;color:#374151;font-size:14px"><p style="margin:0 0 16px;color:#334155">Xin chào <strong>IT Lead HN</strong>,</p><p style="margin:0 0 14px;color:#334155;line-height:1.65">IC Staff H&#224; Nội gửi tới phòng ban của bạn một yêu cầu hậu cần phục vụ công tác tiếp khách.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;width:100%;margin:18px 0;border:1px solid #dbe4ee;border-radius:8px"><tbody><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Hạng mục</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">Welcome LED</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Loại</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">M&#224;n h&#236;nh LED</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Số lượng</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">1</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%;border-bottom:1px solid #e5e7eb">Bắt đầu sử dụng</td><td style="padding:10px 14px;font-weight:600;color:#334155;border-bottom:1px solid #e5e7eb">09:00 05/09/2026</td></tr><tr><td style="padding:10px 14px;color:#64748b;width:34%">Kết thúc sử dụng</td><td style="padding:10px 14px;font-weight:600;color:#334155">10:00 06/09/2026</td></tr></tbody></table><p style="margin:0 0 14px;color:#334155;line-height:1.65"><strong>Nội dung chi tiết công việc:</strong> Chưa c&#243; m&#244; tả chi tiết.</p><div style="margin:20px 0;padding:16px 18px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px"><p style="margin:0 0 12px;font-weight:700;color:#0f3d67">Cần bạn phản hồi</p><p style="margin:0 0 14px;color:#334155;line-height:1.6">Vui lòng chọn một phương án bên dưới để chúng tôi tiếp tục xử lý. Nếu cần điều chỉnh số lượng hoặc thời gian, hãy chọn thao tác trong hệ thống để gửi đề xuất thay đổi.</p></div><p style="margin:0 0 12px;color:#64748b;font-size:12px;line-height:1.6">Đồng ý / Từ chối là thao tác trực tiếp, không yêu cầu đăng nhập. Hành động khác (như gán nhân sự, thảo luận thêm) yêu cầu đăng nhập hệ thống. Liên kết phản hồi trực tiếp sẽ hết hạn sau 14 ngày và chỉ sử dụng được một lần.</p><div style="margin:20px 0 0;padding:14px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px"><p style="margin:0 0 8px;font-size:12px;font-weight:700;color:#475569">Thông tin người gửi</p><p style="margin:0;line-height:1.65;color:#334155"><strong>IC Staff H&#224; Nội</strong><br/>IC Staff — STAFF<br/>Ph&#242;ng Hợp t&#225;c Quốc tế<br/>staff.hn@fpt.edu.vn</p></div><p style="margin:22px 0 0;color:#64748b;font-size:12px;line-height:1.6">Trân trọng,<br/><strong>PEMS - FPT University</strong></p></div>\n    <div style="background:#f9fafb;padding:16px 32px;text-align:center">\n      <p style="color:#9ca3af;font-size:11px;margin:0">© 2026 PEMS — FPT University. Không trả lời email này.</p>\n    </div>\n  </div>\n</body></html>', 'HTML', NULL, NULL, 0, '2026-08-25 01:03:33', NULL, 'SENT', NULL, 4, '2026-08-25 01:03:33', '2026-08-25 01:03:33'),
	(99123, NULL, 'VISIT_INSTANCE', 47148, '[PEMS] Cập nhật công tác chuẩn bị đón đoàn Đại học FPT', '<p style="margin: 0 0 16px; color: #334155">Kính gửi Quý vị,</p><p style="margin: 0 0 14px; color: #334155; line-height: 1.65">Chúng tôi xin gửi tới Quý vị thông tin cập nhật về công tác chuẩn bị đón đoàn Đại học FPT tại FPT University Hà Nội.</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse: collapse; width: 100%; margin: 18px 0; border: 1px solid #dbe4ee; border-radius: 8px"><tbody><tr><td style="padding: 10px 14px; color: #64748b; width: 34%; border-bottom: 1px solid #e5e7eb">Đoàn khách</td><td style="padding: 10px 14px; font-weight: 600; color: #334155; border-bottom: 1px solid #e5e7eb">Đại học FPT</td></tr><tr><td style="padding: 10px 14px; color: #64748b; width: 34%; border-bottom: 1px solid #e5e7eb">Bắt đầu</td><td style="padding: 10px 14px; font-weight: 600; color: #334155; border-bottom: 1px solid #e5e7eb">09:00 31/08/2026</td></tr><tr><td style="padding: 10px 14px; color: #64748b; width: 34%; border-bottom: 1px solid #e5e7eb">Kết thúc</td><td style="padding: 10px 14px; font-weight: 600; color: #334155; border-bottom: 1px solid #e5e7eb">10:00 31/08/2026</td></tr><tr><td style="padding: 10px 14px; color: #64748b; width: 34%; border-bottom: 1px solid #e5e7eb">Cơ sở</td><td style="padding: 10px 14px; font-weight: 600; color: #334155; border-bottom: 1px solid #e5e7eb">FPT University Hà Nội</td></tr><tr><td style="padding: 10px 14px; color: #64748b; width: 34%">Đầu mối phía FPT</td><td style="padding: 10px 14px; font-weight: 600; color: #334155">IC Staff Hà Nội</td></tr></tbody></table><h3 style="font-size: 14px; margin: 18px 0 6px; color: #004c91">1. Thông tin chung</h3><table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="border-collapse: collapse; width: 100%; table-layout: fixed; font-size: 13px; border: 1px solid #374151"><colgroup><col style="width: 34%" width="34%"><col styl