	(45001, 42002, 1, 'Đón đoàn British Council Digital Skills Roundtable', 'Host xác nhận thành phần của British Council Digital Skills Roundtable, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Chuẩn bị chương trình kỹ năng số cho sinh viên và cơ chế đồng tổ chức hoạt động tại campus Hà Nội.', '2026-08-22 09:00:00', '2026-08-22 09:30:00', 'Alpha Building - FPTU Hà Nội', 3, NULL, NULL, '2026-08-04 17:06:10', 3, NULL, NULL),
	(45002, 42002, 2, 'Phiên làm việc chuyên môn với British Council Digital Skills Roundtable', 'Hai bên thống nhất phạm vi workshop, tiêu chí lựa chọn giảng viên, phương án truyền thông và mốc rà soát nội dung trước ngày tổ chức. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', '2026-08-22 09:30:00', '2026-08-22 11:30:00', 'Alpha Building - FPTU Hà Nội', 3, NULL, NULL, '2026-08-04 17:06:10', 3, NULL, NULL),
	(45003, 42003, 1, 'Đón đoàn Osaka AI Laboratories Academic Visit', 'Host xác nhận thành phần của Osaka AI Laboratories Academic Visit, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Khảo sát phòng lab trí tuệ nhân tạo và thảo luận cơ hội đồng hướng dẫn đồ án sinh viên.', '2026-08-11 09:00:00', '2026-08-11 09:30:00', 'Alpha Building - FPTU Hà Nội', 3, NULL, NULL, '2026-08-03 17:06:10', 3, NULL, NULL),
	(45004, 42003, 2, 'Phiên làm việc chuyên môn với Osaka AI Laboratories Academic Visit', 'Đoàn tham quan AI Lab, gặp nhóm giảng viên phụ trách computer vision và rà soát đề cương ba đề tài có thể triển khai trong năm học tới. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', '2026-08-11 09:30:00', '2026-08-11 11:30:00', 'Alpha Building - FPTU Hà Nội', 3, NULL, NULL, '2026-08-03 17:06:10', 3, NULL, NULL),
	(45005, 42004, 1, 'Đón đoàn Korea Foundation Culture Exchange Mission', 'Host xác nhận thành phần của Korea Foundation Culture Exchange Mission, giới thiệu đầu mối campus Hà Nội và thống nhất mục tiêu: Tổ chức phiên giao lưu văn hóa Hàn Quốc - Việt Nam và trao đổi kế hoạch học kỳ trải nghiệm.', '2026-08-08 09:00:00', '2026-08-08 09:30:00', 'Alpha Building - FPTU Hà Nội', 3, NULL, NULL, '2026-08-02 17:06:10', 3, NULL, NULL),
	(45006, 42004, 2, 'Phiên làm việc chuyên môn với Korea Foundation Culture Exchange Mission', 'Chương trình gồm giới thiệu campus, đối thoại sinh viên, trình diễn văn hóa và phiên làm việc riêng về chương trình mobility ngắn hạn. Cuối phiên, hai bên ghi nhận đầu việc, người phụ trách và thời hạn phản hồi.', '2026-08-08 09:30:00', '2026-08-08 11:30:00', 'Alpha Building - FPTU Hà Nội', 3, NULL, NULL, '2026-08-02 17:06:10', 3, NULL, NULL),
