INSERT INTO `visit_instance_form_details` (`visit_instance_id`, `delegation_name`, `visit_type`, `visit_type_other`, `purpose`, `working_content`, `operational_contact_full_name`, `operational_contact_organization`, `operational_contact_job_title`, `operational_contact_phone`, `operational_contact_email`, `operational_contact_guest_member_id`, `working_language`, `transportation_note`, `media_consent_status`, `notes`, `form_revision`, `approval_revision`, `row_version`, `created_at`, `created_by`, `updated_at`, `updated_by`) VALUES
	(3001, 'SeoulTech smart campus discovery visit', 'CAMPUS_TOUR', NULL, 'Khảo sát không gian học tập thông minh, phương án hỗ trợ sinh viên quốc tế và cách FPTU tổ chức tour học thuật cho đối tác công nghệ.', 'Tour thư viện, phòng lab AI, khu trải nghiệm sinh viên; meeting ngắn với IC về quy trình tiếp nhận đoàn và trao đổi follow-up bằng email.', 'Kim Min Jae', 'SeoulTech Global Engagement Center', 'International Partnerships Manager', '+821012340001', 'kim.minjae@seoultech.example', 1, 'EN', 'Khách tự túc phương tiện. Xe riêng của đoàn, đến cổng chính Hòa Lạc.', 'AGREED', 'Đoàn có hai thành viên lớn tuổi, mong FPTU bố trí chỗ nghỉ ngắn giữa các điểm tham quan.', 1, 1, 0, '2026-06-23 08:00:00', 8, '2026-08-14 17:07:23', NULL),
	(3002, 'Kyoto service robotics lab showcase request', 'WORKSHOP', NULL, 'Đề xuất một phiên demo robot dịch vụ cho sinh viên, kiểm tra mức sẵn sàng của phòng lab và quy trình an toàn thiết bị trước khi chốt workshop chính thức.', 'Cần phòng lab có khu vực an toàn, bàn demo, nguồn điện dự phòng và người phụ trách kỹ thuật; nếu không đáp ứng thì nên từ chối sớm.', 'Tanaka Aoi', 'Kyoto Robotics Collaboration Lab', 'Partnership Manager', '+819012345678', 'aoi.tanaka@kyoto-global.example', NULL, 'EN', 'Khách đề nghị FPTU hỗ trợ phương tiện. Yêu cầu hỗ trợ xe điện nội khu nếu có.', 'DECLINED', NULL, 1, 1, 0, '2026-06-10 08:30:00', 21, NULL, NULL),
	(3003, 'SeoulTech AI curriculum articulation briefing', 'MEETING', NULL, 'Làm việc với IC và đại diện đào tạo để đối chiếu cấu trúc chương trình AI, chuẩn tín chỉ và điều kiện trao đổi học kỳ ngắn.', 'Trao đổi syllabus, mapping tín chỉ, tiêu chí chọn sinh viên, yêu cầu tiếng Anh và mốc thời gian mở đợt trao đổi đầu tiên.', 'Lee Joon Ho', 'SeoulTech School of Computing', 'Associate Professor', '+821055512345', 'lee.joonho@seoultech.example', NULL, 'EN', 'Khách tự túc phương tiện. Đoàn tự di chuyển bằng xe 16 chỗ.', 'AGREED', 'Đoàn xin nhận trước slide chương trình đào tạo AI để chuẩn bị câu hỏi.', 1, 1, 0, '2026-06-12 09:00:00', 20, NULL, NULL),
	(3004, 'Green campus preparation visit', 'CAMPUS_TOUR', NULL, 'Khảo sát không gian campus xanh và cách FPTU vận hành xe điện nội khu.', 'Đoàn cần lộ trình tour ngoài trời, điểm dừng tại bãi xe điện và trao đổi với facilities.', 'Emily Smith', 'Singapore Green Mobility Council', 'Policy Liaison', '+6591234567', 'emily.smith@greentech.example', 8, 'EN', 'Khách đề nghị FPTU hỗ trợ phương tiện. Cần FPTU hỗ trợ xe điện nội khu cho 6 khách.', 'AGREED', NULL, 1, 1, 0, '2026-06-13 09:00:00', 22, '2026-08-14 17:07:23', NULL),
	(3005, 'Iberia Mobility Forum campus day', 'EXCHANGE', NULL, 'Tổ chức một ngày giao lưu về mobility, startup và vai trò sinh viên trong dự án xanh.', 'Phiên sáng tham quan, phiên chiều roundtable với sinh viên và IC.', 'Maya Rodriguez', 'Iberia Mobility Forum', 'Program Curator', '+34911222333', 'maya.rodriguez@iberia-mobility.example', 10, 'EN', 'Phương tiện khác. Đoàn có xe thuê riêng, FPTU hỗ trợ điều phối bãi đỗ.', 'AGREED', 'Đoàn cần phiên dịch Anh - Việt cho phiên thảo luận buổi chiều.', 1, 1, 0, '2026-06-14 09:00:00', 23, '2026-08-14 17:07:23', NULL),
	(3006, 'SeoulTech AI lab follow-up discussion', 'MEETING', NULL, 'Làm rõ các đầu việc hợp tác AI lab sau chuyến tham quan đầu tiên.', 'Đoàn tập trung vào biên bản ghi nhớ, action items và đầu mối từng bên.', 'Kim Min Jae', 'SeoulTech Global Engagement Center', 'International Partnerships Manager', '+821012340001', 'kim.minjae@seoultech.example', 12, 'EN', 'Khách tự túc phương tiện. Taxi từ khách sạn đến campus.', 'DECLINED', NULL, 1, 1, 0, '2026-06-05 08:45:00', 8, '2026-08-14 17:07:23', NULL),
	(3007, 'Porto AI Hub closed delegation', 'SIGNING_CEREMONY', NULL, 'Ký biên bản hợp tác ngắn hạn về seminar AI ứng dụng và trao đổi lecturer.', 'Sự kiện đã kết thúc, biên bản và báo cáo dịch vụ đã được lưu.', 'Carlos Mendes', 'Porto Applied AI Hub', 'Research Partnership Lead', '+351211234567', 'carlos.mendes@porto-ai.example', NULL, 'EN', 'Khách đề nghị FPTU hỗ trợ phương tiện. FPTU bố trí xe từ khách sạn và trả đoàn tại sân bay.', 'AGREED', 'Buổi làm việc kín, đề nghị FPTU không đưa tin trước khi hai bên thống nhất.', 1, 1, 0, '2026-05-20 08:00:00', 24, NULL, NULL),
