	(191, 9001, 9901, 1, 1, 'CREATE', NULL, '{"notes": null, "purpose": "Đoàn khách hủy chặng Hà Nội do visa cấp chậm; campus chưa phát sinh người phụ trách tiếp đón.", "visitType": "MEETING", "delegationName": "Visitor cancelled Hanoi-only campus tour due to visa delay", "visitTypeOther": null, "workingContent": "Không tổ chức onsite; staff chỉ lưu lại lý do hủy, lịch dự kiến và đề xuất mở lại request khi visa hoàn tất.", "workingLanguage": "EN", "mediaConsentStatus": "AGREED", "operationalContact": {"email": "sofia.bianchi@polimi.example", "phone": "+390210000202", "fullName": "Sofia Bianchi", "jobTitle": "Mobility Research Programme Manager", "organization": "Politecnico di Milano Mobility Lab"}, "transportationNote": "Khách tự túc phương tiện. Đoàn tự bố trí xe từ trung tâm TP.HCM đến campus."}', 202, '2026-07-27 17:04:46', 'Fresh-create Per-Campus Form V2 baseline'),
	(192, 9002, 9902, 1, 1, 'CREATE', NULL, '{"notes": null, "purpose": "Đối tác đổi lịch họp hội đồng quản trị nên người đăng ký hủy yêu cầu sau khi campus đã được duyệt.", "visitType": "WORKSHOP", "delegationName": "Visitor cancelled HCM workshop after partner board reschedule", "visitTypeOther": null, "workingContent": "Không triển khai logistics; cần thông báo department đã nhận lịch để tránh chuẩn bị thừa.", "workingLanguage": "EN", "mediaConsentStatus": "DECLINED", "operationalContact": {"email": "kelly.nguyen@uts.example", "phone": "+61410000203", "fullName": "Nguyen Kelly", "jobTitle": "Student Exchange Coordinator", "organization": "University of Technology Sydney Student Exchange"}, "transportationNote": "Khách đề nghị FPTU hỗ trợ phương tiện. Đề nghị campus hỗ trợ xe điện nội khu và bảng welcome."}', 203, '2026-07-27 17:04:46', 'Fresh-create Per-Campus Form V2 baseline'),
	(193, 9003, 9903, 1, 1, 'CREATE', NULL, '{"notes": "Đoàn xin xác nhận lại lịch trước một tuần vì phải đặt vé nội địa.", "purpose": "Staff Leader từ chối vì request multi-campus thiếu campus objective riêng và không đủ ngày chuẩn bị logistics liên cơ sở.", "visitType": "EXCHANGE", "delegationName": "Multi-campus request rejected because agenda scope was incomplete", "visitTypeOther": null, "workingContent": "Staff Leader của từng campus yêu cầu bổ sung agenda riêng, danh sách khách chính thức và thư xác nhận thời gian làm việc trước khi xem xét lại.", "workingLanguage": "EN", "mediaConsentStatus": "AGREED", "operationalContact": {"email": "priya.raman@singapore-ai.example", "phone": "+6590000210", "fullName": "Priya Raman", "jobTitle": "Applied AI Programme Director", "organization": "Singapore Applied AI Consortium"}, "transportationNote": "Phương tiện khác. Đoàn dự kiến kết hợp xe thuê và boat tour nội vùng."}', 210, '2026-07-27 17:04:46', 'Fresh-create Per-Campus Form V2 baseline'),
	(194, 9004, 9904, 1, 1, 'CREATE', NULL, '{"notes": null, "purpose": "Staff Leader từng campus đã xử lý request tổng, các campus đang chờ Staff Leader approve và gán host và chuẩn bị agenda riêng.", "visitType": "CAMPUS_TOUR", "delegationName": "Multi-campus approved but pending host assignment across campuses", "visitTypeOther": null, "workingContent": "Staff Leader từng campus cần gán host, xác nhận phòng họp và gửi lời mời department support trước hạn 5 ngày.", "workingLanguage": "EN", "mediaConsentStatus": "DECLINED", "operationalContact": {"email": "fatima.zahra@casablanca-tech.example", "phone": "+21260000212", "fullName": "Fatima Zahra", "jobTitle": "International Cooperation Manager", "organization": "Casablanca Institute of Technology Partnerships"}, "transportationNote": "Khách tự túc phương tiện. Đoàn tự đặt shuttle từ sân bay Phù Cát."}', 212, '2026-07-27 17:04:46', 'Fresh-create Per-Campus Form V2 baseline'),
	(195, 9005, 9905, 1, 1, 'CREATE', NULL, '{"notes": "Đoàn có nhu cầu suất ăn chay cho ba thành viên.", "purpose": "Đoàn đang triển khai reception ở nhiều campus với trách nhiệm host, department support và logistics tách theo từng instance.", "visitType": "CAMPUS_TOUR", "delegationName": "Multi-campus active reception with split campus responsibilities", "visitTypeOther": null, "workingContent": "Campus HN đang tiếp đoàn, campus HCM chuẩn bị phiên sau; logistics và minutes được theo dõi riêng từng instance.", "workingLanguage": "EN", "mediaConsentStatus": "AGREED", "operationalContact": {"email": "amelie.dubois@paris-digital.example", "phone": "+33144000205", "fullName": "Amelie Dubois", "jobTitle": "International Programme Curator", "organization": "Paris Digital Arts Institute"}, "transportationNote": "Khách đề nghị FPTU hỗ trợ phương tiện. Cần FPTU hỗ trợ điều phối di chuyển giữa các campus nếu lịch được chốt."}', 205, '2026-07-27 17:04:46', 'Fresh-create Per-Campus Form V2 baseline'),
