	(46032, 47012, 47122, 1, 1, 'CREATE', NULL, '{"notes": "không có gì", "members": [{"fullName": "Truong D Nguyen (Patrick)", "jobTitle": "Managing Director", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 1, "organization": "UK CENTRE"}, {"fullName": "Nguyễn Minh Trí", "jobTitle": "Phó Giám đốc", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 2, "organization": "UK CENTRE"}, {"fullName": "Nguyen Hong Thu", "jobTitle": "HR-Admin Manager", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 3, "organization": "MEDIA MAX JAPAN (VIET NAM) CO., LTD"}, {"fullName": "Kenji Sato", "jobTitle": "Giám đốc Kỹ thuật (CTO)", "memberType": "GUEST", "nationality": "Nhật Bản", "displayOrder": 4, "organization": "MEDIA MAX JAPAN (VIET NAM) CO., LTD"}, {"fullName": "Ngô Phương Thảo", "jobTitle": "Trưởng phòng Thiết kế", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 5, "organization": "MEDIA MAX JAPAN (VIET NAM) CO., LTD"}, {"fullName": "Trịnh Hoài Nam", "jobTitle": "Kỹ sư Phần mềm Trưởng", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 6, "organization": "MEDIA MAX JAPAN (VIET NAM) CO., LTD"}, {"fullName": "Min-soo Kim", "jobTitle": "Chuyên viên Kiểm thử (QA)", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 7, "organization": "MEDIA MAX JAPAN (VIET NAM) CO., LTD"}, {"fullName": "Morgan Maxwell", "jobTitle": "Graphic Designer", "memberType": "GUEST", "nationality": "Anh", "displayOrder": 8, "organization": "WARNER & SPENCER"}, {"fullName": "Nguyễn Khánh Linh", "jobTitle": "Giám đốc Chi nhánh", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 9, "organization": "WARNER & SPENCER"}, {"fullName": "David Miller", "jobTitle": "Cố vấn Tài chính Quốc tế", "memberType": "GUEST", "nationality": "Mỹ", "displayOrder": 10, "organization": "WARNER & SPENCER"}, {"fullName": "Lương Văn Tuấn", "jobTitle": "Trưởng phòng Tín dụng", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 11, "organization": "WARNER & SPENCER"}], "purpose": "Tham quan FPT University Hà Nội nhằm tìm hiểu mô hình đào tạo gắn với doanh nghiệp, cơ sở vật chất giảng dạy, nghiên cứu và hệ sinh thái đổi mới sáng tạo. Chuyến thăm tập trung trao đổi về chương trình đào tạo vi mạch, bán dẫn, trí tuệ nhân tạo, cơ hội phối hợp xây dựng học phần, tổ chức hội thảo và trao đổi học thuật. Hai bên thảo luận dự án nghiên cứu chung, thực tập, chuyển giao công nghệ và phát triển quan hệ hợp tác lâu dài trong tương lai gần.", "visitType": "MEETING", "delegationName": "YUAN ZE UNIVERSITY ĐẾN THAM QUAN VÀ LÀM VIỆC", "visitTypeOther": null, "workingContent": "Buổi họp tập trung trao đổi về chương trình sinh viên giữa FPT University và Đoàn Kyoto International University, gồm điều kiện tham gia, tiêu chí tuyển chọn, thời gian học tập và số lượng sinh viên. Hai bên thảo luận cơ chế công nhận tín chỉ, quy đổi kết quả học tập, học phí, học bổng, chỗ ở, bảo hiểm và hỗ trợ thị thực. Đại diện hai trường thống nhất xây dựng danh sách học phần tương đương, lịch học và đầu mối phụ trách. Nội dung cũng đề cập chương trình định hướng trước khi khởi hành, hỗ trợ sinh viên quốc tế trong thời gian học, hoạt động giao lưu văn hóa và xử lý tình huống phát sinh. Cuối buổi, hai bên dự kiến lập kế hoạch thử nghiệm, xác định mốc thời gian, trách nhiệm phối hợp và tiêu chí đánh giá toàn diện hiệu quả chương trình.", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "thoaitop@gmail.com", "operationalContactPhone": null, "operationalContactFullName": "Nguyên Ly Hao", "operationalContactOrganization": "YUAN ZE UNIVERSITY"}', 231, '2026-08-08 22:44:18', NULL),
