	(46041, 47018, 47129, 1, 1, 'CREATE', NULL, '{"notes": null, "members": [{"fullName": "Truong D Nguyen (Patrick)", "jobTitle": "Managing Director", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 1, "organization": "HARVARD BUSINESS SCHOOL"}, {"fullName": "Nguyễn Minh Trí", "jobTitle": "Phó Giám đốc", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 2, "organization": "UK CENTRE"}, {"fullName": "Trần Thị Hồng Vân", "jobTitle": "Trưởng phòng Đào tạo", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 3, "organization": "UK CENTRE"}, {"fullName": "Nguyen Hong Thu", "jobTitle": "HR-Admin Manager", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 4, "organization": "MEDIA MAX JAPAN (VIET NAM) CO., LTD"}, {"fullName": "Kenji Sato", "jobTitle": "Giám đốc Kỹ thuật (CTO)", "memberType": "GUEST", "nationality": "Nhật Bản", "displayOrder": 5, "organization": "MEDIA MAX JAPAN (VIET NAM) CO., LTD"}, {"fullName": "Ngô Phương Thảo", "jobTitle": "Trưởng phòng Thiết kế", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 6, "organization": "MEDIA MAX JAPAN (VIET NAM) CO., LTD"}, {"fullName": "Trịnh Hoài Nam", "jobTitle": "Kỹ sư Phần mềm Trưởng", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 7, "organization": "MEDIA MAX JAPAN (VIET NAM) CO., LTD"}, {"fullName": "Min-soo Kim", "jobTitle": "Chuyên viên Kiểm thử (QA)", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 8, "organization": "MEDIA MAX JAPAN (VIET NAM) CO., LTD"}, {"fullName": "Morgan Maxwell", "jobTitle": "Graphic Designer", "memberType": "GUEST", "nationality": "Anh", "displayOrder": 9, "organization": "HARVARD BUSINESS SCHOOL"}, {"fullName": "Nguyễn Khánh Linh", "jobTitle": "Giám đốc Chi nhánh", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 10, "organization": "HARVARD BUSINESS SCHOOL"}, {"fullName": "David Miller", "jobTitle": "Cố vấn Tài chính Quốc tế", "memberType": "GUEST", "nationality": "Mỹ", "displayOrder": 11, "organization": "HARVARD BUSINESS SCHOOL"}, {"fullName": "Lương Văn Tuấn", "jobTitle": "Trưởng phòng Tín dụng", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 12, "organization": "HARVARD BUSINESS SCHOOL"}], "purpose": "Trong khuôn khổ chương trình, đoàn đại biểu đã tham quan cơ sở vật chất, tìm hiểu về mô hình đào tạo, môi trường học tập và hệ sinh thái giáo dục của FPT. Đồng thời, hai bên đã có những trao đổi xoay quanh hành trình chuyển đổi AI của FPT, từ chiến lược phát triển, ứng dụng công nghệ đến tầm nhìn xây dựng hệ sinh thái trí tuệ nhân tạo phục vụ giáo dục, doanh nghiệp và xã hội.", "visitType": "SIGNING_CEREMONY", "plannedEndAt": "2026-08-20T10:00:00", "delegationName": "HARVARD BUSINESS SCHOOL", "plannedStartAt": "2026-08-20T09:00:00", "visitTypeOther": null, "workingContent": "Trong khuôn khổ chương trình, đoàn đại biểu đã tham quan cơ sở vật chất, tìm hiểu về mô hình đào tạo, môi trường học tập và hệ sinh thái giáo dục của FPT. Đồng thời, hai bên đã có những trao đổi xoay quanh hành trình chuyển đổi AI của FPT, từ chiến lược phát triển, ứng dụng công nghệ đến tầm nhìn xây dựng hệ sinh thái trí tuệ nhân tạo phục vụ giáo dục, doanh nghiệp và xã hội.", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "duyflt2004@gmail.com", "operationalContactPhone": null, "operationalContactFullName": "Nguyễn ĐÌnh DUy", "operationalContactJobTitle": "Staff", "operationalContactOrganization": "HARVARD BUSINESS SCHOOL"}', 238, '2026-08-13 21:20:27', NULL),
	(46042, 47019, 47130, 1, 1, 'CREATE', NULL, '{"notes": "Kính thưa toàn thể quý cô, bác, anh, chị trong đoàn, lời đầu tiên cho phép em xin gửi lời chào thân thương và lời chúc sức khỏe đến tất cả mọi người. Chúc cho chuyến hành trình của đoàn chúng ta diễn ra trọn vẹn và nhiều niềm vui.", "members": [{"fullName": "Dr. Emily Carter", "jobTitle": "Director of Global Partnerships", "memberType": "GUEST", "nationality": "Hoa Kỳ", "displayOrder": 1, "organization": "Andes University Exchange Office (Andes Exchange)"}, {"fullName": "Mr. Daniel Kim", "jobTitle": "International Program Manager", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 2, "organization": "Andes University Exchange Office (Andes Exchange)"}, {"fullName": "Ms. Sofia Martinez", "jobTitle": "Academic Cooperation Coordinator", "memberType": "GUEST", "nationality": "Tây Ban Nha", "displayOrder": 3, "organization": "Global Education Alliance"}, {"fullName": "Prof. Liam O\'Connor", "jobTitle": "Dean of International Programs", "memberType": "GUEST", "nationality": "Ireland", "displayOrder": 4, "organization": "Dublin Institute of Technology"}, {"fullName": "Ms. Aiko Tanaka", "jobTitle": "International Student Advisor", "memberType": "GUEST", "nationality": "Nhật Bản", "displayOrder": 5, "organization": "Global Education Alliance"}, {"fullName": "Nguyễn Văn A", "jobTitle": "Giám đốc", "memberType": "EXTERNAL_SUPPORT", "nationality": "Việt Nam", "displayOrder": 6, "organization": "SeoulTech Global Engagement Center (SeoulTech GEC)"}], "purpose": "Khách đoàn (nhóm khách đi chung từ 10–12 người trở lên) thường có chung một mục đích chuyến đi được tổ chức thống nhất. Các mục đích chính bao gồm du lịch nghỉ dưỡng, công tác kết hợp hội thảo, gắn kết tập thể (team building), khen thưởng nhân sự, hoặc tham gia các sự kiện, hành hương và học tập", "visitType": "WORKSHOP", "plannedEndAt": "2026-08-26T10:00:00", "delegationName": "Đoàn Công ty TNHH Thương mại và Du lịch Á Châu", "plannedStartAt": "2026-08-26T09:00:00", "visitTypeOther": null, "workingContent": "Nội dung làm việc với một đoàn khách bất kỳ (trong du lịch hoặc đón tiếp tại cơ quan/doanh nghiệp) bao gồm: chào hỏi và giới thiệu thành phần, thống nhất lịch trình, phổ biến nội quy, điều phối dịch vụ (ăn, nghỉ, di chuyển), và lắng nghe các yêu cầu phát sinh để hỗ trợ kịp thời", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "canhnvthe186121@fpt.edu.vn", "operationalContactPhone": "+84901000003", "operationalContactFullName": "Thắng Cảnh", "operationalContactJobTitle": "Trưởng phòng", "operationalContactOrganization": "Phòng Hợp tác Quốc tế"}', 3, '2026-08-14 17:01:38', NULL),
	(46043, 47020, 47131, 1, 1, 'CREATE', NULL, '{"notes": "Đoàn mong muốn được tham quan khu giảng đường, khu thực hành và có khoảng 30 phút trao đổi với đại diện nhà trường.", "members": [{"fullName": "Nguyễn Minh Anh", "jobTitle": "Business Development Manager", "memberType": "GUEST", "nationality": "Vietnam", "displayOrder": 1, "organization": "TechVision Việt Nam"}, {"fullName": "Trần Hoàng Nam", "jobTitle": "HR Manager", "memberType": "GUEST", "nationality": "Vietnam", "displayOrder": 2, "organization": "TechVision Việt Nam"}, {"fullName": "Lê Thu Hà", "jobTitle": "Project Coordinator", "memberType": "GUEST", "nationality": "Vietnam", "displayOrder": 3, "organization": "TechVision Việt Nam"}, {"fullName": "Phạm Quốc Bảo", "jobTitle": "Interpreter", "memberType": "EXTERNAL_SUPPORT", "nationality": "Vietnam", "displayOrder": 4, "organization": "TechVision Việt Nam"}], "purpose": "Tham quan môi trường đào tạo của Đại học FPT, tìm hiểu mô hình đào tạo gắn với doanh nghiệp và trao đổi cơ hội hợp tác giữa hai đơn vị.", "visitType": "CAMPUS_TOUR", "plannedEndAt": "2026-08-20T10:00:00", "delegationName": "Đoàn tham quan TechVision Việt Nam", "plannedStartAt": "2026-08-20T09:00:00", "visitTypeOther": null, "workingContent": "Tham quan khuôn viên trường, phòng học và khu vực thực hành; giới thiệu tổng quan về Đại học FPT; trao đổi về chương trình đào tạo và các hoạt động hợp tác doanh nghiệp; thảo luận cơ hội tổ chức chương trình thực tập cho sinh viên.", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": "Đoàn di chuyển bằng xe ô tô 16 chỗ, biển số 30G-123.45.", "operationalContactEmail": "truongphuonganh049@gmail.com", "operationalContactPhone": "+84912345678", "operationalContactFullName": "Nguyễn Minh Anh", "operationalContactJobTitle": "Business Development Manager", "operationalContactOrganization": "TechVision Việt Nam"}', 241, '2026-08-15 10:43:43', NULL),
