	(46048, 47023, 47136, 1, 1, 'CREATE', NULL, '{"notes": null, "members": [{"fullName": "Shin Hiroshi", "jobTitle": "Giám đốc", "memberType": "GUEST", "nationality": "Japan", "displayOrder": 1, "organization": "Kyoto International University"}], "purpose": "Tham quan FPT University Hà Nội nhằm tìm hiểu mô hình đào tạo gắn với doanh nghiệp, cơ sở vật chất giảng dạy, nghiên cứu và hệ sinh thái đổi mới sáng tạo. Chuyến thăm tập trung trao đổi về chương trình đào tạo vi mạch, bán dẫn, trí tuệ nhân tạo, cơ hội phối hợp xây dựng học phần, tổ chức hội thảo và trao đổi học thuật. Hai bên thảo luận dự án nghiên cứu chung, thực tập, chuyển giao công nghệ và phát triển quan hệ hợp tác lâu dài trong tương lai gần.", "visitType": "CAMPUS_TOUR", "plannedEndAt": "2026-08-20T10:00:00", "delegationName": "Đoàn Kyoto International University", "plannedStartAt": "2026-08-20T09:00:00", "visitTypeOther": null, "workingContent": "Buổi họp tập trung trao đổi về chương trình sinh viên giữa FPT University và Đoàn Kyoto International University, gồm điều kiện tham gia, tiêu chí tuyển chọn, thời gian học tập và số lượng sinh viên. Hai bên thảo luận cơ chế công nhận tín chỉ, quy đổi kết quả học tập, học phí, học bổng, chỗ ở, bảo hiểm và hỗ trợ thị thực. Đại diện hai trường thống nhất xây dựng danh sách học phần tương đương, lịch học và đầu mối phụ trách. Nội dung cũng đề cập chương trình định hướng trước khi khởi hành, hỗ trợ sinh viên quốc tế trong thời gian học, hoạt động giao lưu văn hóa và xử lý tình huống phát sinh. Cuối buổi, hai bên dự kiến lập kế hoạch thử nghiệm, xác định mốc thời gian, trách nhiệm phối hợp và tiêu chí đánh giá toàn diện hiệu quả chương trình.", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "phuonganhhhh1409@gmail.com", "operationalContactPhone": null, "operationalContactFullName": "Shin Hiroshi", "operationalContactJobTitle": "Giám đốc", "operationalContactOrganization": "Kyoto International University"}', 245, '2026-08-15 11:51:21', NULL),
	(46049, 47023, 47137, 1, 1, 'CREATE', NULL, '{"notes": null, "members": [{"fullName": "Shin Hiroshi", "jobTitle": "Giám đốc", "memberType": "GUEST", "nationality": "Japan", "displayOrder": 1, "organization": "Kyoto International University"}], "purpose": "Tham quan FPT University Hà Nội nhằm tìm hiểu mô hình đào tạo gắn với doanh nghiệp, cơ sở vật chất giảng dạy, nghiên cứu và hệ sinh thái đổi mới sáng tạo. Chuyến thăm tập trung trao đổi về chương trình đào tạo vi mạch, bán dẫn, trí tuệ nhân tạo, cơ hội phối hợp xây dựng học phần, tổ chức hội thảo và trao đổi học thuật. Hai bên thảo luận dự án nghiên cứu chung, thực tập, chuyển giao công nghệ và phát triển quan hệ hợp tác lâu dài trong tương lai gần.", "visitType": "CAMPUS_TOUR", "plannedEndAt": "2026-08-28T10:00:00", "delegationName": "Đoàn Kyoto International University", "plannedStartAt": "2026-08-28T09:00:00", "visitTypeOther": null, "workingContent": "Buổi họp tập trung trao đổi về chương trình sinh viên giữa FPT University và Đoàn Kyoto International University, gồm điều kiện tham gia, tiêu chí tuyển chọn, thời gian học tập và số lượng sinh viên. Hai bên thảo luận cơ chế công nhận tín chỉ, quy đổi kết quả học tập, học phí, học bổng, chỗ ở, bảo hiểm và hỗ trợ thị thực. Đại diện hai trường thống nhất xây dựng danh sách học phần tương đương, lịch học và đầu mối phụ trách. Nội dung cũng đề cập chương trình định hướng trước khi khởi hành, hỗ trợ sinh viên quốc tế trong thời gian học, hoạt động giao lưu văn hóa và xử lý tình huống phát sinh. Cuối buổi, hai bên dự kiến lập kế hoạch thử nghiệm, xác định mốc thời gian, trách nhiệm phối hợp và tiêu chí đánh giá toàn diện hiệu quả chương trình.", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "longfb0211@gmail.com", "operationalContactPhone": null, "operationalContactFullName": "Long Nguyễn Công", "operationalContactJobTitle": "International Relations Manager", "operationalContactOrganization": "Đoàn Kyoto International University"}', 245, '2026-08-15 11:51:21', NULL),
