	(46059, 47029, 47144, 1, 1, 'CREATE', NULL, '{"notes": null, "members": [{"fullName": "ể test xác nhận người đăng kí", "jobTitle": "ể test xác nhận người đăng kí", "memberType": "GUEST", "nationality": "Saudi Arabia", "displayOrder": 1, "organization": "ể test xác nhận người đăng kí"}], "purpose": "ể test xác nhận người đăng kí", "visitType": "CAMPUS_TOUR", "plannedEndAt": "2026-08-27T10:00:00", "delegationName": "tên đoàn để test xác nhận người đăng kí", "plannedStartAt": "2026-08-27T09:00:00", "visitTypeOther": null, "workingContent": "ể test xác nhận người đăng kí", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "canhnvthe186121@fpt.edu.vn", "operationalContactPhone": null, "operationalContactFullName": "ể test xác nhận người đăng kí", "operationalContactJobTitle": "ể test xác nhận người đăng kí", "operationalContactOrganization": "ể test xác nhận người đăng kí"}', 8, '2026-08-19 03:57:14', NULL),
	(46060, 47030, 47145, 1, 1, 'CREATE', NULL, '{"notes": null, "members": [{"fullName": "MInato", "jobTitle": "Chủ tịch", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 1, "organization": "TMAXTIBERO"}, {"fullName": "Nguyễn Quang Thoại", "jobTitle": "Nhân viên", "memberType": "GUEST", "nationality": "Ấn Độ", "displayOrder": 2, "organization": "TMAXTIBERO"}], "purpose": "Trong buổi thảo luận, hai bên đã chia sẻ về khả năng triển khai các chương trình hỗ trợ học thuật, tài nguyên đào tạo, workshop chuyên môn cũng như cơ hội để sinh viên tiếp cận các nền tảng DBMS và công nghệ thực tiễn từ doanh nghiệp. \\nĐồng thời, TmaxTibero cũng giới thiệu thêm về các giải pháp cơ sở dữ liệu và hệ sinh thái công nghệ mà doanh nghiệp đang phát triển, mở ra nhiều tiềm năng hợp tác trong đào tạo, nghiên cứu và định hướng nghề nghiệp cho sinh viên ngành Công nghệ thông tin.", "visitType": "WORKSHOP", "plannedEndAt": "2026-09-19T10:00:00", "delegationName": "TMAXTIBERO", "plannedStartAt": "2026-09-19T09:00:00", "visitTypeOther": null, "workingContent": "Trong buổi thảo luận, hai bên đã chia sẻ về khả năng triển khai các chương trình hỗ trợ học thuật, tài nguyên đào tạo, workshop chuyên môn cũng như cơ hội để sinh viên tiếp cận các nền tảng DBMS và công nghệ thực tiễn từ doanh nghiệp. \\nĐồng thời, TmaxTibero cũng giới thiệu thêm về các giải pháp cơ sở dữ liệu và hệ sinh thái công nghệ mà doanh nghiệp đang phát triển, mở ra nhiều tiềm năng hợp tác trong đào tạo, nghiên cứu và định hướng nghề nghiệp cho sinh viên ngành Công nghệ thông tin.", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "nguyenquangthoai04@gmail.com", "operationalContactPhone": "+84967368980", "operationalContactFullName": "Nguyễn Quang Thoại", "operationalContactJobTitle": "Nhân viên", "operationalContactOrganization": "TMAXTIBERO"}', 238, '2026-08-21 20:39:47', NULL),
	(46061, 47031, 47146, 1, 1, 'CREATE', NULL, '{"notes": null, "members": [{"fullName": "Dr. Emily Carter", "jobTitle": "Director of Global Partnerships", "memberType": "GUEST", "nationality": "Hoa Kỳ", "displayOrder": 1, "organization": "Global Education Alliance"}, {"fullName": "Mr. Daniel Kim", "jobTitle": "International Program Manager", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 2, "organization": "Global Education Alliance"}, {"fullName": "Ms. Sofia Martinez", "jobTitle": "Academic Cooperation Coordinator", "memberType": "GUEST", "nationality": "Tây Ban Nha", "displayOrder": 3, "organization": "Global Education Alliance"}, {"fullName": "Prof. Liam O\'Connor", "jobTitle": "Dean of International Programs", "memberType": "GUEST", "nationality": "Ireland", "displayOrder": 4, "organization": "Dublin Institute of Technology"}, {"fullName": "Ms. Aiko Tanaka", "jobTitle": "International Student Advisor", "memberType": "GUEST", "nationality": "Nhật Bản", "displayOrder": 5, "organization": "Global Education Alliance"}], "purpose": "Học tập và trải nghiệm:Quan sát thực tế những kiến thức đã học trong sách vở.Tiếp thu thêm thông tin mới từ hướng dẫn viên hoặc thực tế địa phương.Nâng cao hiểu biết về văn hóa, lịch sử và con người vùng miền.Gắn kết tập thể:Tạo cơ hội để các thành viên trò chuyện và hiểu nhau hơn.Xây dựng tinh thần đoàn kết qua các hoạt động chung.Lưu giữ những kỷ niệm đẹp cùng nhau.Thư giãn và giải trí:Giảm bớt căng thẳng sau những ngày làm việc hoặc học tập mệt mỏi.Tận hưởng bầu không khí trong lành ở những nơi mới.Phục hồi năng lượng tích cực cho bản thân.", "visitType": "CAMPUS_TOUR", "plannedEndAt": "2026-08-28T10:00:00", "delegationName": "Đoàn sinh viên ĐHQGHN", "plannedStartAt": "2026-08-28T09:00:00", "visitTypeOther": null, "workingContent": "Đón tiếp và giới thiệu: Ban quản lý giới thiệu tổng quan về lịch sử, quy mô và các điểm nhấn nổi bật tại khu tham quan.Khảo sát thực tế: Đoàn di chuyển tham quan các khu vực trưng bày, cảnh quan chính và kiểm tra hệ thống cơ sở hạ tầng phục vụ khách.Trao đổi và thảo luận: Hai bên đóng góp ý kiến về việc cải thiện trải nghiệm tham quan, đảm bảo an toàn và vệ sinh môi trường.Tổng kết và ký kết: Thống nhất các nội dung hợp tác ngắn hạn và chụp ảnh lưu niệm kết thúc chuyến công tác.", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "canhnvthe186121@fpt.edu.vn", "operationalContactPhone": null, "operationalContactFullName": "Prof. Liam O\'Connor", "operationalContactJobTitle": "Dean of International Programs", "operationalContactOrganization": "Dublin Institute of Technology"}', 233, '2026-08-24 11:24:28', NULL),
