	(46066, 47035, 47150, 1, 1, 'CREATE', NULL, '{"notes": null, "members": [{"fullName": "Truong D Nguyen (Patrick)", "jobTitle": "HR-Admin Manager", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 1, "organization": "LGCNS", "guestMemberId": 99178}, {"fullName": "Kenji Sato Kimi", "jobTitle": "Giám đốc Kỹ thuật (CTO)", "memberType": "GUEST", "nationality": "Nhật Bản", "displayOrder": 2, "organization": "LGCNS", "guestMemberId": 99179}, {"fullName": "Ngô Phương Thúy", "jobTitle": "Trưởng phòng Thiết kế", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 3, "organization": "LGCNS", "guestMemberId": 99180}, {"fullName": "Min-soo Jun", "jobTitle": "Chuyên viên Kiểm thử (QA)", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 4, "organization": "LETUINEDU", "guestMemberId": 99181}, {"fullName": "Morgan Maxwell", "jobTitle": "Graphic Designer", "memberType": "GUEST", "nationality": "Vương quốc Anh", "displayOrder": 5, "organization": "LETUINEDU", "guestMemberId": 99182}, {"fullName": "Nguyễn Văn Tuấn", "jobTitle": "Trưởng phòng Tín dụng", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 6, "organization": "LETUINEDU", "guestMemberId": 99183}, {"fullName": "Nguyễn Quang Thoại", "jobTitle": "Nhân Viên", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 7, "organization": "LGCNS", "guestMemberId": 99184}], "purpose": "Tham quan FPT University Hà Nội nhằm tìm hiểu mô hình đào tạo gắn với doanh nghiệp, cơ sở vật chất giảng dạy, nghiên cứu và hệ sinh thái đổi mới sáng tạo. Chuyến thăm tập trung trao đổi về chương trình đào tạo vi mạch, bán dẫn, trí tuệ nhân tạo, cơ hội phối hợp xây dựng học phần, tổ chức hội thảo và trao đổi học thuật. Hai bên thảo luận dự án nghiên cứu chung, thực tập, chuyển giao công nghệ và phát triển quan hệ hợp tác lâu dài trong tương lai gần.", "visitType": "WORKSHOP", "plannedEndAt": "2026-10-15T10:00:00", "delegationName": "thth", "plannedStartAt": "2026-10-15T09:00:00", "visitTypeOther": null, "workingContent": "Buổi họp tập trung trao đổi về chương trình sinh viên giữa FPT University và Đoàn Kyoto International University, gồm điều kiện tham gia, tiêu chí tuyển chọn, thời gian học tập và số lượng sinh viên. Hai bên thảo luận cơ chế công nhận tín chỉ, quy đổi kết quả học tập, học phí, học bổng, chỗ ở, bảo hiểm và hỗ trợ thị thực. Đại diện hai trường thống nhất xây dựng danh sách học phần tương đương, lịch học và đầu mối phụ trách. Nội dung cũng đề cập chương trình định hướng trước khi khởi hành, hỗ trợ sinh viên quốc tế trong thời gian học, hoạt động giao lưu văn hóa và xử lý tình huống phát sinh. Cuối buổi, hai bên dự kiến lập kế hoạch thử nghiệm, xác định mốc thời gian, trách nhiệm phối hợp và tiêu chí đánh giá toàn diện hiệu quả chương trình.", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "thoainqhe180765@fpt.edu.vn", "operationalContactPhone": null, "operationalContactFullName": "Nguyễn Quang Thoại", "operationalContactJobTitle": "Nhân Viên", "operationalContactOrganization": "LGCNS", "operationalContactGuestMemberId": 99184}', 235, '2026-08-26 07:10:50', NULL),
	(46067, 47036, 47151, 1, 1, 'CREATE', NULL, '{"notes": null, "members": [{"fullName": "Truong D Nguyen (Patrick)", "jobTitle": "HR-Admin Manager", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 1, "organization": "LGCNS", "guestMemberId": 99185}, {"fullName": "Kenji Sato Kimi", "jobTitle": "Giám đốc Kỹ thuật (CTO)", "memberType": "GUEST", "nationality": "Nhật Bản", "displayOrder": 2, "organization": "LGCNS", "guestMemberId": 99186}, {"fullName": "Ngô Phương Thúy", "jobTitle": "Trưởng phòng Thiết kế", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 3, "organization": "LGCNS", "guestMemberId": 99187}, {"fullName": "Min-soo Jun", "jobTitle": "Chuyên viên Kiểm thử (QA)", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 4, "organization": "LETUINEDU", "guestMemberId": 99188}, {"fullName": "Morgan Maxwell", "jobTitle": "Graphic Designer", "memberType": "GUEST", "nationality": "Vương quốc Anh", "displayOrder": 5, "organization": "LETUINEDU", "guestMemberId": 99189}, {"fullName": "Nguyễn Văn Tuấn", "jobTitle": "Trưởng phòng Tín dụng", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 6, "organization": "LETUINEDU", "guestMemberId": 99190}, {"fullName": "Nguyễn Quang Thoại", "jobTitle": "Nhân Viên", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 7, "organization": "LGCNS", "guestMemberId": 99191}], "purpose": "Tham quan FPT University Hà Nội nhằm tìm hiểu mô hình đào tạo gắn với doanh nghiệp, cơ sở vật chất giảng dạy, nghiên cứu và hệ sinh thái đổi mới sáng tạo. Chuyến thăm tập trung trao đổi về chương trình đào tạo vi mạch, bán dẫn, trí tuệ nhân tạo, cơ hội phối hợp xây dựng học phần, tổ chức hội thảo và trao đổi học thuật. Hai bên thảo luận dự án nghiên cứu chung, thực tập, chuyển giao công nghệ và phát triển quan hệ hợp tác lâu dài trong tương lai gần.", "visitType": "CAMPUS_TOUR", "plannedEndAt": "2026-09-30T10:00:00", "delegationName": "NAm Á ĐÔng", "plannedStartAt": "2026-09-30T09