	(46069, 47037, 47152, 1, 1, 'CREATE', NULL, '{"notes": null, "members": [{"fullName": "Nguyen Hong Thu", "jobTitle": "HR-Admin Manager", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 1, "organization": "UNIMAS", "guestMemberId": 99197}, {"fullName": "PaJik Sato", "jobTitle": "Giám đốc Kỹ thuật (CTO)", "memberType": "GUEST", "nationality": "Nhật Bản", "displayOrder": 2, "organization": "UNIMAS", "guestMemberId": 99198}, {"fullName": "Ngô Thị Thảo", "jobTitle": "Trưởng phòng Thiết kế", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 3, "organization": "UNIMAS", "guestMemberId": 99199}, {"fullName": "Min-soo Kim Un", "jobTitle": "Chuyên viên Kiểm thử (QA)", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 4, "organization": "UNIMAS", "guestMemberId": 99200}, {"fullName": "Morgan Maxwell", "jobTitle": "Graphic Designer", "memberType": "GUEST", "nationality": "Vương quốc Anh", "displayOrder": 5, "organization": "UNIMAS", "guestMemberId": 99201}, {"fullName": "Lương Anh Tuấn", "jobTitle": "Trưởng phòng Tín dụng", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 6, "organization": "UNIMAS", "guestMemberId": 99202}, {"fullName": "Nguyễn Quang Thoại", "jobTitle": "Nhân viên", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 7, "organization": "UNIMAS", "guestMemberId": 99203}], "purpose": "The visit to FPT University Hanoi aimed to explore the university\'s industry-integrated training model, teaching and research facilities, and innovation ecosystem. Discussions focused on training programs in microchips, semiconductors, and artificial intelligence, as well as opportunities for collaborative curriculum development, seminar organization, and academic exchanges. Both parties also discussed joint research projects, internships, technology transfer, and the development of a long-term partnership in the near future.", "visitType": "MEETING", "plannedEndAt": "2026-09-10T10:00:00", "delegationName": "UNIMAS", "plannedStartAt": "2026-09-10T09:00:00", "visitTypeOther": null, "workingContent": "The meeting focused on discussing the student program between FPT University and UNIMAS, covering participation requirements, selection criteria, study duration, and student quotas. Both parties deliberated on mechanisms for credit recognition and academic result conversion, as well as tuition fees, scholarships, accommodation, insurance, and visa support. Representatives from both institutions agreed to establish a list of equivalent courses, a study schedule, and designated points of contact. Discussions also addressed pre-departure orientation, support for international students during their studies, cultural exchange activities, and the handling of unforeseen situations. Finally, the parties planned to develop a pilot scheme, defining timelines, coordination responsibilities, and comprehensive criteria for evaluating the program\'s effectiveness.", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "nguyenquangthoai04@gmail.com", "operationalContactPhone": null, "operationalContactFullName": "Nguyễn Quang Thoại", "operationalContactJobTitle": "Nhân viên", "operationalContactOrganization": "UNIMAS", "operationalContactGuestMemberId": 99203}', 238, '2026-08-26 14:23:00', NULL),
	(46070, 47037, 47152, 2, 1, 'RESUBMIT', NULL, '{"notes": null, "members": [{"fullName": "Nguyen Hong Thu", "jobTitle": "HR-Admin Manager", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 1, "organization": "UNIMAS", "guestMemberId": 99197}, {"fullName": "PaJik Sato", "jobTitle": "Giám đốc Kỹ thuật (CTO)", "memberType": "GUEST", "nationality": "Nhật Bản", "displayOrder": 2, "organization": "UNIMAS", "guestMemberId": 99198}, {"fullName": "Ngô Thị Thảo", "jobTitle": "Trưởng phòng Thiết kế", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 3, "organization": "UNIMAS", "guestMemberId": 99199}, {"fullName": "Min-soo Kim Un", "jobTitle": "Chuyên viên Kiểm thử (QA)", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 4, "organization": "UNIMAS", "guestMemberId": 99200}, {"fullName": "Morgan Maxwell", "jobTitle": "Graphic Designer", "memberType": "GUEST", "nationality": "Vương quốc Anh", "displayOrder": 5, "organization": "UNIMAS", "guestMemberId": 99201}, {"fullName": "Lương Anh Tuấn", "jobTitle": "Trưởng phòng Tín dụng", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 6, "organization": "UNIMAS", "guestMemberId": 99202}, {"fullName": "Nguyễn Quang Thoại", "jobTitle": "Nhân viên", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 7, "organization": "UNIMAS", "guestMemberId": 99203}], "purpose": "The visit to FPT University Hanoi aimed to explore the university\'s industry-integrated training model, teaching and research facilities, and innovation ecosystem. Discussions focused on training programs in microchips, semiconductors, and artificial intelligence, as well as opportunities for collaborative curriculum development, seminar organization, and academic exchanges. Both parties also discussed joint research projects, internships, technology transfer, and the development of a long-term partnership in the near future.", "visitType": "MEETING", "plannedEndAt": "2026-09-10T11:00:00", "delegationName": "UNIMAS", "plannedStartAt": "2026-09-10T09:00:00", "visitTypeOther": null, "workingContent": "The meeting focused on discussing the student program between FPT University and UNIMAS, covering participation requirements, selection criteria, study duration, and student quotas. Both parties deliberated on mechanisms for credit recognition and academic result conversion, as well as tuition fees, scholarships, accommodation, insurance, and visa support. Representatives from both institutions agreed to establish a list of equivalent courses, a study schedule, and designated points of contact. Discussions also addressed pre-departure orientation, support for international students during their studies, cultural exchange activities, and the handling of unforeseen situations. Finally, the parties planned to develop a pilot scheme, defining timelines, coordination responsibilities, and comprehensive criteria for evaluating the program\'s effectiveness.", "workingLanguage": "VI", "mediaConsentStatus": "AGREED", "transportationNote": null, "operationalContactEmail": "nguyenquangthoai04@gmail.com", "operationalContactPhone": null, "operationalContactFullName": "Nguyễn Quang Thoại", "operationalContactJobTitle": "Nhân viên", "operationalContactOrganization": "UNIMAS", "operationalContactGuestMemberId": 99203}', 238, '2026-08-26 14:26:37', '05ab1c1770ad49df88dab9ac6729d63c'),
	(46071, 47037, 47152, 3, 1, 'PENDING_EDIT', NULL, '{"notes": null, "members": [{"fullName": "Nguyen Hong Thu", "jobTitle": "HR-Admin Manager", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 1, "organization": "UNIMAS", "guestMemberId": 99197}, {"fullName": "PaJik Sato", "jobTitle": "Giám đốc Kỹ thuật (CTO)", "memberType": "GUEST", "nationality": "Nhật Bản", "displayOrder": 2, "organization": "UNIMAS", "guestMemberId": 99198}, {"fullName": "Ngô Thị Thảo", "jobTitle": "Trưởng phòng Thiết kế", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 3, "organization": "UNIMAS", "guestMemberId": 99199}, {"fullName": "Min-soo Kim Un", "jobTitle": "Chuyên viên Kiểm thử (QA)", "memberType": "GUEST", "nationality": "Hàn Quốc", "displayOrder": 4, "organization": "UNIMAS", "guestMemberId": 99200}, {"fullName": "Morgan Maxwell", "jobTitle": "Graphic Designer", "memberType": "GUEST", "nationality": "Vương quốc Anh", "displayOrder": 5, "organization": "UNIMAS", "guestMemberId": 99201}, {"fullName": "Lương Anh Tuấn", "jobTitle": "Trưởng phòng Tín dụng", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 6, "organization": "UNIMAS", "guestMemberId": 99202}, {"fullName": "Nguyễn Quang Thoại", "jobTitle": "Nhân viên", "memberType": "GUEST", "nationality": "Việt Nam", "displayOrder": 7, "organization": "UNIMAS", "guestMemberId": 99203}], "purpose": "The visit to FPT University Hanoi aimed to explore the university\'s industry-integrated training model, teaching and research facilities, and innovation ecosystem. Discussions focused on training programs in microchips, semiconductors, and artificial intelligence, as well as opportunities for collaborative curriculum development, seminar organization, and academic exchanges. Both parties also discussed joint research projects, internships, technology transfer, and the development of a long-term partnership in the near future.", "visitType": "MEETING", "plannedEndAt": "2026-09-10T11:00:00", "del