	(99001, 9902, 'EQUIPMENT', 'Thiết bị trình chiếu/demo cho Visitor cancelled HCM workshop after partner board reschedule', 'Yêu cầu hậu cần phục vụ request VR-2026-9002 tại FPT University Đà Nẵng. Mục tiêu nghiệp vụ: Đối tác đổi lịch họp hội đồng quản trị nên người đăng ký hủy yêu cầu sau khi campus đã được duyệt. Ghi chú xử lý: đã hủy theo trạng thái visit hoặc yêu cầu của host.', 'SYSTEM_REQUEST', NULL, 2, '2026-08-17 09:30:00', '2026-08-17 12:00:00', 'CANCELLED', 'HIGH', 12, 109, '2026-07-30 21:04:47', 135, '2026-07-30 23:04:47', 136, 135, '2026-07-31 00:04:47', NULL, NULL, '2026-08-16 17:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Quyết định được ghi nhận theo năng lực chuẩn bị thực tế tại DN.', 2, '2026-07-30 21:04:47', 12, '2026-08-08 17:05:05', 203),
	(99002, 9903, 'ROOM', 'Phòng họp CT cho Multi-campus request rejected because agenda scope was incomplete', 'Yêu cầu hậu cần phục vụ request VR-2026-9003 tại FPT University Cần Thơ. Mục tiêu nghiệp vụ: Staff Leader từ chối vì request multi-campus thiếu campus objective riêng và không đủ ngày chuẩn bị logistics liên cơ sở. Ghi chú xử lý: đã hủy theo trạng thái visit hoặc yêu cầu của host.', 'SYSTEM_REQUEST', NULL, 1, '2026-08-17 10:00:00', '2026-08-17 12:30:00', 'CANCELLED', 'MEDIUM', 14, 110, '2026-07-31 23:04:47', 137, '2026-08-01 00:04:47', 138, 137, '2026-08-01 01:04:47', NULL, NULL, '2026-08-16 18:00:00', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Quyết định được ghi nhận theo năng lực chuẩn bị thực tế tại CT.', 2, '2026-07-31 23:04:47', 14, '2026-08-08 17:05:05', 210),
