	(3001, 1001, 1, '2026-08-23 09:00:00', '2026-08-23 11:00:00', 'CANCELLED', 8, '2026-06-23 08:00:00', 'REGISTRANT_SELF_MATCH', NULL, NULL, NULL, NULL, NULL, NULL, 'WAIT_FOR_LATER', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 0, 8, '2026-06-23 10:00:00', 'VISITOR', 'SELF_SERVICE', 'Visitor xác nhận hủy instance HN do thay đổi lịch di chuyển. Host/IC đã dừng chuẩn bị phòng, logistics và gửi ghi chú follow-up.', 'Instance tại HN đã hủy; không chuẩn bị onsite, chỉ giữ lý do hủy và thông tin liên hệ để follow-up.', 1, '2026-06-23 08:00:00', 8, '2026-08-08 17:05:20', 8),
	(3002, 1002, 1, '2026-08-24 09:15:00', '2026-08-24 11:45:00', 'REJECTED', 21, '2026-06-10 08:30:00', 'REGISTRANT_SELF_MATCH', NULL, NULL, NULL, NULL, NULL, NULL, 'WAIT_FOR_LATER', NULL, NULL, NULL, NULL, NULL, 3, '2026-06-10 15:20:00', 'STAFF_LEADER', NULL, 'Từ chối do thời gian chuẩn bị thiết bị robot quá ngắn và phòng lab đã có lịch thi cuối kỳ. [Migrated to campus-level rejection for HN.]', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Campus HN đã từ chối tiếp nhận request; không chuẩn bị onsite, chỉ lưu lý do từ chối và thông tin follow-up.', 1, '2026-06-10 08:30:00', 21, '2026-08-08 17:05:20', 3),
	(3003, 1003, 1, '2026-08-16 09:45:00', '2026-08-16 12:45:00', 'AFTER_VISIT', 20, '2026-06-12 09:00:00', 'REGISTRANT_SELF_MATCH', NULL, NULL, NULL, 4, 3, '2026-06-12 16:45:00', 'WAIT_FOR_LATER', NULL, NULL, NULL, NULL, NULL, 3, '2026-06-12 16:45:00', 'STAFF_LEADER', NULL, 'IC Staff Hà Nội đã mở giai đoạn chuẩn bị tại FPT University Hà Nội; agenda và các hạng mục hỗ trợ đang được phối hợp.', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Checklist trước chuyến thăm tại HN: xác nhận khách, mở phòng họp, chuẩn bị màn hình, in agenda và chạy thử đường dẫn trình chiếu.', 3, '2026-06-12 09:00:00', 20, '2026-08-09 22:51:27', 4),
	(3004, 1004, 1, '2026-08-11 10:00:00', '2026-08-11 13:30:00', 'BEFORE_VISIT', 22, '2026-06-13 09:00:00', 'REGISTRANT_SELF_MATCH', NULL, NULL, NULL, 4, 3, '2026-06-13 14:15:00', 'WAIT_FOR_LATER', NULL, NULL, NULL, NULL, NULL, 3, '2026-06-13 14:15:00', 'STAFF_LEADER', NULL, 'FPT University Hà Nội đã chuyển sang chuẩn bị sau khi IC Staff Hà Nội tiếp nhận vai trò Host và kiểm tra kế hoạch.', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Checklist trước chuyến thăm tại HN: xác nhận khách, mở phòng họp, chuẩn bị màn hình, in agenda và chạy thử đường dẫn trình chiếu.', 2, '2026-06-13 09:00:00', 22, '2026-08-08 17:05:20', 4),
	(3005, 1005, 1, '2026-08-08 16:04:25', '2026-08-08 20:04:25', 'AFTER_VISIT', 23, '2026-06-14 09:00:00', 'REGISTRANT_SELF_MATCH', NULL, NULL, NULL, 4, 3, '2026-06-14 15:30:00', 'WAIT_FOR_LATER', NULL, NULL, NULL, NULL, NULL, 3, '2026-06-14 15:30:00', 'STAFF_LEADER', NULL, 'Đoàn khách đang làm việc tại FPT University Hà Nội; các đầu việc trong ngày được theo dõi theo lịch trình đã thống nhất.', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Đang tiếp đoàn tại HN; host cần cập nhật attendance, ghi minutes và chụp tối thiểu một ảnh nếu media consent cho phép.', 4, '2026-06-14 09:00:00', 23, '2026-08-13 19:42:45', 4),
	(3006, 1006, 1, '2026-08-06 14:00:00', '2026-08-06 19:00:00', 'AFTER_VISIT', 8, '2026-06-05 08:45:00', 'REGISTRANT_SELF_MATCH', NULL, NULL, NULL, 4, 3, '2026-06-05 14:45:00', 'WAIT_FOR_LATER', NULL, NULL, NULL, NULL, NULL, 3, '2026-06-05 14:45:00', 'STAFF_LEADER', NULL, 'Chương trình tại FPT University Hà Nội đã kết thúc; IC Staff Hà Nội đang hoàn thiện biên bản, phản hồi và các đầu việc tiếp nối.', NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, 'Sau visit tại HN: rà soát action item, thu feedback, chuẩn bị news hoặc xác nhận không cần news trước khi đóng hồ sơ.', 4, '2026-06-05 08:45:00', 8, '2026-08-08 17:05:20', 4),
	(3007, 1007, 1, '2026-07-21 15:00:00', '2026-07-21 21:00:00', 'CLOSED', 24, '2026-05-20 08:00:00', 'REGISTRANT_SELF_MATCH', NULL, NULL, NULL, 4, 3, '2026-05-20 16:15:00', 'WAIT_FOR_LATER', NULL, NULL, NULL, NULL, NULL, 3, '2026-05-20 16:15:00', 'STAFF_LEADER', NULL, 'FPT University Hà Nội đã hoàn thành toàn bộ quy trình sau chuyến thăm và lưu hồ sơ phục vụ tra cứu.', 4, '2026-06-01 17:30:00', 'Đã hoàn tất tiếp khách tại HN: agenda thực tế khớp biên bản, feedback đã ghi nhận, logistics đã đối soát và news/no-news gate đã xử lý.', 0, NULL, NULL, NULL, NULL, NULL, 'Hồ sơ tại HN đã đóng; biên bản, phản hồi và nội dung công khai đã được hoàn tất.', 5, '2026-05-20 08:00:00', 24, '2026-08-08 17:05:20', 4),
