	(1, 'bc5451f3-5463-43d7-b196-03d217296216', 'canhnvthe186121@fpt.edu.vn', '1ba2ad56a1199be6e9826633e8e4e8442a36beeb6c939872d5eb81bdc568b99c', '{"submissionId":"bc5451f3-5463-43d7-b196-03d217296216","registrant":{"fullName":"Th\\u1EAFng C\\u1EA3nh","nationality":"Egypt","organization":"Andes University Exchange Office (Andes Exchange)","jobTitle":"Delegation Coordinator","phone":"\\u002B84353521525","email":"canhnvthe186121@fpt.edu.vn"},"partnerId":109,"campusVisits":[{"campusId":"HN","plannedStartAt":"2026-08-13T09:00:00","plannedEndAt":"2026-08-13T10:00:00","delegationName":"Global Education Alliance \\u2013 Academic Partnership Delegation 2026","visitType":"CAMPUS_TOUR","visitTypeOther":null,"purpose":"Trao \\u0111\\u1ED5i c\\u01A1 h\\u1ED9i h\\u1EE3p t\\u00E1c \\u0111\\u00E0o t\\u1EA1o qu\\u1ED1c t\\u1EBF, x\\u00E2y d\\u1EF1ng ch\\u01B0\\u01A1ng tr\\u00ECnh trao \\u0111\\u1ED5i sinh vi\\u00EAn v\\u00E0 th\\u1ED1ng nh\\u1EA5t \\u0111\\u1ECBnh h\\u01B0\\u1EDBng ph\\u1ED1i h\\u1EE3p h\\u1ECDc thu\\u1EADt gi\\u1EEFa Global Education Alliance v\\u00E0 FPT University.","workingContent":"Hai b\\u00EAn gi\\u1EDBi thi\\u1EC7u t\\u1ED5ng quan v\\u1EC1 m\\u00F4 h\\u00ECnh \\u0111\\u00E0o t\\u1EA1o, m\\u1EA1ng l\\u01B0\\u1EDBi \\u0111\\u1ED1i t\\u00E1c v\\u00E0 c\\u00E1c ch\\u01B0\\u01A1ng tr\\u00ECnh qu\\u1ED1c t\\u1EBF \\u0111ang tri\\u1EC3n khai. \\u0110o\\u00E0n kh\\u00E1ch mong mu\\u1ED1n t\\u00ECm hi\\u1EC3u ch\\u01B0\\u01A1ng tr\\u00ECnh trao \\u0111\\u1ED5i sinh vi\\u00EAn m\\u1ED9t h\\u1ECDc k\\u1EF3, c\\u01A1 ch\\u1EBF c\\u00F4ng nh\\u1EADn t\\u00EDn ch\\u1EC9, \\u0111i\\u1EC1u ki\\u1EC7n ti\\u1EBFp nh\\u1EADn gi\\u1EA3ng vi\\u00EAn th\\u1EC9nh gi\\u1EA3ng v\\u00E0 kh\\u1EA3 n\\u0103ng ph\\u1ED1i h\\u1EE3p t\\u1ED5 ch\\u1EE9c workshop chuy\\u00EAn m\\u00F4n. Bu\\u1ED5i l\\u00E0m vi\\u1EC7c d\\u1EF1 ki\\u1EBFn k\\u1EBFt th\\u00FAc b\\u1EB1ng vi\\u1EC7c th\\u1ED1ng nh\\u1EA5t \\u0111\\u1EA7u m\\u1ED1i ph\\u1EE5 tr\\u00E1ch, b\\u1ED9 t\\u00E0i li\\u1EC7u c\\u1EA7n trao \\u0111\\u1ED5i v\\u00E0 k\\u1EBF ho\\u1EA1ch x\\u00E2y d\\u1EF1ng d\\u1EF1 th\\u1EA3o bi\\u00EAn b\\u1EA3n ghi nh\\u1EDB h\\u1EE3p t\\u00E1c.","visitors":[{"fullName":"Dr. Emily Carter","nationality":"Hoa K\\u1EF3","jobTitle":"Director of Global Partnerships","organization":"Global Education Alliance"},{"fullName":"Mr. Daniel Kim","nationality":"H\\u00E0n Qu\\u1ED1c","jobTitle":"International Program Manager","organization":"Global Education Alliance"},{"fullName":"Ms. Sofia Martinez","nationality":"T\\u00E2y Ban Nha","jobTitle":"Academic Cooperation Coordinator","organization":"Global Education Alliance"},{"fullName":"Prof. Liam O\\u0027Connor","nationality":"Ireland","jobTitle":"Dean of International Programs","organization":"Dublin Institute of Technology"},{"fullName":"Ms. Aiko Tanaka","nationality":"Nh\\u1EADt B\\u1EA3n","jobTitle":"International Student Advisor","organization":"Global Education Alliance"}],"externalSupportMembers":[{"fullName":"Nguy\\u1EC5n V\\u0103n A","jobTitle":"Gi\\u00E1m \\u0111\\u1ED1c","organization":"C\\u00F4ng ty XYZ","nationality":"Vi\\u1EC7t Nam"}],"operationalContact":{"fullName":"Nguy\\u1EC5n Di\\u1EC7u Th\\u00FAy Qu\\u1EF3nh","organization":"Andes University Exchange Office (Andes Exchange)","jobTitle":"Delegation Coordinator","phone":"\\u002B84353521525","email":"canhnvthe186121@fpt.edu.vn"},"workingLanguage":"VI","transportationNote":null,"mediaConsentStatus":"AGREED","notes":null,"hostSelection":null}]}', '2026-08-08 17:15:04', '2026-08-08 18:15:04', NULL),
	(2, 'fd0c2798-4086-4431-8cd0-63c1e603bb53', 'thoaiph12345@gmail.com', '4bff0cd05f7e6b2c053cd8165951fec35c8aa99a01e12eca9297923ce0d34a91', '{"submissionId":"fd0c2798-4086-4431-8cd0-63c1e603bb53","registrant":{"fullName":"Nguy\\u00EAn Nam","nationality":"South Korea","organization":"YUAN ZE UNIVERSITY","jobTitle":"staff","phone":"","email":"thoaiph12345@gmail.com"},"partnerId":null,"campusVisits":[{"campusId":"HN","plannedStartAt":"2026-08-16T09:00:00","plannedEndAt":"2026-08-16T10:00:00","delegationName":"YUAN ZE UNIVERSITY \\u0110\\u1EBEN THAM QUAN V\\u00C0 L\\u00C0M VI\\u1EC6C","visitType":"MEETING","visitTypeOther":null,"purpose":"Tham quan FPT University H\\u00E0 N\\u1ED9i nh\\u1EB1m t\\u00ECm hi\\u1EC3u m\\u00F4 h\\u00ECnh \\u0111\\u00E0o t\\u1EA1o g\\u1EAFn v\\u1EDBi doanh nghi\\u1EC7p, c\\u01A1 s\\u1EDF v\\u1EADt ch\\u1EA5t gi\\u1EA3ng d\\u1EA1y, nghi\\u00EAn c\\u1EE9u v\\u00E0 h\\u1EC7 sinh th\\u00E1i \\u0111\\u1ED5i m\\u1EDBi s\\u00E1ng t\\u1EA1o. Chuy\\u1EBFn th\\u0103m t\\u1EADp trung trao \\u0111\\u1ED5i v\\u1EC1 ch\\u01B0\\u01A1ng tr\\u00ECnh \\u0111\\u00E0o t\\u1EA1o vi m\\u1EA1ch, b\\u00E1n d\\u1EABn, tr\\u00ED tu\\u1EC7 nh\\u00E2n t\\u1EA1o, c\\u01A1 h\\u1ED9i ph\\u1ED1i h\\u1EE3p x\\u00E2y d\\u1EF1ng h\\u1ECDc ph\\u1EA7n, t\\u1ED5 ch\\u1EE9c h\\u1ED9i th\\u1EA3o v\\u00E0 trao \\u0111\\u1ED5i h\\u1ECDc thu\\u1EADt. Hai b\\u00EAn th\\u1EA3o lu\\u1EADn d\\u1EF1 \\u00E1n nghi\\u00EAn c\\u1EE9u chung, th\\u1EF1c t\\u1EADp, chuy\\u1EC3n giao c\\u00F4ng ngh\\u1EC7 v\\u00E0 ph\\u00E1t tri\\u1EC3n quan h\\u1EC7 h\\u1EE3p t\\u00E1c l\\u00E2u d\\u00E0i trong t\\u01B0\\u01A1ng lai g\\u1EA7n.","workingContent":"Bu\\u1ED5i h\\u1ECDp t\\u1EADp trung trao \\u0111\\u1ED5i v\\u1EC1 ch\\u01B0\\u01A1ng tr\\u00ECnh sinh vi\\u00EAn gi\\u1EEFa FPT University v\\u00E0 \\u0110o\\u00E0n Kyoto International University, g\\u1ED3m \\u0111i\\u1EC1u ki\\u1EC7n tham gia, ti\\u00EAu ch\\u00ED tuy\\u1EC3n ch\\u1ECDn, th\\u1EDDi gian h\\u1ECDc t\\u1EADp v\\u00E0 s\\u1ED1 l\\u01B0\\u1EE3ng sinh vi\\u00EAn. Hai b\\u00EAn th\\u1EA3o lu\\u1EADn c\\u01A1 ch\\u1EBF c\\u00F4ng nh\\u1EADn t\\u00EDn ch\\u1EC9, quy \\u0111\\u1ED5i k\\u1EBFt qu\\u1EA3 h\\u1ECDc t\\u1EADp, h\\u1ECDc ph\\u00ED, h\\u1ECDc b\\u1ED5ng, ch\\u1ED7 \\u1EDF, b\\u1EA3o hi\\u1EC3m v\\u00E0 h\\u1ED7 tr\\u1EE3 th\\u1ECB th\\u1EF1c. \\u0110\\u1EA1i di\\u1EC7n hai tr\\u01B0\\u1EDDng th\\u1ED1ng nh\\u1EA5t x\\u00E2y d\\u1EF1ng danh s\\u00E1ch h\\u1ECDc ph\\u1EA7n t\\u01B0\\u01A1ng \\u0111\\u01B0\\u01A1ng, l\\u1ECBch h\\u1ECDc v\\u00E0 \\u0111\\u1EA7u m\\u1ED1i ph\\u1EE5 tr\\u00E1ch. N\\u1ED9i dung c\\u0169ng \\u0111\\u1EC1 c\\u1EADp ch\\u01B0\\u01A1ng tr\\u00ECnh \\u0111\\u1ECBnh h\\u01B0\\u1EDBng tr\\u01B0\\u1EDBc khi kh\\u1EDFi h\\u00E0nh, h\\u1ED7 tr\\u1EE3 sinh vi\\u00EAn qu\\u1ED1c t\\u1EBF trong th\\u1EDDi gian h\\u1ECDc, ho\\u1EA1t \\u0111\\u1ED9ng giao l\\u01B0u v\\u0103n h\\u00F3a v\\u00E0 x\\u1EED l\\u00FD t\\u00ECnh hu\\u1ED1ng ph\\u00E1t sinh. Cu\\u1ED1i bu\\u1ED5i, hai b\\u00EAn d\\u1EF1 ki\\u1EBFn l\\u1EADp k\\u1EBF ho\\u1EA1ch th\\u1EED nghi\\u1EC7m, x\\u00E1c \\u0111\\u1ECBnh m\\u1ED1c th\\u1EDDi gian, tr\\u00E1ch nhi\\u1EC7m ph\\u1ED1i h\\u1EE3p v\\u00E0 ti\\u00EAu ch\\u00ED \\u0111\\u00E1nh gi\\u00E1 to\\u00E0n di\\u1EC7n hi\\u1EC7u qu\\u1EA3 ch\\u01B0\\u01A1ng tr\\u00ECnh.","visitors":[{"fullName":"Truong D Nguyen (Patrick)","nationality":"Vi\\u1EC7t Nam","jobTitle":"Managing Director","organization":"UK CENTRE"},{"fullName":"Nguy\\u1EC5n Minh Tr\\u00ED","nationality":"Vi\\u1EC7t Nam","jobTitle":"Ph\\u00F3 Gi\\u00E1m \\u0111\\u1ED1c","organization":"UK CENTRE"},{"fullName":"Nguyen Hong Thu","nationality":"Vi\\u1EC7t Nam","jobTitle":"HR-Admin Manager","organization":"MEDIA MAX JAPAN (VIET NAM) CO., LTD"},{"fullName":"Kenji Sato","nationality":"Nh\\u1EADt B\\u1EA3n","jobTitle":"Gi\\u00E1m \\u0111\\u1ED1c K\\u1EF9 thu\\u1EADt (CTO)","organization":"MEDIA MAX JAPAN (VIET NAM) CO., LTD"},{"fullName":"Ng\\u00F4 Ph\\u01B0\\u01A1ng Th\\u1EA3o","nationality":"Vi\\u1EC7t Nam","jobTitle":"Tr\\u01B0\\u1EDFng ph\\u00F2ng Thi\\u1EBFt k\\u1EBF","organization":"MEDIA MAX JAPAN (VIET NAM) CO., LTD"},{"fullName":"Tr\\u1ECBnh Ho\\u00E0i Nam","nationality":"Vi\\u1EC7t Nam","jobTitle":"K\\u1EF9 s\\u01B0 Ph\\u1EA7n m\\u1EC1m Tr\\u01B0\\u1EDFng","organization":"MEDIA MAX JAPAN (VIET NAM) CO., LTD"},{"fullName":"Min-soo Kim","nationality":"H\\u00E0n Qu\\u1ED1c","jobTitle":"Chuy\\u00EAn vi\\u00EAn Ki\\u1EC3m th\\u1EED (QA)","organization":"MEDIA MAX JAPAN (VIET NAM) CO., LTD"},{"fullName":"Morgan Maxwell","nationality":"Anh","jobTitle":"Graphic Designer","organization":"WARNER \\u0026 SPENCER"},{"fullName":"Nguy\\u1EC5n Kh\\u00E1nh Linh","nationality":"Vi\\u1EC7t Nam","jobTitle":"Gi\\u00E1m \\u0111\\u1ED1c Chi nh\\u00E1nh","organization":"WARNER \\u0026 SPENCER"},{"fullName":"David Miller","nationality":"M\\u1EF9","jobTitle":"C\\u1ED1 v\\u1EA5n T\\u00E0i ch\\u00EDnh Qu\\u1ED1c t\\u1EBF","organization":"WARNER \\u0026 SPENCER"},{"fullName":"L\\u01B0\\u01A1ng V\\u0103n Tu\\u1EA5n","nationality":"Vi\\u1EC7t Nam","jobTitle":"Tr\\u01B0\\u1EDFng ph\\u00F2ng T\\u00EDn d\\u1EE5ng","organization":"WARNER \\u0026 SPENCER"}],"externalSupportMembers":[],"operationalContact":{"fullName":"Nguy\\u00EAn Ly Hao","organization":"YUAN ZE UNIVERSITY","jobTitle":"staff","phone":"","email":"thoaitop@gmail.com"},"workingLanguage":"VI","transportationNote":null,"mediaConsentStatus":"AGREED","notes":"kh\\u00F4ng c\\u00F3 g\\u00EC","hostSelection":null}]}', '2026-08-08 22:43:48', '2026-08-08 23:43:48', '2026-08-08 22:44:18'),
