	(10, '76c91a1c-7410-41f1-8ee4-6c8d3c8d275f', 'nguyenquangthoai04@gmail.com', '811a22f7851ddc292316dc1d88e2ff3d3f43e947840d6eac377357441c096614', '{"submissionId":"76c91a1c-7410-41f1-8ee4-6c8d3c8d275f","registrant":{"fullName":"Nguy\\u1EC5n Quang Tho\\u1EA1i","nationality":"Vietnam","organization":"NANNING UNIVERSITY","jobTitle":"International Relations Manager","phone":"","email":"nguyenquangthoai04@gmail.com"},"partnerId":null,"campusVisits":[{"campusId":"HN","plannedStartAt":"2026-09-06T09:00:00","plannedEndAt":"2026-09-06T10:00:00","delegationName":"NANNING UNIVERSITY","visitType":"SIGNING_CEREMONY","visitTypeOther":null,"purpose":"Tham quan FPT University H\\u00E0 N\\u1ED9i nh\\u1EB1m t\\u00ECm hi\\u1EC3u m\\u00F4 h\\u00ECnh \\u0111\\u00E0o t\\u1EA1o g\\u1EAFn v\\u1EDBi doanh nghi\\u1EC7p, c\\u01A1 s\\u1EDF v\\u1EADt ch\\u1EA5t gi\\u1EA3ng d\\u1EA1y, nghi\\u00EAn c\\u1EE9u v\\u00E0 h\\u1EC7 sinh th\\u00E1i \\u0111\\u1ED5i m\\u1EDBi s\\u00E1ng t\\u1EA1o. Chuy\\u1EBFn th\\u0103m t\\u1EADp trung trao \\u0111\\u1ED5i v\\u1EC1 ch\\u01B0\\u01A1ng tr\\u00ECnh \\u0111\\u00E0o t\\u1EA1o vi m\\u1EA1ch, b\\u00E1n d\\u1EABn, tr\\u00ED tu\\u1EC7 nh\\u00E2n t\\u1EA1o, c\\u01A1 h\\u1ED9i ph\\u1ED1i h\\u1EE3p x\\u00E2y d\\u1EF1ng h\\u1ECDc ph\\u1EA7n, t\\u1ED5 ch\\u1EE9c h\\u1ED9i th\\u1EA3o v\\u00E0 trao \\u0111\\u1ED5i h\\u1ECDc thu\\u1EADt. Hai b\\u00EAn th\\u1EA3o lu\\u1EADn d\\u1EF1 \\u00E1n nghi\\u00EAn c\\u1EE9u chung, th\\u1EF1c t\\u1EADp, chuy\\u1EC3n giao c\\u00F4ng ngh\\u1EC7 v\\u00E0 ph\\u00E1t tri\\u1EC3n quan h\\u1EC7 h\\u1EE3p t\\u00E1c l\\u00E2u d\\u00E0i trong t\\u01B0\\u01A1ng lai g\\u1EA7n.","workingContent":"Bu\\u1ED5i h\\u1ECDp t\\u1EADp trung trao \\u0111\\u1ED5i v\\u1EC1 ch\\u01B0\\u01A1ng tr\\u00ECnh sinh vi\\u00EAn gi\\u1EEFa FPT University v\\u00E0 \\u0110o\\u00E0n Kyoto International University, g\\u1ED3m \\u0111i\\u1EC1u ki\\u1EC7n tham gia, ti\\u00EAu ch\\u00ED tuy\\u1EC3n ch\\u1ECDn, th\\u1EDDi gian h\\u1ECDc t\\u1EADp v\\u00E0 s\\u1ED1 l\\u01B0\\