	(17, 'fef235c0-06aa-42f6-9e6c-ad556622f08f', 'nguyenquangthoai04@gmail.com', 'f8c99cbb38250beef2d33744e86da45aa73623b14d4669b109b52c5c42a05342', '{"submissionId":"fef235c0-06aa-42f6-9e6c-ad556622f08f","registrant":{"fullName":"Nguy\\u1EC5n Quang Tho\\u1EA1i","nationality":"Vietnam","organization":"Nam \\u00C1 \\u0110\\u00D4ng","jobTitle":"Nh\\u00E2n vi\\u00EAn","phone":"","email":"nguyenquangthoai04@gmail.com"},"partnerId":null,"campusVisits":[{"campusId":"HN","plannedStartAt":"2026-09-30T09:00:00","plannedEndAt":"2026-09-30T10:00:00","delegationName":"NAm \\u00C1 \\u0110\\u00D4ng","visitType":"CAMPUS_TOUR","visitTypeOther":null,"purpose":"Tham quan FPT University H\\u00E0 N\\u1ED9i nh\\u1EB1m t\\u00ECm hi\\u1EC3u m\\u00F4 h\\u00ECnh \\u0111\\u00E0o t\\u1EA1o g\\u1EAFn v\\u1EDBi doanh nghi\\u1EC7p, c\\u01A1 s\\u1EDF v\\u1EADt ch\\u1EA5t gi\\u1EA3ng d\\u1EA1y, nghi\\u00EAn c\\u1EE9u v\\u00E0 h\\u1EC7 sinh th\\u00E1i \\u0111\\u1ED5i m\\u1EDBi s\\u00E1ng t\\u1EA1o. Chuy\\u1EBFn th\\u0103m t\\u1EADp trung trao \\u0111\\u1ED5i v\\u1EC1 ch\\u01B0\\u01A1ng tr\\u00ECnh \\u0111\\u00E0o t\\u1EA1o vi m\\u1EA1ch, b\\u00E1n d\\u1EABn, tr\\u00ED tu\\u1EC7 nh\\u00E2n t\\u1EA1o, c\\u01A1 h\\u1ED9i ph\\u1ED1i h\\u1EE3p x\\u00E2y d\\u1EF1ng h\\u1ECDc ph\\u1EA7n, t\\u1ED5 ch\\u1EE9c h\\u1ED9i th\\u1EA3o v\\u00E0 trao \\u0111\\u1ED5i h\\u1ECDc thu\\u1EADt. Hai b\\u00EAn th\\u1EA3o lu\\u1EADn d\\u1EF1 \\u00E1n nghi\\u00EAn c\\u1EE9u chung, th\\u1EF1c t\\u1EADp, chuy\\u1EC3n giao c\\u00F4ng ngh\\u1EC7 v\\u00E0 ph\\u00E1t tri\\u1EC3n quan h\\u1EC7 h\\u1EE3p t\\u00E1c l\\u00E2u d\\u00E0i trong t\\u01B0\\u01A1ng lai g\\u1EA7n.","workingContent":"Bu\\u1ED5i h\\u1ECDp t\\u1EADp trung trao \\u0111\\u1ED5i v\\u1EC1 ch\\u01B0\\u01A1ng tr\\u00ECnh sinh vi\\u00EAn gi\\u1EEFa FPT University v\\u00E0 \\u0110o\\u00E0n Kyoto International University, g\\u1ED3m \\u0111i\\u1EC1u ki\\u1EC7n tham gia, ti\\u00EAu ch\\u00ED tuy\\u1EC3n ch\\u1ECDn, th\\u1EDDi gian h\\u1ECDc t\\u1EADp v\\u00E0 s\\u1ED1 l\\u01B0\\u1EE3ng sinh vi\\u00EAn. Hai b\\u00EAn th\\u1EA3o lu\\u1EADn c\\u01A1 ch\\u1EBF c\\u00F4ng nh\\u1EADn t\\u00EDn ch\\u1EC9, quy \\u0111\\u1ED5i k\\u1EBFt qu\\u1EA3 h\\u1ECDc t\\u1EADp, h\\u1ECDc ph\\u00ED, h\\u1ECDc b\\u1ED5ng, ch\\u1ED7 \\u1EDF, b\\u1EA3o hi\\u1EC3m v\\u00E0 h\\u1ED7 tr\\u1EE3 th\\u1ECB th\\u1EF1c. \\u0110\\u1EA1i di\\u1EC7n hai tr\\u01B0\\u1EDDng th\\u1ED1ng nh\\u1EA5t x\\u00E2y d\\u1EF1ng danh s\\u00E1ch h\\u1ECDc ph\\u1EA7n t\\u01B0\\u01A1ng \\u0111\\u01B0\\u01A1ng, l\\u1ECBch h\\u1ECDc v\\u00E0 \\u0111\\u1EA7u m\\u1ED1i ph\\u1EE5 tr\\u00E1ch. N\\u1ED9i dung c\\u0169ng \\u0111\\u1EC1 c\\u1EADp ch\\u01B0\\u01A1ng tr\\u00ECnh \\u0111\\u1ECBnh h\\u01B0\\u1EDBng tr\\u01B0\\u1EDBc khi kh\\u1EDFi h\\u00E0nh, h\\u1ED7 tr\\u1EE3 sinh vi\\u00EAn qu\\u1ED1c t\\u1EBF trong th\\u1EDDi gian h\\u1ECDc, ho\\u1EA1t \\u0111\\u1ED9ng giao l\\u01B0u v\\u0103n h\\u00F3a v\\u00E0 x\\u1EED l\\u00FD t\\u00ECnh hu\\u1ED1ng ph\\u00E1t sinh. Cu\\u1ED1i bu\\u1ED5i, hai b\\u00EAn d\\u1EF1 ki\\u1EBFn l\\u1EADp k\\u1EBF ho\\u1EA1ch th\\u1EED nghi\\u1EC7m, x\\u00E1c \\u0111\\u1ECBnh m\\u1ED1c th\\u1EDDi gian, tr\\u00E1ch nhi\\u1EC7m ph\\u1ED1i h\\u1EE3p v\\u00E0 ti\\u00EAu ch\\u00ED \\u0111\\u00E1nh gi\\u00E1 to\\u00E0n di\\u1EC7n hi\\u1EC7u qu\\u1EA3 ch\\u01B0\\u01A1ng tr\\u00ECnh.","visitors":[{"fullName":"Truong D Nguyen (Patrick)","nationality":"H\\u00E0n Qu\\u1ED1c","jobTitle":"HR-Admin Manager","organization":"LGCNS","organizationPartnerId":null,"clientMemberKey":"1327d615-abd9-4c5a-af67-e916d67954e9","guestMemberId":null},{"fullName":"Kenji Sato Kimi","nationality":"Nh\\u1EADt B\\u1EA3n","jobTitle":"Gi\\u00E1m \\u0111\\u1ED1c K\\u1EF9 thu\\u1EADt (CTO)","organization":"LGCNS","organizationPartnerId":null,"clientMemberKey":"da58d61c-4ee6-4f02-a2d2-6a4eaf7a7165","guestMemberId":null},{"fullName":"Ng\\u00F4 Ph\\u01B0\\u01A1ng Th\\u00FAy","nationality":"Vi\\u1EC7t Nam","jobTitle":"Tr\\u01B0\\u1EDFng ph\\u00F2ng Thi\\u1EBFt k\\u1EBF","organization":"LGCNS","organizationPartnerId":null,"clientMemberKey":"0f9f91b4-85b3-4155-a072-7a75354909f0","guestMemberId":null},{"fullName":"Min-soo Jun","nationality":"H\\u00E0n Qu\\u1ED1c","jobTitle":"Chuy\\u00EAn vi\\u00EAn Ki\\u1EC3m th\\u1EED (QA)","organization":"LETUINEDU","organizationPartnerId":null,"clientMemberKey":"718aefa2-3d7d-4438-875d-94a4ee87aee8","guestMemberId":null},{"fullName":"Morgan Maxwell","nationality":"V\\u01B0\\u01A1ng qu\\u1ED1c Anh","jobTitle":"Graphic Designer","organization":"LETUINEDU","organizationPartnerId":null,"clientMemberKey":"4fcf2a8a-5077-4585-83dd-e9e7346bdc75","guestMemberId":null},{"fullName":"Nguy\\u1EC5n V\\u0103n Tu\\u1EA5n","nationality":"Vi\\u1EC7t Nam","jobTitle":"Tr\\u01B0\\u1EDFng ph\\u00F2ng T\\u00EDn d\\u1EE5ng","organization":"LETUINEDU","organizationPartnerId":null,"clientMemberKey":"6835515c-9ead-4b96-86e1-73dce160c6ab","guestMemberId":null},{"fullName":"Nguy\\u1EC5n Quang Tho\\u1EA1i","nationality":"Vi\\u1EC7t Nam","jobTitle":"Nh\\u00E2n Vi\\u00EAn","organization":"LGCNS","organizationPartnerId":null,"clientMemberKey":"fcd144a3-e049-4d16-8d66-0d850d3c1c5a","guestMemberId":null}],"externalSupportMembers":[],"operationalContact":{"fullName":"Nguy\\u1EC5n Quang Tho\\u1EA1i","organization":"LGCNS","jobTitle":"Nh\\u00E2n Vi\\u00EAn","phone":"","email":"nguyenquangthoai04@gmail.com"},"workingLanguage":"VI","transportationNote":null,"mediaConsentStatus":"AGREED","notes":null,"hostSelection":null,"operationalContactClientMemberKey":"fcd144a3-e049-4d16-8d66-0d850d3c1c5a"}]}', '2026-08-26 10:39:06', '2026-08-26 11:39:06', '2026-08-26 10:39:28'),
	(18, '5ef582b5-2afa-4381-84bf-1d19cede6355', 'nguyenquangthoai04@gmail.com', '35d672a944be7c8a37231d6191bae450bb686ecbcba91db5d6deeb8fd4c8e541', '{"submissionId":"5ef582b5-2afa-4381-84bf-1d19cede6355","registrant":{"fullName":"Nguy\\u1EC5n Quang Tho\\u1EA1i","nationality":"Vietnam","organization":"UNIMAS","jobTitle":"Nh\\u00E2n vi\\u00EAn","phone":"","email":"nguyenquangthoai04@gmail.com"},"partnerId":null,"campusVisits":[{"campusId":"HN","plannedStartAt":"2026-09-10T09:00:00","plannedEndAt":"2026-09-10T10:00:00","delegationName":"UNIMAS","visitType":"MEETING","visitTypeOther":null,"purpose":"The visit to FPT University Hanoi aimed to explore the university\\u0027s industry-integrated training model, teaching and research facilities, and innovation ecosystem. Discussions focused on training programs in microchips, semiconductors, and artificial intelligence, as well as opportunities for collaborative curriculum development, seminar organization, and academic exchanges. Both parties also discussed joint research projects, internships, technology transfer, and the development of a long-term partnership in the near future.","workingContent":"The meeting focused on discussing the student program between FPT University and UNIMAS, covering participation requirements, selection criteria, study duration, and student quotas. Both parties deliberated on mechanisms for credit recognition and academic result conversion, as well as tuition fees, scholarships, accommodation, insurance, and visa support. Representatives from both institutions agreed to establish a list of equivalent courses, a study schedule, and designated points of contact. Discussions also addressed pre-departure orientation, support for international students during their studies, cultural exchange activities, and the handling of unforeseen situations. Finally, the parties planned to develop a pilot scheme, defining timelines, coordination responsibilities, and comprehensive criteria for evaluating the program\\u0027s effectiveness.","visitors":[{"fullName":"Nguyen Hong Thu","nationality":"H\\u00E0n Qu\\u1ED1c","jobTitle":"HR-Admin Manager","organization":"UNIMAS","organizationPartnerId":null,"clientMemberKey":"c42737d4-9a38-4656-add7-e9dbabb9e3a9","guestMemberId":null},{"fullName":"PaJik Sato","nationality":"Nh\\u1EADt B\\u1EA3n","jobTitle":"Gi\\u00E1m \\u0111\\u1ED1c K\\u1EF9 thu\\u1EADt (CTO)","organization":"UNIMAS","organizationPartnerId":null,"clientMemberKey":"9a753798-94ac-4cc3-99f7-7663e248dfeb","guestMemberId":null},{"fullName":"Ng\\u00F4 Th\\u1ECB Th\\u1EA3o","nationality":"Vi\\u1EC7t Nam","jobTitle":"Tr\\u01B0\\u1EDFng ph\\u00F2ng Thi\\u1EBFt k\\u1EBF","organization":"UNIMAS","organizationPartnerId":null,"clientMemberKey":"f5153126-f02f-4d3e-83c5-55f83a7039f1","guestMemberId":null},{"fullName":"Min-soo Kim Un","nationality":"H\\u00E0n Qu\\u1ED1c","jobTitle":"Chuy\\u00EAn vi\\u00EAn Ki\\u1EC3m th\\u1EED (QA)","organization":"UNIMAS","organizationPartnerId":null,"clientMemberKey":"aba311a8-a8f0-4788-893a-a1486fd24bcb","guestMemberId":null},{"fullName":"Morgan Maxwell","nationality":"V\\u01B0\\u01A1ng qu\\u1ED1c Anh","jobTitle":"Graphic Designer","organization":"UNIMAS","organizationPartnerId":null,"clientMemberKey":"7f08e52c-63c7-4251-96da-952a2f87bc30","guestMemberId":null},{"fullName":"L\\u01B0\\u01A1ng Anh Tu\\u1EA5n","nationality":"Vi\\u1EC7t Nam","jobTitle":"Tr\\u01B0\\u1EDFng ph\\u00F2ng T\\u00EDn d\\u1EE5ng","organization":"UNIMAS","organizationPartnerId":null,"clientMemberKey":"1ca5bd78-24db-4cc1-aa03-bb461270ce07","guestMemberId":null},{"fullName":"Nguy\\u1EC5n Quang Tho\\u1EA1i","nationality":"Vietnam","jobTitle":"Nh\\u00E2n vi\\u00EAn","organization":"UNIMAS","organizationPartnerId":null,"clientMemberKey":"5afc4b28-b788-4dbf-9caf-845f31249197","guestMemberId":null}],"externalSupportMembers":[],"operationalContact":{"fullName":"Nguy\\u1EC5n Quang Tho\\u1EA1i","organization":"UNIMAS","jobTitle":"Nh\\u00E2n vi\\u00EAn","phone":"","email":"nguyenquangt